window.__D("text/zohar-hebrew-translation/c022",{"p":[[9522011880,"<p>בֹּא וּרְאֵה, נְחֹשֶׁת הַתְּנוּפָה שֶׁאָמַרְנוּ, אֵלֶּה הֵם אוֹתָם הָרֵי נְחֹשֶׁת, שֶׁנִּקְרְאוּ הָרֵי נְחֹשֶׁת, וְהֵם שֶׁנִּקְרְאוּ אַדְנֵי נְחֹשֶׁת. (ואלה) עוֹמְדִים שׁוֹעֲרִים בְּכָל אוֹתָם הַפְּתָחִים, וּמַקִּיפִים אוֹתָם, אֶת כָּל אוֹתָם שֶׁעוֹמְדִים בִּפְנִים, מִשּׁוּם שֶׁאֵלֶּה הֵם שׁוֹעֲרִים שֶׁעוֹמְדִים בַּפְּתָחִים שֶׁבַּחוּץ, וְאֵלֶּה נִכְנָסִים וְיוֹצְאִים בְּבֵית הַמֶּלֶךְ.</p>\n<p>וּמֵהַנְּחֹשֶׁת הַזּוֹ, כָּל אוֹתָם כְּלֵי הַמִּזְבֵּחַ לְשַׁמֵּשׁ בּוֹ. וְאֵלֶּה הֵם כֵּלִים לַמִּזְבֵּחַ. שֶׁכְּשֶׁנְּשָׁמוֹת קְרֵבוֹת לַעֲלוֹת עַל גַּבֵּי הַמִּזְבֵּחַ, אֵלֶּה הֵם עוֹבְדִים אוֹתָהּ עֲבוֹדַת הַמִּזְבֵּחַ, וְכֻלָּם מְסַיְּעִים לְשַׁמֵּשׁ אֶת אוֹתוֹ שִׁמּוּשׁ, וְנִקְרָאִים כְּלֵי הַמִּזְבֵּחַ. וְכָל הַכֵּלִים הַלָּלוּ וְכָל אוֹתָם יִתְדוֹת הַמִּשְׁכָּן, כֻּלָּם נִקְרְאוּ בְשֵׁמוֹת, כְּלֵי שָׁרֵת לְשַׁמֵּשׁ בַּקֹּדֶשׁ. וְעַל זֶה עוֹמְדִים כֻּלָּם מְמֻנִּים יְדוּעִים וּמֶרְכָּבוֹת יְדוּעוֹת וְרוּחוֹת יְדוּעוֹת, כָּל אֶחָד וְאֶחָד כָּרָאוּי לוֹ. וּבְהֵיכְלוֹת הַקֹּדֶשׁ, שֶׁהֵם הֵיכָלוֹת יְדוּעִים, כֻּלָּם בְּחֶשְׁבּוֹן.</p>\n<p>קֶשֶׁר הַזָּהָב - בְּזָהָב. כֶּסֶף - בְּכֶסֶף. נְחֹשֶׁת - בִּנְחֹשֶׁת. אֵלֶּה שֶׁל הַנְּחֹשֶׁת שֶׁלְּמַטָּה נוֹטְלִים כֹּחַ מִנְּחֹשֶׁת שֶׁל מַעְלָה, וְכָךְ הַכֹּל. כָּל אוֹתָם גְּוָנִים מִתְעָרְבִים אֵלֶּה בְּאֵלֶּה, לֶאֱחֹז וּלְהִתְקַשֵּׁר אֵלֶּה בְּאֵלֶּה.</p>\n<p>קַרְסֵי הַזָּהָב עוֹמְדִים לְקַשֵּׁר אוֹתָן יְרִיעוֹת אַחַת עִם אַחַת. קַרְסֵי הַנְּחֹשֶׁת עוֹמְדִים לִקְשֹׁר אֶת הַמִּשְׁכָּן. וְאֵלֶּה כְּנֶגֶד אֵלֶּה. וְכֻלָּם עוֹמְדִים כַּכּוֹכָבִים הַלָּלוּ שֶׁבָּרָקִיעַ. כְּמוֹ שֶׁמְּאִירִים הַכּוֹכָבִים בָּרָקִיעַ וְנִרְאִים, כָּךְ גַּם מְאִירִים אוֹתָם קְרָסִים בַּמִּשְׁכָּן, וַהֲרֵי בֵּאַרְנוּ. וּמְאִירִים אוֹתָם קְרָסִים וְנִרְאִים כַּכּוֹכָבִים שֶׁעוֹמְדִים וּבוֹלְטִים (ולוהטים) וְנוֹצְצִים, וְאוֹתָם חֲמִשִּׁים שֶׁל זָהָב וַחֲמִשִּׁים שֶׁל נְחֹשֶׁת, וּמִאִירִים אֵלֶּה כְּנֶגֶד אֵלֶּה.</p>\n<p>מִתּוֹךָֹ הָאוֹר שֶׁלְּמַעְלָה יוֹצֵאת הִתְנוֹצְצוּת אַחַת שֶׁנּוֹצֶצֶת וּמְאִירָה לְתוֹךְ הָאַסְפַּקְלַרְיָה שֶׁלֹּא מְאִירָה, וְאוֹתָהּ הִתְנוֹצְצוּת כְּלוּלָה מִכָּל הַגְּוָנִים שֶׁמְּאִירִים, וְנִקְרֵאת אַרְגָּמָן. וּכְשֶׁמַּכֶּה הָאַרְגָּמָן הַזֶּה בְּאוֹתוֹ אוֹר חָשׁוּךְ (תכלת), אָז יוֹצֵאת הִתְנוֹצְצוּת אַחַת אַחֶרֶת שֶׁלֹּא לוֹהֶטֶת, וּמִתְעָרְבִים זֶה בָּזֶה. וְהֵם הָיוּ לְבוּשֵׁי הַקֹּדֶשׁ שֶׁהִתְלַבֵּשׁ בָּהֶם מִיכָאֵל הַכֹּהֵן הַגָּדוֹל.</p>\n<p>וּכְשֶׁמִּתְלַבֵּשׁ בָּהֶם בְּאוֹתָם לְבוּשֵׁי כָבוֹד, אָז נִכְנָס לְשַׁמֵּשׁ בַּקֹּדֶשׁ, וְטֶרֶם יִלְבַּשׁ הַמַּלְבּוּשִׁים הַלָּלוּ לֹא יִכָּנֵס לַקֹּדֶשׁ. כְּמוֹ כֵן - (שמות כד) וַיָּבא מֹשֶׁה בְּתוֹךְ הֶעָנָן וַיַּעַל אֶל הָהָר, וְלָמַדְנוּ שֶׁהָיָה מִתְלַבֵּשׁ בֶּעָנָן. וּכְשֶׁהָיָה מִתְלַבֵּשׁ בֶּעָנָן, אָז וַיַּעַל אֶל הָהָר. וְטֶרֶם שֶׁהִתְלַבֵּשׁ בּוֹ, לֹא יָכֹל לְהִכָּנֵס פְּנִימָה. כְּמוֹ כֵן הַכֹּהֵן הַגָּדוֹל לֹא נִכְנָס לַקֹּדֶשׁ עַד שֶׁמִּתְלַבֵּשׁ בַּלְּבוּשִׁים הַלָּלוּ כְּדֵי לְהִכָּנֵס לַקֹּדֶשׁ.</p>\n<p>וּמִשּׁוּם שֶׁיָּצְאוּ מִסּוֹדוֹת עֶלְיוֹנִים וְהֵם כְּמוֹ שֶׁלְּמַעְלָה, נִקְרָאִים בִּגְדֵי שְׂרָד, מִשּׁוּם שֶׁנִּשְׁאֲרוּ מֵאוֹתָם לְבוּשִׁים עֶלְיוֹנִים, מִשּׁוּם שֶׁהָיוּ מִמַּה שֶּׁנִּשְׁאַר מֵאוֹרוֹת הַזִּיוִים הָעֶלְיוֹנִים. תְּכֵלֶת וְאַרְגָּמָן - הַגְּוָנִים שֶׁל סוֹד הַשֵּׁם הַקָּדוֹשׁ שֶׁנִּקְרָא שֵׁם שָׁלֵם, יְדֹוָ\"ד אֱלֹהִים. וְזֶהוּ סוֹד שֶׁיִּתְלַבֵּשׁ בּוֹ הַכֹּהֵן הַגָּדוֹל לְהִכָּנֵס לַקֹּדֶשׁ. תּוֹלַעַת שָׁנִי - הֵם גְּוָנִים אֲדֻמִּים. וּתְכֵלֶת וְאַרְגָּמָן, שֶׁהוּא כָּלוּל בְּתוֹךְ אוֹתָם גְּוָנִים. וּמִתּוֹךְ שֶׁהוּא מִתְלַבֵּשׁ בָּהֶם בַּלְּבוּשִׁים שֶׁל הַגְּוָנִים הַלָּלוּ, הָיָה נִכְנָס לִפְנִים וְלֹא דוֹחִים אוֹתוֹ הַחוּצָה.</p>\n<p>בֹּא וּרְאֵה, הַכֹּל נַעֲשָׂה בְּסוֹד הָאֱמוּנָה לִהְיוֹת הַכֹּל כְּמוֹ שֶׁלְּמַעְלָה, וְעַל זֶה כָּתוּב, בִּגְדֵי הַשְּׂרָד לְשָׁרֵת בַּקֹּדֶשׁ. וְנִקְרְאוּ בִּגְדֵי (קדש) שְׂרָד, מִשּׁוּם שֶׁלֹּא נִקְרָאִים קֹדֶשׁ אֶלָּא כְּשֶׁשּׁוֹרִים בּוֹ אוֹתָם הַגְּוָנִים, שֶׁכָּתוּב (ויקראטז) בִּגְדֵי קֹדֶשׁ הֵם. וְכָתוּב (ירמיהב) קֹדֶשׁ יִשְׂרָאֵל לַה' רֵאשִׁית תְּבוּאָתֹה. קֹדֶשׁ יִשְׂרָאֵל, מִשּׁוּם שֶׁבְּיִשְׂרָאֵל נִרְאִים כָּל הַגְּוָנִים, כֹּהֲנִים לְוִיִּם וְיִשְׂרָאֵל, וְאֵלֶּה הֵם הַגְּוָנִים לְהֵרָאוֹת בִּפְנִים.</p>"],[9522011881,"<p>בֹּא וּרְאֵה, אֵין נְשָׁמָה עוֹלָה לְהֵרָאוֹת לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ עַד שֶׁזּוֹכָה לְהִתְלַבֵּשׁ בִּלְבוּשׁ שֶׁל מַעְלָה לְהֵרָאוֹת שָׁם. וְכֵן כְּמוֹ זֶה לֹא יוֹרֶדֶת לְמַטָּה עַד שֶׁמִּתְלַבֶּשֶׁת בַּלְּבוּשׁ שֶׁל הָעוֹלָם הַזֶּה.</p>\n<p>כְּמוֹ כֵן הַמַּלְאָכִים הַקְּדוֹשִׁים שֶׁלְּמַעְלָה, שֶׁכָּתוּב בָּהֶם (תהלים קב) עֹשֶׂה מַלְאָכָיו רוּחוֹת מְשָׁרְתָיו אֵשׁ לֹהֵט, כְּשֶׁעוֹשִׂים שְׁלִיחוּת בָּעוֹלָם הַזֶּה, אֵין יוֹרְדִים לְמַטָּה עַד שֶׁמִּתְלַבְּשִׁים בַּלְּבוּשׁ שֶׁל הָעוֹלָם הַזֶּה, וְהַכֹּל הוּא כְּמוֹ שֶׁאוֹתוֹ מָקוֹם שֶׁהוֹלֵךְ לְשָׁם. וַהֲרֵי בֵּאַרְנוּ שֶׁנְּשָׁמָה לֹא עוֹלָה אֶלָּא בִּלְבוּשׁ שֶׁמֵּאִיר.</p>\n<p>וּבֹא רְאֵה, אָדָם הָרִאשׁוֹן, כְּשֶׁהָיָה בְּגַן עֵדֶן, הָיָה מִתְלַבֵּשׁ בִּלְבוּשׁ כְּמוֹ שֶׁלְּמַעְלָה, וְהוּא לְבוּשׁ שֶׁל אוֹר עֶלְיוֹן. כֵּיוָן שֶׁגֹּרַשׁ מִגַּן עֵדֶן וְהִצְטָרֵךְ לְגוֹנֵי הָעוֹלָם הַזֶּה, מַה כָּתוּב? (בראשית ג) וַיַּעַשׂ ה' אֱלֹהִים לְאָדָם וּלְאִשְׁתּוֹ כָּתְנוֹת עוֹר וַיַּלְבִּשֵׁם. בָּרִאשׁוֹנָה הָיוּ כָּתְנוֹת אוֹר, אוֹר שֶׁל אוֹתוֹ אוֹר עֶלְיוֹן שֶׁשִּׁמֵּשׁ בּוֹ בְּגַן עֵדֶן.</p>\n<p>מִשּׁוּם שֶׁהֲרֵי גַּן עֵדֶן, אוֹר הָעֶלְיוֹן שֶׁמֵּאִיר מְשַׁמֵּשׁ בּוֹ. וְעַל כֵּן, אָדָם הָרִאשׁוֹן, כְּשֶׁנִּכְנַס לְתוֹךְ הַגָּן, הִלְבִּישׁ אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא בַּלְּבוּשׁ שֶׁל אוֹתוֹ אוֹר וְהִכְנִיסוֹ לְשָׁם. וְאִם לֹא הֻלְבַּשׁ בָּרִאשׁוֹנָה בְּאוֹתוֹ אוֹר, לֹא יִכָּנֵס לְשָׁם. כֵּיוָן שֶׁגֹּרַשׁ מִשָּׁם, הִצְטָרֵךְ לִלְבוּשׁ אַחֵר, אָז - וַיַּעַשׂ ה' אֱלֹהִים לְאָדָם וּלְאִשְׁתּוֹ כָּתְנוֹת עוֹר. וְהַכֹּל כְּמוֹ שֶׁצָּרִיךְ. וְכָאן כְּמוֹ כֵן עָשׂוּ בִּגְדֵי שְׂרָד לְשָׁרֵת בַּקֹּדֶשׁ, לְהִכָּנֵס בַּקֹּדֶשׁ.</p>\n<p>וַהֲרֵי פֵּרְשׁוּהָ, שֶׁמַּעֲשִׂים טוֹבִים שֶׁאָדָם עוֹשֶׂה בָּעוֹלָם הַזֶּה, אוֹתָם מַעֲשִׂים מוֹשְׁכִים אוֹר שֶׁל הַזִּיו הָעֶלְיוֹן לְבוּשׁ לְהִתְתַּקֵּן בּוֹ לְאוֹתוֹ הָעוֹלָם לְהֵרָאוֹת לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. וּבְאוֹתוֹ לְבוּשׁ שֶׁלּוֹבֵשׁ, נֶהֱנֶה וְרוֹאֶה לְתוֹךְ הָאַסְפַּקְלַרְיָה הַמְּאִירָה, כְּמוֹ שֶׁנֶּאֱמַר (תהלים כז) לַחֲזוֹת בְּנֹעַם ה' וּלְבַקֵּר בְּהֵיכָלוֹ.</p>\n<p>וְעַל כֵּן הַנְּשָׁמָה מִתְלַבֶּשֶׁת בִּשְׁנֵי עוֹלָמוֹת, לִהְיוֹת לָהּ שְׁלֵמוּת בַּכֹּל - בָּעוֹלָם הַזֶּה שֶׁלְּמַטָּה וּבָעוֹלָם שֶׁלְּמַעְלָה. וְעַל זֶה כָּתוּב, (שם קמ) אַךְ צַדִּיקִים יוֹדוּ לִשְׁמֶךְ יֵשְׁבוּ יְשָׁרִים אֶת פָּנֶיךְ. אַךְ צַדִּיקִים יוֹדוּ לִשְׁמֶךְ - בָּעוֹלָם הַזֶּה. יֵשְׁבוּ יְשָׁרִים אֶת פָּנֶיךְ - בְּאוֹתוֹ עוֹלָם.</p>\n<p>וַיַּעַשׂ אֶת הָאֵפוֹד זָהָב, הֲרֵי פֵּרְשׁוּהָ. אָמַר רַבִּי יוֹסֵי, אֵפוֹד וְחֹשֶׁן הָיוּ כְאֶחָד, וּפֵרְשׁוּהָ שֶׁהֲרֵי בִּמְקוֹם אוֹתוֹ הַקִּיּוּם עוֹמְדִים כָּל אוֹתָן שְׁתֵּים עֶשְׂרֵה אֲבָנִים, כֻּלָּם נוֹטְלִים שְׁמוֹת בְּנֵי יִשְׂרָאֵל, וְכֻלָּם שְׁנֵים עָשָׂר תְּחוּמִים עֶלְיוֹנִים, כֻּלָּם הֵם בְּסוֹד שֶׁל שִׁבְטֵי יִשְׂרָאֵל.</p>\n<p>וְסוֹד זֶה כָּתוּב, (שם קכב) שֶׁשָּׁם עָלוּ שְׁבָטִים שִׁבְטֵי יָהּ עֵדוּת לְיִשְׂרָאֵל לְהֹדוֹת לְשֵׁם ה'. שֶׁשָּׁם עָלוּ שְׁבָטִים - אֵלּוּ שְׁנֵים עָשָׂר שְׁבָטִים עֶלְיוֹנִים לְמַעְלָה, שֶׁהֵם שִׁבְטֵי יָהּ, שֶׁהֲרֵי שֵׁם זֶה עֵדוּת לְיִשְׂרָאֵל.</p>"],[9522011882,"<p>אָמַר רַבִּי חִיָּיא, פַּעֲמַיִם כָּתוּב שְׁבָטִים. אֶלָּא, שֶׁשָּׁם עָלוּ שְׁבָטִים - אֵלּוּ הַשְּׁבָטִים שֶׁלְּמַטָּה. שִׁבְטֵי יָהּ - אֵלּוּ הַשְּׁבָטִים שֶׁלְּמַעְלָה. עֵדוּת לְיִשְׂרָאֵל - זֶה הַשֵּׁם הַקָּדוֹשׁ הָעֶלְיוֹן הַזֶּה שֶׁנִּקְרָא עֵדוּת, כְּמוֹ שֶׁנֶּאֱמַר (שם קלב) וְעֵדתִי זוֹ אֲלַמְּדֵם. וְאוֹתָם שְׁנֵים עָשָׂר שְׁבָטִים קְדוֹשִׁים עֶלְיוֹנִים הֵם שְׁתֵּים עֶשְׂרֵה אֲבָנִים קְדוֹשׁוֹת, וְלָכֵן הֵם עוֹמְדִים לְמַטָּה כְּמוֹ שֶׁלְּמַעְלָה, וְכָל אוֹתָם שֵׁמוֹת שֶׁל שְׁנֵים עָשָׂר הַשְּׁבָטִים, כֻּלָּם חֲקוּקִים בְּאוֹתָן אֲבָנִים, וְהַכֹּהֵן הַגָּדוֹל נוֹטֵל אוֹתָם.</p>\n<p>בֹּא וּרְאֵה, כְּשֶׁיַּעֲקֹב הָיָה הוֹלֵךְ לְחָרָן, מַה כָּתוּב? (בראשית כח) וַיִּקַּח מֵאַבְנֵי הַמָּקוֹם וַיָּשֶׂם מְרַאֲשּתָיו. אֵלּוּ שְׁתֵּים עֶשְׂרֵה אֲבָנִים קְדוֹשׁוֹת, וְכֻלָּן נַעֲשׂוּ אֶבֶן אַחַת, שֶׁכָּתוּב וְהָאֶבֶן הַזֹּאת אֲשֶׁר שַׂמְתִּי מַצֵּבָה. וְקוֹרֵא לָהֶן אֶבֶן, מָה הַטַּעַם? מִשּׁוּם שֶׁכָּל שְׁתֵּים עֶשְׂרֵה הָאֲבָנִים נִכְלְלוּ בְּאֶבֶן קְדוֹשָׁה עֶלְיוֹנָה אַחַת, שֶׁהִיא מֵעֲלֵיהֶן, שֶׁכָּתוּב וְהָאֶבֶן הַזֹּאת אֲשֶׁר שַׂמְתִּי מַצֵּבָה יִהְיֶה בֵּית אֱלֹהִים.</p>\n<p>וְלָכֵן כָּאן הַכֹּהֵן הַגָּדוֹל הָיָה שָׂם אוֹתָן עַל לִבּוֹ לְזָכְרָם תָּמִיד, שֶׁכָּתוּב (שמות כח) וְנָשָׂא אַהֲרֹן אֶת שְׁמוֹת בְּנֵי יִשְׂרָאֵל עַל לִבּוֹ לִפְנֵי ה' תָּמִיד. וּמִשּׁוּם כָּךְ הַכֹּל הוּא בְּסוֹד שֶׁל שְׁנֵים עָשָׂר, שְׁנֵים עָשָׂר עֶלְיוֹנִים טְמִירִים לְמַעְלָה שֶׁנִּגְנְזוּ בְּסוֹד עֶלְיוֹן קָדוֹשׁ, וְהֵם הַסּוֹד שֶׁל הַתּוֹרָה, וְיוֹצְאִים מִקּוֹל דַּק אֶחָד, וַהֲרֵי פֵּרְשׁוּהָ. שְׁנֵים עָשָׂר אֲחֵרִים טְמִירִים לְמַטָּה כְּמוֹ שֶׁהֵם, וְיוֹצְאִים תּוֹךְ קוֹל אַחֵר שֶׁהִיא אֶבֶן, שֶׁכָּתוּב (בראשיתמט) מִשָּׁם רֹעֶה אֶבֶן יִשְׂרָאֵל.</p>\n<p>וְלָכֵן פֵּרְשׁוּהָ בְּסוֹד הַכָּתוּב, (שם כט) וְנֶאֶסְפוּ שָׁמָּה כָל הָעֲדָרִים וְגָלֲלוּ אֶת הָאֶבֶן. זוֹ הַשְּׁכִינָה שֶׁנִּקְרֵאת אֶבֶן בֹּחַן, אֶבֶן יִשְׂרָאֵל. שֶׁגּוֹלְלִים אוֹתָהּ וּמַכְנִיסִים אוֹתָהּ לַגָּלוּת, וְכָתוּב וְהֵשִׁיבוּ אֶת הָאֶבֶן עַל פִּי הַבְּאֵר לִמְקוֹמָהּ, וְעַל שְׁמָהּ נִקְרָאִים כָּל הָאֲבָנִים.</p>\n<p>וְכַמָּה אֲבָנִים לַאֲבָנִים. יֵשׁ אֲבָנִים וְיֵשׁ אֲבָנִים. יֵשׁ אֲבָנִים יְסוֹדֵי הַבַּיִת, שֶׁכָּתוּב (מלכים א ה) וַיְצַו הַמֶּלֶךְ וַיַּסִּעוּ אֲבָנִים גְּדלוֹת אֲבָנִים יְקָרוֹת לְיַסֵּד הַבָּיִת אַבְנֵי גָזִית. וְיֵשׁ אֲבָנִים עֶלְיוֹנוֹת נִכְבָּדוֹת, וְהֵן (אלו) שְׁתֵּים עֶשְׂרֵה, וְהֵן אַרְבַּע מַעֲרָכוֹת, שָׁלֹשׁ שָׁלֹשׁ לְכָל מַעֲרָכָה לְאַרְבָּעָה רוּחוֹת הָעוֹלָם. כְּמוֹ כֵן אוֹתָם אַרְבָּעָה דְגָלִים שֶׁהָיוּ הוֹלְכִים בַּמִּדְבָּר, וְהֵם שְׁנֵים עָשָׂר שְׁבָטִים, שְׁלֹשָׁה שְׁלֹשָׁה לְכָל צַד לְאַרְבָּעָה רוּחוֹת הָעוֹלָם. וְהַכֹּל סוֹד אֶחָד, וַהֲרֵי פֵּרְשׁוּהָ.</p>\n<p>וּבֹא רְאֵה, בְּשָׁעָה שֶׁהַכֹּהֵן הַגָּדוֹל הָיָה שָׂם אֶת שְׁתֵּים עֶשְׂרֵה הָאֲבָנִים הַלָּלוּ וְלוֹבֵשׁ אוֹתָן בְּחֹשֶׁן וְאֵפוֹד, אָז שָׁרְתָה עָלָיו שְׁכִינָה, וְאוֹתָן שְׁתֵּים עֶשְׂרֵה אֲבָנִים חֲקוּקוֹת בִּשְׁמוֹת כָּל הַשְּׁבָטִים, וְכָל שֵׁבֶט וְשֵׁבֶט חָקוּק עַל אֶבֶן אַחַת. שְׁקוּעוֹת הָיוּ הָאוֹתִיּוֹת עַל הָאֲבָנִים, וּכְשֶׁהֵאִירוּ הָאֲבָנִים, הָיוּ הָאוֹתִיּוֹת בּוֹלְטוֹת הַחוּצָה וּמְאִירוֹת עַל מַה שֶּׁהִצְטָרְכוּ.</p>\n<p>(ובאותיות השבטים) וּבְכָל הַשְּׁבָטִים לֹא הָיוּ שְׁתֵּי הָאוֹתִיּוֹת ח' ט', בִּשְׁבִיל שֶׁלֹּא נִמְצָא חֵטְ\"א בְּכֻלָּם. אָמַר רַבִּי חִזְקִיָּה, אִם כָּךְ, ח' שֶׁהַשֵּׁם גּוֹרֵם - נָאֶה. אֲבָל ט', שֶׁהִיא אוֹת טוֹבָה, וְשָׁנִינוּ, מִי שֶׁרוֹאֶה ט' בַּחֲלוֹמוֹ טוֹב לוֹ, מִשּׁוּם שֶׁבָּהּ פָּתְחָה תוֹרָה כִּי טוֹב, שֶׁכָּתוּב (בראשית א) וַיַּרְא אֱלֹהִים אֶת הָאוֹר כִּי טוֹב, וְהוֹאִיל וְהִיא אוֹת טוֹבָה, לָמָּה לֹא נִכְתְּבָה בְּאוֹתָם שְׁבָטִים?</p>\n<p>אָמַר לוֹ, מִשּׁוּם שֶׁסְּמוּכוֹת שְׁתֵּי הָאוֹתִיּוֹת זוֹ לָזוֹ. וְעוֹד, שֶׁהֲרֵי הָאוֹת ט' גְּנוּזָה וּטְמִירָה, וְהִיא מְאִירָה אֶת הָאוֹר שֶׁל כֻּלָּם, שֶׁהֲרֵי אוֹת זוֹ הִיא הָאוֹר שֶׁל כֻּלָּם, וְאֵין אוֹר נִמְצָא חוּץ מֵהָאוֹת הַזּוֹ, שֶׁכָּתוּב וַיַּרְא אֱלֹהִים אֶת הָאוֹר כִּי טוֹב. וְהוּא הָאוֹר שֶׁל אוֹתוֹ הָאוֹר שֶׁגָּנוּז וְטָמִיר. וְעַל זֶה כָּתוּב, (תהלים פד) לֹא יִמְנַע טוֹב לַהוֹלְכִים בְּתָמִים. וְזֶהוּ הָאוֹר שֶׁל כָּל הַשְּׁבָטִים. וּמִשּׁוּם כָּךְ לֹא נֶחְקְקָה בָהֶן. וְעוֹד, שֶׁכָּל הַשְּׁתֵּים עֶשְׂרֵה יוֹצְאוֹת מִתּוֹךְ הָאַכְסַדְּרָה הַזּוֹ הַטְּמִירָה שֶׁהִיא בְּסוֹד הָאוֹת ט', וּמִשּׁוּם כָּךְ הִיא טְמִירָה וּגְנוּזָה וְאֵינָהּ נִרְאֵית בָּהֶן.</p>\n<p>בֹּא וּרְאֵה, כָּל אוֹתָן אֲבָנִים עוֹמְדוֹת בְּדֶרֶךְ אוֹת וָנֵס, וְכֻלָּן כְּשֶׁהֵאִירוּ, אָז פְּנֵי הַכֹּהֵן הַגָּדוֹל הָיוּ מְאִירוֹת, וְהָאוֹתִיּוֹת מְאִירוֹת וּבוֹלְטוֹת לְהוֹדִיעַ לַחוּץ. וּכְשֶׁהָיוּ מְאִירִים פְּנֵי הַכֹּהֵן, אָז הָיוּ נוֹדָעוֹת בְּלִיטוֹת הָאוֹתִיּוֹת שֶׁהוּא לְטוֹב, וּבָזֶה נוֹדַע הַכֹּהֵן אִם צַדִּיק הָאִישׁ אִם לֹא. וְעַל כָּךְ הַכֹּל הוּא בְּאוֹת וָנֵס, וַהֲרֵי פֵּרְשׁוּהָ.</p>\n<p>רַבִּי אַבָּא הָיָה מָצוּי לִפְנֵי רַבִּי שִׁמְעוֹן. אָמַר לוֹ, זֶה שֶׁכָּתוּב (שמות כח) וְנָתַתָּ אֶל חֹשֶׁן הַמִּשְׁפָּט אֶת הָאוּרִים וְאֶת הַתֻּמִּים. וְשָׁנִינוּ, אוּרִים - שֶׁמְּאִירִים בַּדָּבָר שֶׁהִצְטָרְכוּ. תֻּמִּים - שֶׁהָיוּ שְׁלֵמִים בְּדִבְרֵיהֶם. עוֹד אָנוּ צְרִיכִים לָדַעַת. (הסוד הזה)</p>\n<p>אָמַר לוֹ, וַדַּאי, וְכָךְ הוּא, חֹשֶׁן וְאֵפוֹד כְּנֶגֶד אוּרִים וְתֻמִּים, וְזֶהוּ סוֹד הַתְּפִלִּין וְקֶשֶׁר הַתְּפִלִּין כְּנֶגֶד שְׁנֵי אֵלֶּה. פָּתַח וְאָמַר, (שם לג) וְרָאִיתָ אֶת אֲחֹרָי וּפָנַי לֹא יֵרָאוּ. וְרָאִיתָ אֶת אֲחֹרָי, הֲרֵי שָׁנִינוּ שֶׁהֶרְאָה לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לְמֹשֶׁה קֶשֶׁר שֶׁל תְּפִלִּין. וּפָנַי - אֵלֶּה תְּפִלִּין מַמָּשׁ. וּפָנַי הֵם תְּפִלִּין, שֶׁהֵן סוֹד עֶלְיוֹן הַשֵּׁם הַקָּדוֹשׁ. אֲחֹרָי - הוּא סוֹד קֶשֶׁר הַתְּפִלִּין. וַהֲרֵי יָדוּעַ לַחֲבֵרִים. מִשּׁוּם שֶׁזּוֹ אַסְפַּקְלַרְיָה הַמְּאִירָה, וְזוֹ אַסְפַּקְלַרְיָה שֶׁאֵינָהּ מְאִירָה.</p>\n<p>כְּנֶגֶד זֶה, אוּרִים - שֶׁמְּאִירִים בְּדִבְרֵיהֶם. תֻּמִּים - שֶׁמֻּשְׁלָמִים בְּדִבְרֵיהֶם. זֶה פָּנִים וְזֶה אָחוֹר. וְסוֹד זֶה - קוֹל וְדִבּוּר. הַקּוֹל מֵאִיר לַדִּבּוּר לְדַבֵּר, הַדִּבּוּר מַשְׁלִים אֶת הַדָּבָר. וְתָמִיד זֶה בָּזֶה עוֹלִים וְלֹא נִפְרָדִים זֶה מִזֶּה לְעוֹלָמִים. מִשּׁוּם כָּךְ חֹשֶׁן וְאֵפוֹד, זֶה פָּנִים וְזֶה אָחוֹר, וְהַכֹּל סוֹד אֶחָד בְּלִי הֶבְדֵּל כְּלָל.</p>\n<p>אָמַר לוֹ, אִם כָּךְ שֶׁאֵינָם נִפְרָדִים לְעוֹלָמִים, וּמִי שֶׁהִפְרִידָם, הֲרֵי שָׁנִינוּ, שֶׁכָּתוּב (משלי טז) מַפְרִיד אַלּוּף, מַה זֶּה שֶׁכָּתוּב (שמואל א כג) וַיְהִי בִּבְרֹחַ אֶבְיָתָר בֶּן אֲחִימֶלֶךְ אֶל דָּוִד קְעִילָה אֵפוֹד יָרַד בְּיָדוֹ, וְאִלּוּ חֹשֶׁן לֹא נֶאֱמַר?</p>\n<p>אָמַר לוֹ, וַדַּאי כָּךְ הוּא. כָּל מַה שֶּׁהוּא חָשׁוּב, הוּא טָמִיר וְגָנוּז, וְלֹא נִזְכָּר כָּל כָּךְ. כְּמוֹ כֵן נוֹשְׂאֵי אֵפוֹד בַּד - מַה שֶּׁהוּא בְּגָלוּי יוֹתֵר, הוּא נִזְכָּר, בִּשְׁבִיל שֶׁמִּתְכַּסֶּה מַה שֶּׁהוּא בִּגְנִיזוּת וּטְמִירוּת, וְעַל כֵּן נִזְכָּר מַה שֶּׁהוּא בְּגָלוּי יוֹתֵר.</p>\n<p>וּמִשּׁוּם כָּךְ הַשֵּׁם הָעֶלְיוֹן הוּא סוֹד בִּטְמִירוּת וּגְנִיזוּת, וְלֹא נִזְכָּר אֶלָּא בַּשֵּׁם שֶׁהוּא בְּהִתְגַּלּוּת. זֶה נִזְכָּר, וְזֶה נִגְנָז. זֶה בְּגִלּוּי וְזֶה בְּנִסְתָּר. וְכָל מַה שֶּׁהִתְגַּלָּה, הוּא נִזְכָּר לְעוֹלָמִים. הַשֵּׁם הַגָּנוּז הוּא יְהֹוָ\"ה. הַשֵּׁם שֶׁהוּא בְּהִתְגַּלּוּת הוּא אֲדנָ\"י, וְעַל זֶה נִכְתָּב בְּאוֹתִיּוֹת טְמִירוֹת וְנִקְרָא בָּאוֹתִיּוֹת הַלָּלוּ וְנִתְכַּסָּה זֶה בָּזֶה, לִהְיוֹת הַכָּבוֹד הָעֶלְיוֹן טָמִיר וְגָנוּז לְעוֹלָמִים. שֶׁכָּל דַּרְכֵי הַתּוֹרָה כָּךְ הֵם - גָּלוּי וְנִסְתָּר. וְכָל דִּבְרֵי הָעוֹלָם, בֵּין שֶׁל הָעוֹלָם הַזֶּה וּבֵין שֶׁל הָעוֹלָם שֶׁלְּמַעְלָה, כֻּלָּם טְמִירִים וּגְלוּיִים.</p>\n<p>פָּתַח וְאָמַר, (יונה א) וַיֹּאמְרוּ אֵלָיו הַגִּידָה נָּא לָנוּ בַּאֲשֶׁר לְמִי הָרָעָה הַ את לָנוּ וְגוֹ'. בַּפָּסוּק הַזֶּה יֵשׁ לְהִתְבּוֹנֵן, כֻּלָּם שָׁאֲלוּ בְּסוֹד הַחָכְמָה, שֶׁכָּתוּב הַגִּידָה נָּא לָנוּ בַּאֲשֶׁר לְמִי. בַּאֲשֶׁר - שָׁאֲלוּ בְּסוֹד הַחָכְמָה. כָּאן שָׁאֲלוּ סוֹד שֶׁהוּא בְּנִגְלֶה, לָדַעַת אִם בָּא מִזַּרְעוֹ שֶׁל יוֹסֵף, שֶׁכֵּיוָן שֶׁרָאָה הַיָּם אֶת אֲרוֹנוֹ, מִיָּד נִבְקַע וְהָיָה יַבָּשָׁה, שֶׁכָּתוּב (תהלים קיד) הַיָּם רָאָה וַיָּנֹס. הַיָּם רָאָה אֶת אוֹתוֹ שֶׁכָּתוּב בּוֹ (בראשית לט) וַיָּנָס וַיֵּצֵא הַחוּצָה. מִיָּד - הַיַּרְדֵּן יִסֹּב לְאָחוֹר.</p>\n<p>וְעַל כֵּן שָׁאֲלוּ אוֹתוֹ בַּאֲשֶׁר, שֶׁכָּתוּב בּוֹ בְּיוֹסֵף, בַּאֲשֶׁר אַתְּ אִשְׁתּוֹ. אִם בָּאתָ מֵאוֹתוֹ הַזֶּרַע, הִתְפַּלֵּל שֶׁיִּשְׁתֹּק הַיָּם מֵאִתָּנוּ. לְמִי - וְאִם בָּאתָ מִזַּרְעוֹ שֶׁל יַעֲקֹב, שֶׁכָּתוּב בּוֹ (שם לב) לְמִי אַתָּה וְאָנָה תֵלֵךְ. וְהֵם הָיוּ מַלְאָכִים קְדוֹשִׁים שֶׁשָּׁלַח בִּשְׁלִיחוּתוֹ וְנִצַּל מֵאוֹתָהּ צָרָה. הִתְפַּלֵּל לְרִבּוֹנְךְ, וְיִשְׁלַח מַלְאָכוֹ וְנִנָּצֵל מֵאוֹתָהּ צָרָה.</p>\n<p>וְאִם לֹא, מַה מְּלַאכְתְּךְ - בַּמָּה אַתָּה מִתְעַסֵּק בְּכָל יוֹם? וּמֵאַיִן תָּבוֹא - מִי הֵם אֲבוֹתֶיךְ? מָה אַרְצֶךְ - אִם הִיא אֶרֶץ שֶׁרְאוּיָה לְהֵעָנֵשׁ. וְאֵי מִזֶּה עַם אָתָּה - אִם הוּא עֲמָלֵק אוֹ אֶחָד מִשִּׁבְעָה עֲמָמִים שֶׁרְאוּיִים לְהֵעָנֵשׁ. הַכֹּל שָׁאֲלוּ אוֹתוֹ כָּרָאוּי.</p>\n<p>מַה הֵשִׁיב לָהֶם? וַיֹּאמֶר לָהֶם עִבְרִי אָנֹכִי, מֵאוֹתוֹ זֶרַע שֶׁל אַבְרָהָם הָעִבְרִי שֶׁקִּדֵּשׁ אֶת שֵׁם רִבּוֹנוֹ בְּכָל יוֹם בָּעוֹלָם. וְאֶת ה' אֱלֹהֵי הַשָּׁמַיִם אֲנִי יָרֵא וְגוֹ'. הֵם לֹא שָׁאֲלוּ אוֹתוֹ אֶלָּא דָּבָר בַּנִּגְלֶה וּבַנִּסְתָּר לָדַעַת בּוֹ, וְהוּא הֵשִׁיב לָהֶם הַכֹּל בְּנִגְלֶה.</p>\n<p>מַה כָּתוּב? וַיִּירְאוּ הָאֲנָשִׁים יִרְאָה גְדוֹלָה. כֵּיוָן שֶׁשָּׁמְעוּ אֶת שְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, מִיָּד פָּחֲדוּ, מִשּׁוּם שֶׁכֻּלָּם הָיוּ יוֹדְעִים אֶת הַנִּסִּים וְהַגְּבוּרוֹת שֶׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא בַּיָּם. וְכֵיוָן שֶׁאָמַר לָהֶם אֶת שְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, מִיָּד פָּחֲדוּ לְפָנָיו פַּחַד רַב. עוֹד אָמַר לָהֶם שֶׁהוּא בּוֹרֵחַ מִלִּפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְעַל כֵּן אָמְרוּ לוֹ, מַה זֹּאת עָשִׂיתָ שֶׁאַתָּה בָּרַחְתָּ מִפָּנָיו וְלֹא עָשִׂיתָ מִצְווֹתָיו. וּמִשּׁוּם כָּךְ מַה את עָשִׂיתָ שֶׁאַתָּה עָבַרְתָּ עַל מִצְווֹת רִבּוֹנְךְ.</p>\n<p>וּבֹא רְאֵה, כָּל אֵלּוּ שֶׁהִתְגַּיְּרוּ אַחַר כָּךְ, כְּשֶׁרָאוּ אֶת הַנִּסִּים וְהַגְּבוּרוֹת שֶׁעָשָׂה לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לְיוֹנָה בַּיָּם, וְכֻלָּם רָאוּ אוֹתוֹ כְּשֶׁנּוֹפֵל בַּיָּם, וְאוֹתוֹ דָּג שֶׁעוֹלֶה וּבוֹלֵעַ אוֹתוֹ לִפְנֵיהֶם, וּכְשֶׁבָּא אוֹתוֹ דָּג גָּדוֹל לְעֵינֵי הַכֹּל וּפָלַט אוֹתוֹ לַיַּבָּשָׁה, בָּאוּ אֵלָיו וְהִתְגַּיְּרוּ כֻלָּם. זֶהוּ שֶׁכָּתוּב (יונה ב) מְשַׁמְּרִים הַבְלֵי שָׁוְא חַסְדָּם יַעֲזבוּ.</p>\n<p>וּבֹא רְאֵה, כָּל אֵלֶּה הָיוּ גֵרֵי צֶדֶק, וְהִתְחַכְּמוּ בַתּוֹרָה, וְהָיוּ חֲכָמִים עֶלְיוֹנִים. מִשּׁוּם שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא הִתְרַצָּה בָהֶם, וּבְכָל אֵלּוּ שֶׁקָּרְבוּ אֵלָיו וּמְקַדְּשִׁים אֶת שְׁמוֹ בְּגָלוּי, שֶׁכַּאֲשֶׁר מִתְקַדֵּשׁ שְׁמוֹ בְּגָלוּי, שְׁמוֹ הַנִּסְתָּר מִתְעַלֶּה עַל כִּסֵּא כְבוֹדוֹ, שֶׁכָּתוּב (ויקרא כב) וְנִקְדַּשְׁתִּי בְּתוֹךְ בְּנֵי יִשְׂרָאֵל.</p>\n<p>(בא וראה מה כתוב) (שמות לט) וַיִּרְכְּסוּ אֶת הַחֹשֶׁן מִטַּבְּעֹתָיו אֶל טַבְּעֹת הָאֵפֹד בִּפְתִיל תְּכֵלֶת. לָמָּה בִּפְתִיל תְּכֵלֶת? אֶלָּא לְהַרְאוֹת שֶׁהַתְּכֵלֶת הַזּוֹ נִקְשֶׁרֶת בַּכֹּל, וְעַל זֶה הַכֹּל הוּא בְּסוֹד עֶלְיוֹן.</p>\n<p>מַה כָּתוּב? (שם כח) פַּעֲמוֹן זָהָב וְרִמּוֹן, וּבֵאַרְנוּ שֶׁהַכֹּל בְּסוֹד עֶלְיוֹן כְּפִי שֶׁאָמַרְנוּ. מַה כָּתוּב? וְנִשְׁמַע קוֹלוֹ בְּבאוֹ אֶל הַקֹּדֶשׁ לִפְנֵי ה'. מִשּׁוּם שֶׁצָּרִיךְ קוֹל שֶׁנִּשְׁמָע, וְהַבְּרָכוֹת יִשְׁרוּ עַל הָעוֹלָם בִּשְׁבִיל הַכֹּהֵן, שֶׁהוּא מְבָרֵךְ אֶת הַכֹּל וְעוֹבֵד הַכֹּל. פַּעֲמוֹן זָהָב, הֲרֵי בֵּאַרְנוּ. רִמּוּן, שֶׁמִּתְמַלֵּא כְּמוֹ הָרִמּוֹן הַזֶּה שֶׁהוּא מָלֵא מֵהַכֹּל, וְהַכֹּל בֵּאַרְנוּ.</p>\n<p>וַיַּעַשׂ אֶת מְעִיל הָאֵפֹד מַעֲשֵׂה אֹרֵג כְּלִיל תְּכֵלֶת. הֲרֵי נִתְבָּאֵר בְּסוֹד הַחֹשֶׁן וְהָאֵפוֹד, וְהַכֹּל אֶחָד. כְּלִיל תְּכֵלֶת, שֶׁכָּךְ רָאוּי כְּמוֹ שֶׁבֵּאַרְנוּ, שֶׁתְּכֵלֶת הוּא סוֹד שֶׁל אוֹר הַכִּסֵּא. תְּכֵלֶת שֶׁהוּא בְּקֶשֶׁר שֶׁל אוֹר לָבָן, הַכֹּל כְּאֶחָד. וְעַל זֶה הַתְּכֵלֶת הוּא לָאֵפוֹד.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, הַלְּבוּשִׁים הַלָּלוּ שֶׁל הַכֹּהֵן, כֻּלָּם הֵם בְּסוֹד עֶלְיוֹן, לִהְיוֹת לְבוּשִׁים שֶׁלְּמַטָּה כְּמוֹ שֶׁלְּמַעְלָה. בֹּא וּרְאֵה, כֵּיוָן שֶׁמִּיכָאֵל הוּא כֹּהֵן גָּדוֹל וּבָא מִצַּד הַיָּמִין, לָמָּה כָּתוּב בְּגַבְרִיאֵל, (דניאל יב) הָאִישׁ לְבוּשׁ הַבַּדִּים? שֶׁהֲרֵי הַלְּבוּשִׁים הֵם לַכֹּהֵן הַגָּדוֹל, וּמִיכָאֵל הוּא הַכֹּהֵן, וּבָא מִצַּד הַיָּמִין? אֶלָּא מִכָּאן שֶׁשְּׂמֹאל נִכְלָל בַּיָּמִין תָּמִיד, וְהִתְלַבֵּשׁ גַּבְרִיאֵל בַּלְּבוּשִׁים הַלָּלוּ.</p>\n<p>עוֹד, שֶׁהֲרֵי גַּבְרִיאֵל הִתְמַנָּה שָׁלִיחַ בָּעוֹלָם הַזֶּה, וְכָל שָׁלִיחַ שֶׁהִתְמַנָּה בָּעוֹלָם הַזֶּה, צָרִיךְ לְהִתְלַבֵּשׁ בִּלְבוּשֵׁי הָעוֹלָם הַזֶּה, וַהֲרֵי בֵּאַרְנוּ בְּסוֹד הַנְּשָׁמָה, כְּשֶׁהִיא עוֹלָה לְמַעְלָה הִיא מִתְלַבֶּשֶׁת בִּלְבוּשׁ כְּמוֹ שֶׁלְּמַעְלָה, כְּדֵי לִהְיוֹת שָׁם. וְכֵן כְּשֶׁיּוֹרֶדֶת לְמַטָּה מִלְמַעְלָה, הַכֹּל הוּא כְּמוֹ שֶׁאוֹתוֹ מָקוֹם שֶׁהוֹלֶכֶת לְשָׁם. כְּמוֹ כֵן כָּל אוֹתָם שְׁלוּחִים שֶׁהִתְמַנּוּ בִּשְׁלִיחוּת בָּעוֹלָם הַזֶּה, וַהֲרֵי בֵּאַרְנוּ.</p>\n<p>וּבֹא רְאֵה, הַמְּעִיל הַזֶּה שֶׁל הָאֵפוֹד - לְכַסּוֹת עָלָיו כְּשֶׁלּוֹבֵשׁ אוֹתוֹ. כָּתוּב (תהלים קלט) אָחוֹר וָקֶדֶם צַרְתָּנִי וַתָּשֶׁת עָלַי כַּפֶּכָה. פָּסוּק זֶה הֲרֵי פֵּרְשׁוּהוּ.</p>\n<p>אֲבָל בֹּא וּרְאֵה, בְּשָׁעָה שֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת אָדָם הָרִאשׁוֹן, זָכָר וּנְקֵבָה נִבְרְאוּ, וְהָיוּ שְׁנֵיהֶם זֶה עִם זֶה קְשׁוּרִים, הַנְּקֵבָה לְאָחוֹר וְהַזָּכָר לִפְנִים, עַד שֶׁנִּסֵּר אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא, וְהִתְקִין אוֹתָהּ וְהִכְנִיס אוֹתָהּ לִפְנֵי אָדָם לְהִסְתַּכֵּל פָּנִים בְּפָנִים. וְכֵיוָן שֶׁהִסְתַּכְּלוּ פָּנִים בְּפָנִים, אָז רָבְתָה הָאַהֲבָה בָּעוֹלָם, וְהוֹלִידוּ תוֹלָדוֹת בָּעוֹלָם, מַה שֶּׁלֹּא הָיָה מִקֹּדֶם לָכֵן, וַהֲרֵי בֵּאַרְנוּ.</p>\n<p>וְאַחַר שֶׁחָטָא אָדָם וְהָאִשָּׁה, וּבָא נָחָשׁ עַל חַוָּה וְהִטִּיל בָּהּ זֻהֲמָה, הוֹלִידָה חַוָּה אֶת קַיִן, וְהָיָה דְּיוֹקְנוֹ דְּיוֹקָן שֶׁלְּמַעְלָה וּמַטָּה מִסּוֹד הַזֻּהֲמָה שֶׁל הַצַּד הָאַחֵר וּמֵהַצַּד שֶׁלְּמַטָּה. וְעַל כֵּן הוּא הָיָה הָרִאשׁוֹן שֶׁעָשָׂה מָוֶת בָּעוֹלָם, מִשּׁוּם שֶׁהַצַּד שֶׁלּוֹ גָּרַם. הַנָּחָשׁ דַּרְכּוֹ הוּא לֶאֱרֹב לַהֲרֹג, אוֹתוֹ שֶׁבָּא מִמֶּנּוּ בְּדַרְכּוֹ לָקַח וְהָלַךְ. וְעַל זֶה כָּתוּב (בראשית ד) וַיְהִי בִּהְיוֹתָם בַּשָּׂדֶה וַיָּקָם קַיִן אֶל הֶבֶל אָחִיו וַיַּהַ רְגֵהוּ.</p>\n<p>מָצָאנוּ בְּסִפְרֵי הַקַּדְמוֹנִים, שֶׁכְּשֶׁהָרַג קַיִן אֶת הֶבֶל, הָיָה נוֹשֵׁךְ אוֹתוֹ נְשִׁיכוֹת כַּנָּחָשׁ, עַד שֶׁהוֹצִיא אֶת נִשְׁמָתוֹ וְהָרַג אוֹתוֹ.</p>\n<p>וְכָל הַדְּבָרִים חָזְרוּ לַיְסוֹד הָרִאשׁוֹן, וְאִם קַיִן לֹא הָיָה מִן אוֹתוֹ הַצַּד, לֹא נִמְצָא כָּךְ לְאָחִיו. וְעַל כֵּן, כֵּיוָן שֶׁרָאָה אָדָם שֶׁנֶּהֱרַג הֶבֶל וְגֹרַשׁ קַיִן, אָמַר: מָה אֲנִי אוֹלִיד מִכָּאן וָהָלְאָה. נִפְרַד מֵאִשְׁתּוֹ מֵאָה וּשְׁלֹשִׁים שָׁנָה, וְרוּחוֹת נְקֵבוֹת טְמֵאוֹת הָיוּ בָאוֹת וּמִתְחַמְּמוֹת מִמֶּנּוּ, וְהָיָה מוֹלִיד רוּחוֹת וְשֵׁדִים, וְנִקְרָאִים נִגְעֵי בְּנֵי אָדָם, וּבֵאַרְנוּ.</p>\n<p>אַחַר כָּךְ קִנֵּא וְהִתְלַבֵּשׁ בְּקִנְאָה, וְהִתְחַבֵּר בְּאִשְׁתּוֹ וְהוֹלִיד אֶת שֵׁת, שֶׁכָּתוּב (בראשית ה) וַיּוֹלֶד בִּדְמוּתוֹ כְּצַלְמוֹ וַיִּקְרָא אֶת שְׁמוֹ שֵׁת. זֶהוּ בִּדְמוּתוֹ כְּצַלְמוֹ, מַה שֶּׁלֹּא הָיָה כָּךְ בָּרִאשׁוֹנָה, בְּאוֹתָם בָּנִים רִאשׁוֹנִים שֶׁהָיוּ מִקֹּדֶם לָכֵן.</p>\n<p>מִשּׁוּם שֶׁהֲרֵי בָּרִאשׁוֹנָה הִתְחַבְּרוּת אַחֶרֶת הָיְתָה אֵלָיו, וּפֵרְשׁוּהָ, עַד שֶׁבָּאָה חַוָּה וְהִתְקִינָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא לְאָדָם, וְהִתְחַבְּרוּ פָּנִים בְּפָנִים. וְעַל זֶה כָּתוּב, (שם ב) לְזֹאת יִקָּרֵא אִשָּׁה. זוֹהִי אִשָּׁה, אֲבָל אַחֶרֶת לֹא נִקְרֵאת כָּךְ, וַהֲרֵי פֵּרְשׁוּהָ.</p>\n<p>וּמִשּׁוּם שֶׁאָדָם וְחַוָּה נִבְרְאוּ כְאֶחָד, כָּתוּב (שם ה) זָכָר וּנְקֵבָה בְּרָאָם וַיְבָרֶךְ אֹתָם. שְׁנֵיהֶם כְּאֶחָד הָיוּ. וְעַל זֶה כָּתוּב, אָחוֹר וָקֶדֶם צַרְתָּנִי.</p>\n<p>בֹּא וּרְאֵה, אֵפוֹד וְחֹשֶׁן - אָחוֹר וָקֶדֶם הָיוּ, וּכְשֶׁהַכֹּהֵן הִתְלַבֵּשׁ בָּהֶם, הָיָה דּוֹמֶה בִּדְיוֹקָן עֶלְיוֹן. וַהֲרֵי נִתְבָּאֵר שֶׁאָז פָּנָיו הֵאִירוּ וְהָאוֹתִיּוֹת בָּלְטוּ, וְעָלוּ לְמַעְלָה מְאִירוֹת, וְאָז הָיָה יוֹדֵעַ אֶת הַדָּבָר.</p>\n<p>וּמִשּׁוּם כָּךְ תִּקּוּן הַחֹשֶׁן וְתִקּוּן הָאֵפוֹד כְּאֶחָד נִקְשְׁרוּ, וְאַף עַל גַּב שֶׁתִּקּוּן זֶה אֵינוֹ כְּתִקּוּן זֶה, וְהַכֹּל בְּסוֹד אֶחָד. קֶשֶׁר שֶׁל זֶה בָּזֶה, לְהִתְאַחֵז חֹשֶׁן בְּאֵפוֹד בְּאַרְבַּע טַבָּעוֹת שֶׁנִּקְשְׁרוּ בַּמָּקוֹם הַזֶּה וּבַמָּקוֹם הַזֶּה. וְהֵם סוֹד אוֹתָן הַמֶּרְכָּבוֹת שֶׁנִּקְשְׁרוּ בַּצַּד הַזֶּה שֶׁלְּמַטָּה לְאוֹתָם שֶׁלְּמַעְלָה, וְהַכֹּל הוּא בְּסוֹד שֶׁל אוֹפַנִּים וְחַיּוֹת.</p>\n<p>כָּתוּב, בְּרֵאשִׁית בָּרָא אֱלֹהִים אֵת הַשָּׁמַיִם וְאֵת הָאָרֶץ. וּפֵרְשׁוּהָ, שֶׁהֲרֵי הַכֹּל כְּמוֹ כֵן נַעֲשָׂה הַמִּשְׁכָּן. כְּמוֹ שֶׁהָעוֹלָם הַתַּחְתּוֹן עָשָׂה כְּמוֹ הָעוֹלָם הָעֶלְיוֹן, וְכָל מַעֲשֵׂהוּ שֶׁעָשָׂה כְּמוֹ שֶׁלְּמַעְלָה - כָּךְ גַּם הַמִּשְׁכָּן, כָּל מַעֲשָׂיו הֵם כְּמַעֲשֶׂה וּכְמוֹ שֶׁל הָעוֹלָם (העליון). (ובארוה, כדגמא זו נעשה המשכן, וכל מעשיו שעשה בעולם הזה כדגמא שלמעלה עשה. וכך גם כן המשכן, כל מעשיו הם כדגמת מעלה, כדגמת העולם התחתון וכדגמת העולם העליון).</p>\n<p>וְסוֹד זֶה, כָּל מַעֲשֵׂי הַמִּשְׁכָּן, כֻּלָּם מַעֲשִׂים וְתִקּוּנִים שֶׁלְּמַעְלָה וּלְמַטָּה, כְּדֵי לְהַשְׁרוֹת שְׁכִינָה בָּעוֹלָם בַּדִּיּוּרִים הָעֶלְיוֹנִים וּבַדִּיּוּרִים הַתַּחְתּוֹנִים. כְּמוֹ כֵן גַּן עֵדֶן לְמַטָּה הוּא כְּמוֹ הָעֶלְיוֹן. וּכְמוֹ הַתַּחְתּוֹן - כָּל הַצִּיּוּרִים וְכָל הַדְּיוֹקְנָאוֹת שֶׁל הָעוֹלָם כֻּלָּם שָׁם. וְעַל כֵּן עֲבוֹדַת הַמִּשְׁכָּן וַעֲבוֹדַת שָׁמַיִם וָאָרֶץ, כֻּלָּם בְּסוֹד אֶחָד.</p>"],[9522011883,"<p>כָּתוּב (ישעיה מ) שְׂאוּ מָרוֹם עֵינֵיכֶם וּרְאוּ מִי בָרָא אֵלֶּה וְגוֹ'. פָּסוּק זֶה פֵּרְשׁוּהוּ, אֲבָל בּא וּרְאֵה, וְכִי בִּשְׁבִיל שֶׁיִּסְתַּכֵּל אָדָם בְּעֵינָיו לְמַעְלָה וּמַעֲלֶה אוֹתָם לְמַעְלָה, יָכוֹל לְהִסְתַּכֵּל בְּמַה שֶּׁלֹּא הֻרְשָׁה לָדַעַת וְלִרְאוֹת?</p>\n<p>אֶלָּא, שְׂאוּ מָרוֹם עֵינֵיכֶם - מִי שֶׁרוֹצֶה לְהִסְתַּכֵּל בְּמַעֲשֵׂי הַקָּדוֹשׁ בָּרוּךְ הוּא, יִזְקֹף עֵינָיו לְמַעְלָה וְיִרְאֶה כַּמָּה חֲיָלוֹת וְכַמָּה מַחֲנוֹת מַעֲשִׂים מְשֻׁנִּים זֶה מִזֶּה, גְּדוֹלִים אֵלֶּה מֵאֵלֶּה, וְאָז תִּרְאוּ וְתִשְׁאֲלוּ וְתֹאמְרוּ, מִי בָרָא אֵלֶּה. מִי בָרָא אֵלֶּה, הֲרֵי בֵּאַרְנוּ סוֹד שֶׁל מִי, בָּרָא אֵלֶּה, שֶׁהוּא מָקוֹם שֶׁעוֹמֵד מָרוֹם וְגָנוּז וְנִסְתָּר וְלֹא יָדוּעַ וְעוֹמֵד תָּמִיד לִשְׁאֵלָה, מִשּׁוּם שֶׁלֹּא הִתְגַּלָּה לְאוֹתוֹ מָקוֹם.</p>\n<p>הַמּוֹצִיא בְמִסְפָּר צְבָאָם, מַה זֶּה הַמּוֹצִיא? אֶלָּא מִשּׁוּם שֶׁאוֹתוֹ מָקוֹם טָמִיר וְגָנוּז, הוּא מוֹצִיא הַכֹּל בְּסוֹד הַקּוֹל שֶׁיּוֹצֵא מֵהַשּׁוֹפָר. וְאוֹתוֹ קוֹל הוּא מִסְפָּר שֶׁל כָּל הַחֲיָלוֹת הָעֶלְיוֹנִים וְחֶשְׁבּוֹן שֶׁל הַכֹּל. וּמִשָּׁם נִמְצָא סוֹד הָאֱמוּנָה הָעֶלְיוֹנָה בְּכָל אוֹתָם צְדָדִים עֶלְיוֹנִים, עַד שֶׁשּׁוֹפְעוֹת הַדְּרָגוֹת וְנִמְשָׁכוֹת לְמַטָּה, וְנִפְרָדִים כַּמָּה חֲיָלוֹת לְמִינֵיהֶם, וְכֻלָּם עוֹמְדִים בְּחֶשְׁבּוֹן וְנִקְרָאִים בְּשֵׁם. מֵרֹב אוֹנִים - זֶה צַד הַיָּמִין. אַמִּיץ כֹּחַ - זֶה צַד הַשְּׂמֹאל. אִישׁ לֹא נֶעְדָּר - הַצְּדָדִים שֶׁשּׁוֹפְעִים מִשְּׁנֵי עֲבָרִים.</p>\n<p>דָּבָר אַחֵר שְׂאוּ מָרוֹם עֵינֵיכֶם וּרְאוּ מִי בָרָא אֵלֶּה - הַפָּסוּק הַזֶּה כְּשֶׁהוּקַם הַמִּשְׁכָּן וְהָיָה מִתְתַּקֵּן. כָּל מִי שֶׁרָאָה אֶת הַמִּשְׁכָּן, הִסְתַּכֵּל בּוֹ לְמַעְלָה וּמַטָּה, וְאֶת הַכֹּל רָאָה בַּמִּשְׁכָּן, מִשּׁוּם שֶׁכָּל מַעֲשֵׂי הָעוֹלָם הָעֶלְיוֹן וְהַתַּחְתּוֹן, כֻּלָּם נִתְקְנוּ בַמִּשְׁכָּן, וַהֲרֵי בֵּאַרְנוּ - כָּל מִי שֶׁרוֹאֶה אוֹתָם הַקְּרָסִים בַּמִּשְׁכָּן וְהִסְתַּכֵּל בָּהֶם, הָיָה מִסְתַּכֵּל בָּאוֹר שֶׁלָּהֶם בְּאוֹר הַכּוֹכָבִים, מִשּׁוּם שֶׁכָּךְ עוֹמְדִים הַכּוֹכָבִים בָּרָקִיעַ.</p>\n<p>פָּתַח וְאָמַר, (תהלים קמח) הַלְלוּיָה הַלְלוּ אֶת ה' מִן הַשָּׁמַיִם וְגוֹ'. בֹּא וּרְאֵה, הַתִּשְׁבַּחַת הַזּוֹ אָמַר דָּוִד כְּנֶגֶד סוֹד הַשֵּׁם הַקָּדוֹשׁ, שֶׁהוּא כְּלָל שֶׁל תִּשְׁבַּחַת הַכֹּל. שְׁתֵּי תִשְׁבָּחוֹת הֵן, כְּמוֹ סוֹד הַשֵּׁם הַקָּדוֹשׁ הָעֶלְיוֹן, שֶׁהוּא הַכְּלָל שֶׁל תִּשְׁבַּחַת הַכֹּל. וְאֵלּוּ: זֶה, וְהַשֶּׁבַח הָאַחֲרוֹן, שֶׁהוּא כְּלָלוּת הַשְּׁבָחִים שֶׁל הַכֹּל, שֶׁכָּתוּב (שם קנ) הַלְלוּיָהּ הַלְלוּ אֵל בְּקָדְשׁוֹ וְגוֹ'. אֲבָל זֶה הָיָה עַל עֲשָׂרָה מִינִים, וְזֶהוּ עַל שִׁבְעָה, וְהַכֹּל סוֹד אֶחָד בַּשֵּׁם הַקָּדוֹשׁ.</p>"],[9522011884,"<p>הַלְלוּיָהּ הַלְלוּ אֶת ה' מִן הַשָּׁמַיִם, זוֹהִי רֵאשִׁית שֶׁל שִׁשָּׁה צְדָדִים לְהִתְפַּשֵּׁט לְמַטָּה, שֶׁזֶּהוּ סוֹד שֶׁקַּיָּם לִשְׁאֵלָה, כְּמוֹ שֶׁנֶּאֱמַר (דברים ד) כי שאל נא לימים ראשנים אשר היו לפניך וגו'. עד כאן יש רשות לשאלה. מן היום אשר ברא וגו', ועד קצה השמים - מכאן והלאה לא עומד לשאלה, משום שהוא מקום טמיר וגנוז.</p>\n<p>וְעַל זֶה, הַלְלוּ אֶת ה' מִן הַשָּׁמַיִם הַלְלוּהוּ בַּמְּרוֹמִים - אֵלּוּ שְׁנֵי צְדָדִים, (שהם רום ההתחלה) יָמִין וּשְׂמֹאל. וּמִכָּאן מִתְפַּשְּׁטִים כָּל הָאֲחֵרִים לְמַטָּה בְּסוֹד הַדְּרָגוֹת לְהִתְתַּקֵּן כָּרָאוּי. הַלְלוּהוּ כָל מַלְאָכָיו - אֵלּוּ הֵם שְׁנֵי עַמּוּדִים שֶׁעוֹמְדִים תַּחַת הַגּוּף לְהַשְׁעִין אֶת הַגּוּף עֲלֵיהֶם.</p>\n<p>בֹּא וּרְאֵה, אוֹתָם הָעַמּוּדִים שֶׁהַגּוּף נִשְׁעָן עֲלֵיהֶם, עוֹמְדִים כָּאן בְּסוֹד הַמַּלְאָכִים, מִשּׁוּם שֶׁהַיְּרֵכַיִם הֵן שְׁלִיחִים לָלֶכֶת מִמָּקוֹם לְמָקוֹם, וּמִסּוֹד זֶה יוֹצְאִים אוֹתָם שֶׁנִּקְרָאִים מַלְאָכִים, שֶׁהֵם שְׁלִיחִים לָלֶכֶת בִּשְׁלִיחוּת אֲדוֹנָם מִמָּקוֹם לְמָקוֹם.</p>\n<p>הַלְלוּהוּ כָּל צְבָאָיו - זֶהוּ מָקוֹם שֶׁיּוֹצְאִים מִמֶּנּוּ כָּל הַחֲיָלוֹת הַקְּדוֹשִׁים הָעֶלְיוֹנִים, סוֹד אוֹת הַבְּרִית הַקְּדוֹשָׁה, וְהוּא רָשׁוּם בְּכָל שְׁאָר הָרְבָבוֹת, כְּמוֹ שֶׁאָמַרְנוּ, שֶׁכָּתוּב (ישעיה מח) ה' צְבָאוֹת שְׁמוֹ, אוֹת הוּא בְּכָל שְׁאָר הַחֲיָלוֹת וְהָרְבָבוֹת.</p>\n<p>הַלְלוּהוּ שֶׁמֶשׁ וְיָרֵחַ - בּוֹ עוֹמֵד הַסּוֹד הַזֶּה, וְהוּא הַשֶּׁמֶשׁ לְהָאִיר, וּבוֹ עוֹמְדִים כּוֹכָבִים עֶלְיוֹנִים שֶׁמְּאִירִים, וּמַזָּלוֹת, וַהֲרֵי בֵּאַרְנוּ. אַחַר כָּךְ חוֹזֵר לְמַעְלָה לְאוֹתוֹ מָקוֹם שֶׁעוֹמֵד בְּרוּם הַמְּרוֹמִים, וְשָׁם נִתְקָעִים הַכֹּל, הַלְלוּהוּ שְׁמֵי הַשָּׁמָיִם. אַחַר כָּךְ הַלְלוּ אֶת ה' מִן הָאָרֶץ. כְּנֶגֶד אֵלֶּה אֵשׁ וּבָרָד וְגוֹ'.</p>\n<p>בֹּא וּרְאֵה, אוֹתָם כּוֹכָבִים לְמַטָּה עוֹמְדִים בִּמְשִׁיכָה שֶׁנִּמְשָׁכִים מִסּוֹד הָעֶלְיוֹן, מִשּׁוּם שֶׁהַכֹּל עוֹמֵד בִּדְיוֹקָן עֶלְיוֹן, וַהֲרֵי בֵּאַרְנוּ. וּמִשּׁוּם כָּךְ כָּל אוֹתָם כּוֹכָבִים וּמַזָּלוֹת מֵרוּם הָרָקִיעַ, כֻּלָּם עוֹמְדִים לְהַנְהִיג בּוֹ אֶת הָעוֹלָם שֶׁלְּמַטָּה מִמֶּנּוּ, וּמִשָּׁם מִתְפַּשְּׁטוֹת דְּרָגוֹת, עַד שֶׁעוֹמְדוֹת הַדְּרָגוֹת לְאוֹתָם כּוֹכָבִים שֶׁלְּמַטָּה, שֶׁכֻּלָּם אֵין עוֹמְדִים בִּרְשׁוּתָם כְּלוּם, וַהֲרֵי בֵּאַרְנוּ, וְכֻלָּם עוֹמְדִים בָּרְשׁוּת שֶׁלְּמַעְלָה. וְעַל זֶה כָּתוּב, (ישעיה מז) יַעַמְדוּ נָא וְיוֹשִׁיעֻךְ הוֹבְרֵי שָׁמַיִם הַחֹזִים בַּכּוֹכָבִים, וְהַכֹּל הוּא בִּרְשׁוּת וְנִתְבָּאֵר.</p>"],[9522011885,"<p>וַיַּעָשׂוּ אֶת הַכָּתְנֹת שֵׁשׁ וְגוֹ' וְאֵת הַמִּצְנֶפֶת שֵׁשׁ וְגוֹ'. רַבִּי יוֹסֵי פָּתַח, (שם ב) וְהָיָה בְּאַחֲרִית הַיָּמִים נָכוֹן יִהְיֶה הַר בֵּית ה' בְּרֹאשׁ הֶהָרִים וְגוֹ'. וְהָיָה בְּאַחֲרִית הַיָּמִים, כְּשֶׁיִּפְקֹד הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת בַּת יַעֲקֹב וְיָקִים אוֹתָהּ מִן הֶעָפָר וְתִתְחַבֵּר הַשֶּׁמֶשׁ בַּלְּבָנָה, אָז נָכוֹן יִהְיֶה הַר בֵּית ה' - זוֹ יְרוּשָׁלַיִם לְמַעְלָה, שֶׁתִּהְיֶה מְתֻקֶּנֶת בְּתִקּוּנֶיהָ לִהְיוֹת נְאוֹרָה בָּאוֹר שֶׁלְּמַעְלָה, שֶׁכָּל אוֹרָהּ אֵינוֹ מְתֻקָּן אֶלָּא בָּאוֹר שֶׁלְּמַעְלָה. וּבְאוֹתוֹ זְמַן יֵאוֹר עָלֶיהָ אוֹר עֶלְיוֹן עַל אֶחָד פִּי שִׁבְעָה מִמַּה שֶּׁהָיְתָה מִקֹּדֶם לָכֵן, כַּכָּתוּב (שם ל) וְהָיָה אוֹר הַלְּבָנָה כְּאוֹר הַחַמָּה וְאוֹר הַחַמָּה יִהְיֶה שִׁבְעָתַיִם וְגוֹ'.</p>\n<p>בְּרֹאשׁ הֶהָרִים, בְּרָאשֵׁי הֶהָרִים הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה בְּרֹאשׁ? אֶלָּא הָאוֹר הַזֶּה שֶׁיִּהְיֶה לָהּ, בְּרֹאשׁ הֶהָרִים הוּא. וּמִיהוּ רֹאשׁ הֶהָרִים? זֶה הַכֹּהֵן הַגָּדוֹל שֶׁהוּא רֹאשׁ הֶהָרִים, הָרֹאשׁ שֶׁל כָּל צַד הַיָּמִין. וְזֶהוּ שֶׁמְּתַקֵּן אֶת הַבַּיִת תָּמִיד וּמְבָרֵךְ אוֹתָהּ לְהָאִיר פָּנֶיהָ. וְעַל זֶה, יִהְיֶה נָכוֹן.</p>\n<p>וּבַמֶּה יְתַקֵּן אוֹתָהּ? בְּאוֹתָם לְבוּשִׁים שֶׁהֵם כְּמוֹ שֶׁלְּמַעְלָה, כְּמוֹ שֶׁבֵּאֲרוּהָ. וְאוֹתָם לְבוּשִׁים כֻּלָּם עוֹמְדִים בְּסוֹד שֶׁל שֵׁשׁ. וְהַבַּיִת הַזֶּה, כְּשֶׁיִּהְיֶה מְתֻקָּן בְּרֹאשׁ הֶהָרִים הַזֶּה, שֶׁהוּא הַכֹּהֵן הַגָּדוֹל, אָז נִקְשָׁר וּמִתְעַלֶּה לְמַעְלָה בְּקִיּוּם עֶלְיוֹן, וְיֵאוֹר הָעוֹלָם מֵאוֹתוֹ הָאוֹר הָעֶלְיוֹן. (אז) וְזֶהוּ וְנִשָּׂא מִגְּבָעוֹת, מִכָּל שְׁאָר הַחֲיָלוֹת וְהַמַּחֲנוֹת הָעֶלְיוֹנִים. וְאָז, וְנָהֲרוּ אֵלָיו כָּל הַגּוֹיִם.</p>\n<p>בֹּא וּרְאֵה, בְּשָׁעָה שֶׁהַכֹּהֵן שֶׁלְּמַטָּה פּוֹרֵשׂ יָדָיו, אָז רוּחַ עֶלְיוֹנָה מְאִירָה וְיוֹצֵאת, וְכָל הַמְּאוֹרוֹת מְאִירִים, וְהָאוֹרוֹת נִמְשָׁכִים וּנְאוֹרִים וְנִקְשָׁרִים אֵלֶּה בְּאֵלֶּה, עַד שֶׁיָּאִירוּ אֶת פָּנֶיהָ שֶׁל כְּנֶסֶת יִשְׂרָאֵל, וְהַכֹּל עַל יְדֵי הָאוֹר הָרִאשׁוֹן שֶׁהוּא הַכֹּהֵן. וּכְשֶׁהַכֹּהֵן מִתְעוֹרֵר לְמַטָּה, כֹּהֵן מִתְעוֹרֵר לְמַעְלָה. וּבַמַּעֲשִׂים שֶׁלְּמַטָּה מִתְעוֹרֶרֶת הַהִתְעוֹרְרוּת שֶׁלְּמַעְלָה.</p>\n<p>וְעַל זֶה, נָכוֹן יִהְיֶה הַר בֵּית ה' בְּרֹאשׁ הֶהָרִים וְגוֹ', וְנָהֲרוּ אֵלָיו כָּל הַגּיִם. מִשּׁוּם שֶׁעַכְשָׁו, כָּל שְׁאָר הָעַמִּים יֵשׁ לָהֶם מְמֻנִּים בָּרָקִיעַ עֲלֵיהֶם, וּבְאוֹתוֹ זְמַן יְבַעֵר אוֹתָם וְיַפִּיל אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא מִשִּׁלְטוֹנָם, שֶׁכָּתוּב (ישעיה כד) יִפְקֹד ה' עַל צְבָא הַמָּרוֹם בַּמָּרוֹם. וְכֵיוָן שֶׁכֻּלָּם יַעַבְרוּ מִשִּׁלְטוֹנָם, אָז הַקָּדוֹשׁ בָּרוּךְ הוּא יִתְחַזֵּק לְבַדּוֹ, כְּמוֹ שֶׁנֶּאֱמַר (שםב) וְנִשְׂגָּב ה' לְבַדּוֹ בַּיּוֹם הַהוּא. וְאָז, וְנָהֲרוּ אֵלָיו כָּל הַגּוֹיִם. וְזֶהוּ שֶׁכָּתוּב וְהָלְכוּ עַמִּים רַבִּים וְאָמְרוּ לְכוּ וְנַעֲלֶה אֶל הַר ה' אֶל בֵּית אֱלֹהֵי יַעֲקֹב וְגוֹ'.</p>\n<p>וְהַכֹּל הוּא בְּשָׁעָה שֶׁהַכֹּהֵן, שֶׁהוּא רֹאשׁ הֶהָרִים, יָאִיר לָהּ, וְהַכֹּל הוּא בְּסוֹד שֶׁל שֵׁשׁ, שֵׁשׁ הֵם בְּכָל הַצְּדָדִים שֶׁיָּאִיר לָהּ, שֶׁהֲרֵי בְּסוֹד שֶׁל שֵׁשׁ יָאִיר לָהּ.</p>"],[9522011886,"<p>רַבִּי אֶלְעָזָר וְרַבִּי יִצְחָק וְרַבִּי יְהוּדָה הָיוּ הוֹלְכִים בַּדֶּרֶךְ. אָמַר רַבִּי אֶלְעָזָר, זְמַן הוּא לָלֶכֶת עִם הַשְּׁכִינָה, מִשּׁוּם שֶׁשְּׁכִינָה לֹא תִשְׁרֶה עָלֵינוּ אֶלָּא מִתּוֹךְ דִּבְרֵי תוֹרָה. אָמַר רַבִּי יְהוּדָה, מִי שֶׁהוּא הָרֹאשׁ, יִפְתַּח בָּרֹאשׁ.</p>\n<p>פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, (תהלים קיט) צָעִיר אָנֹכִי וְנִבְזֶה פִּקֻּדֶיךְ לֹא שָׁכָחְתִּי. צָעִיר אָנֹכִי וְנִבְזֶה - דָּוִד הַמֶּלֶךְ לִפְעָמִים מְשַׁבֵּחַ אֶת עַצְמוֹ, שֶׁכָּתוּב (שם יח) וְעֹשֶׂה חֶסֶד לִמְשִׁיחוֹ לְדָוִד וּלְזַרְעוֹ עַד עוֹלָם. וְכָתוּב (שמואל בכג) נְאֻם דָּוִד בֶּן יִשַׁי וּנְאֻם הַגֶּבֶר הוּקַם עָל מְשִׁיחַ אֱלֹהֵי יַעֲקֹב. וְלִפְעָמִים עוֹשֶׂה אֶת עַצְמוֹ עָנִי, שֶׁכָּתוּב (תהלים פו) כִּי עָנִי וְאֶבְיוֹן אָנִי. וְכָתוּב צָעִיר אָנֹכִי וְנִבְזֶה. וְהוּא אוֹמֵר, (שם קיח) אֶבֶן מָאֲסוּ הַבּוֹנִים הָיְתָה לְרֹאשׁ פִּנָּה.</p>\n<p>אֶלָּא, בִּזְמַן שֶׁהָיָה עוֹלֶה בְּדַרְגַּת הַשָּׁלוֹם וְהִתְעַלָּה בְּדִין שֶׁל אֱמֶת וְהָיָה שׁוֹלֵט עַל שׂוֹנְאָיו, הָיָה מְשַׁבֵּחַ אֶת עַצְמוֹ. וּבִזְמַן שֶׁרָאָה אֶת עַצְמוֹ בְּצָרָה וְשׂוֹנְאָיו דּוֹחֲקִים אוֹתוֹ, אָז הִנְמִיךְ אֶת עַצְמוֹ, וְהָיָה קוֹרֵא לְעַצְמוֹ עָנִי, קָטָן לְכֻלָּם. מָה הַטַּעַם? מִשּׁוּם שֶׁלִּפְעָמִים הָיָה שׁוֹלֵט, וְלִפְעָמִים הָיָה בַּצָּרָה שֶׁל שׂוֹנְאָיו.</p>\n<p>וְעִם כָּל זֶה, הוּא שָׁלַט עֲלֵיהֶם תָּמִיד וְלֹא יָכְלוּ לוֹ. וְדָוִד הַמֶּלֶךְ תָּמִיד הָיָה מַשְׁפִּיל עַצְמוֹ לַקָּדוֹשׁ- בָּרוּךְ-הוּא, שֶׁכָּל מִי שֶׁמַּנְמִיךְ עַצְמוֹ לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, הוּא מַזְקִיף אוֹתוֹ עַל הַכֹּל, וּמִשּׁוּם כָּךְ הִתְרַצָּה בּוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. בָּעוֹלָם הַזֶּה - שֶׁכָּתוּב (ישעיה לז) וְגַנּוֹתִי עַל הָעִיר הַזֹּאת לְהוֹשִׁיעָהּ לְמַעֲנִי וּלְמַעַן דָּוִד עַבְדִּי. וּבָעוֹלָם הַבָּא - שֶׁכָּתוּב (הושע ג) וּבִקְשׁוּ אֶת ה' אֱלֹהֵיהֶם וְאֵת דָּוִד מַלְכָּם וּפָחֲדוּ אֶל ה' וְאֶל טוּבוֹ בְּאַחֲרִית הַיָּמִים. דָּוִד הוּא הָיָה מֶלֶךְ בָּעוֹלָם הַזֶּה, וְדָוִד יִהְיֶה מֶלֶךְ לֶעָתִיד לָבא. וְעַל זֶה אָמַר, אֶבֶן מָאֲסוּ הַבּוֹנִים הָיְתָה לְרֹאשׁ פִּנָּה.</p>\n<p>בֹּא וּרְאֵה, בְּשָׁעָה שֶׁהַשֶּׁמֶשׁ מַחֲזִיר פָּנָיו וְלֹא מֵאִיר לַלְּבָנָה, מָעֳבָר אוֹרָהּ (ללבנה) וְלֹא מְאִירָה, וְאָז הִיא בְּעֹנִי בְּכָל הַצְּדָדִים, וְנִתְקַדֶּרֶת וְאֵין לָהּ אוֹר כְּלָל. וּכְשֶׁהַשֶּׁמֶשׁ חוֹזֵר נֶגְדָּהּ וּמֵאִיר לָהּ, אָז פָּנֶיהָ מְאִירוֹת, וְהִיא מִתְקַשֶּׁטֶת אֵלָיו כִּנְקֵבָה שֶׁמִּתְקַשֶּׁטֶת אֶל הַזָּכָר, וְאָז הִיא שׁוֹלֶטֶת בְּשִׁלְטוֹן הָעוֹלָם.</p>\n<p>וְעַל זֶה דָּוִד הָיָה מְעַטֵּר עַצְמוֹ בְּאוֹתוֹ גָּוֶן מַמָּשׁ. לִפְעָמִים הוּא עָנִי, וְלִפְעָמִים הוּא בְּעֹשֶׁר וּבַעֲשִׁירוּת הַכֹּל, וּמִשּׁוּם כָּךְ הָיָה אוֹמֵר צָעִיר אָנֹכִי וְנִבְזֶה. וְעִם כָּל זֶה - פִּקֻּדֶיךְ לֹא שָׁכָחְתִּי. כְּמוֹ כֵן יֵשׁ לָאָדָם לִהְיוֹת נִבְזֶה בְעֵינָיו, (ונבזה. ומה אם דוד המלךכך, כלשכן אדם אחר שיש לו) לְהַשְׁפִּיל אֶת עַצְמוֹ בַּכֹּל, לִהְיוֹתוֹ כְּלִי שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מִתְרַצֶּה בּוֹ, וַהֲרֵי פֵּרְשׁוּהָ, שֶׁכָּתוּב (ישעיה נז) וְאֶת דַּכָּא וּשְׁפַל רוּחַ. עַכְשָׁו אֲנִי אֶפְתַּח בָּרֹאשׁ.</p>"],[9522011887,"<p>פָּתַח וְאָמַר, (יחזקאלמ) וַיָּבֵיא אוֹתִי שָׁמָּה וְהִנֵּה אִישׁ מַרְאֵהוּ כְּמַרְאֵה נְחֹשֶׁת וּפְתִיל פִּשְׁתִּים בְּיָדוֹ וּקְנֵה הַמִּדָּה וְהוּא עֹמֵד בַּשָּׁעַר. אֶת זֶה רָאָה יְחֶזְקֵאל בְּאוֹתוֹ מַרְאֵה הַנְּבוּאָה, וְזֶהוּ אִישׁ, שֶׁהוּא שָׁלִיחַ בְּאוֹתָם לְבוּשִׁים.</p>\n<p>וְכָאן לֹא אָמַר אֶלָּא רַק אִישׁ, וְלֹא אָמַר אִישׁ לְבוּשׁ הַבַּדִּים. אֶלָּא בְּשָׁעָה שֶׁעָשָׂה שְׁלִיחוּת לַעֲשׂוֹת דִּין אוֹ לְהַרְאוֹת דִּין - נִקְרָא לְבוּשׁ הַבַּדִּים. וּבְשָׁעָה שֶׁלֹּא בָא לְכָךְ - הִשְׁתַּנָּה לְגָוֶן אַחֵר. כְּפִי שְׁלִיחוּתוֹ - כָּךְ שׁוֹנֶה הַמַּרְאֶה שֶׁלּוֹ בְּאוֹתָם לְבוּשִׁים וְהִשְׁתַּנָּה מִלְּבוּשִׁים לִלְבוּשִׁים, מִשּׁוּם שֶׁהוּא תָּמִיד בְצַד שְׂמֹאל, וְכַמָּה גְוָנִים הֵם שֶׁמִּתְלַבֵּשׁ בָּהֶם, וְכָל אוֹתָם שֶׁבָּאִים מִן הַצַּד שֶׁלּוֹ.</p>\n<p>מַרְאֵהוּ כְּמַרְאֵה נְחֹשֶׁת - כָּאן מִתְלַבֵּשׁ בְּאוֹתוֹ לְבוּשׁ שֶׁהֵם טוּרֵי נְחֹשֶׁת, שֶׁנִּקְרָאִים הָרֵי נְחֹשֶׁת, וְזֶה הֵבִיא מִדָּה לַעֲשׂוֹת מְדִידָה.</p>\n<p>זֶה (קנה המדה) אֵינוֹ הַנִּיצוֹץ הַקָּשֶׁה הַנֶּעְלָם וְהַגָּנוּז, אֶלָּא מִשָּׁם יוֹצֵא הַקָּנֶה הַזֶּה לְמַטָּה, שֶׁנִּגְשָׁם מִתּוֹךְ אוֹר שֶׁנִּשְׁאָר מֵהַנִּיצוֹץ הַקָּשֶׁה, כְּשֶׁמִּסְתַּלֵּק לְמַעְלָה וְנֶחְקָק תּוֹךְ הַסַּפִּיר שֶׁנּוֹצֵץ וְלֹא נוֹדָע. וְעַל כֵּן אוֹתוֹ קְנֵה הַמִּדָּה עוֹמֵד בִּמְדִידַת הַמִּדָּה שֶׁעוֹמֶדֶת לְמַטָּה.</p>\n<p>וְלִפְעָמִם קְנֵה הַמִּדָּה, וְלִפְעָמִים קַו הַמִּדָּה, וְעַל זֶה פְּתִיל וְקָנֶה, וְהַכֹּל מִדָּה לַעֲשׂוֹת מְדִידָה. (שם) כָּל הַמְּדִידוֹת שֶׁל יְחֶזְקֵאל הָיוּ בְּאוֹתוֹ קְנֵה הַמִּדָּה, וּבְמַעֲשֵׂה הַמִּשְׁכָּן הַכֹּל הָיָה בְּקַו הַמִּדָּה.</p>\n<p>בַּמִּשְׁכָּן, בְּאוֹתָהּ מְדִידָה שֶׁלְּמַטָּה, שֶׁהִיא קַו הַמִּדָּה, כְּמוֹ שֶׁאוֹתוֹ הַפְּתִיל, שֶׁכְּשֶׁמַּתְחִיל לְהִתְפַּשֵּׁט, בְּכָל אַמָּה קֶשֶׁר אֶחָד, וּבְאוֹתָהּ מִדָּה מוֹדֵד, וְנִקְרָא אַמָּה. וּמִשּׁוּם כָּךְ, (שמות כו) שְׁמֹנֶה וְעֶשְׂרִים בָּאַמָּה, שֶׁזֶּה אֹרֶךְ, וְרֹחַב אַרְבַּע בָּאַמָּה, וְלֹא כָתוּב אַרְבַּע אַמּוֹת, מִשּׁוּם שֶׁאַמָּה הָיָה מוֹדֵד לְכָל צַד.</p>\n<p>וְזְהִ יוֹצֵא מִסּוֹד הַמָּאוֹר הָעֶלְיוֹן, שֶׁהַמְּדִידָה שֶׁל זֶה לְמַטָּה, מֵהַמְּדִידָה הַזּוֹ שֶׁלְּמַעְלָה נִמְצֵאת. הַמְּדִידָה שֶׁלְּמַטָּה קְטַנָּה אֶלֶף וַחֲמֵשׁ מֵאוֹת צְדָדִים, וְכָל צַד וְצַד שְׁנֵים עָשָׂר אֶלֶף אַמּוֹת, וְעַל כֵּן אַמָּה אַחַת הוֹלֶכֶת בְּכֻלָּן, וְאוֹתָהּ אַמָּה שֶׁזֶּה מוֹדֵד, מִתְפַּשֵּׁט קַו הַמִּדָּה וְנִתְגַּלֵּית עוֹד אַמָּה וּמוֹדֵד, וְכֵן בְּכָל אוֹתָן מְדִידוֹת. (שנים עשר אלף אמות מתפשט קו המדה ונתגלית אמה ומודד, וכן בכל אותן מדידות, ועל זה אמה אחת הולכת בכלם, והיא אמה שמודדת זה מודדת זה).</p>\n<p>שְׁמֹנֶה וְעֶשְׂרִים בָּאַמָּה, הוּא אֹרֶךְ שֶׁל אַמָּה אַחַת, וְהָרֹחַב אַרְבַּע בְּאוֹתָהּ אַמָּה. נִמְצָא אַמָּה אַחַת שֶׁהִיא שְׁלֹשִׁים וּשְׁנַיִם שְׁלִישִׁים. כְּמוֹ שֶׁנֶּאֱמַר (ישעיה מ) וְכָל בַּשָּׁלִשׁ עֲפַר הָאָרֶץ, וְהֵם שְׁלֹשִׁים וּשְׁנַיִם, כְּנֶגֶד שְׁלֹשִׁים וּשְׁנַיִם שְׁבִילִים שֶׁיּוֹצְאִים מִלְמַעְלָה.</p>\n<p>וְכַאֲשֶׁר נַעֲשֵׂית מִדַּת הָאֹרֶךְ בַּמְּדִידָה הַזּוֹ, הִיא אַרְבָּעָה צְדָדִים אוֹתוֹ הָאֹרֶךְ. וְכָל צַד שֶׁבַע אַמּוֹת, שֶׁלְּכָךְ עוֹלוֹת אוֹתָן שֶׁבַע אַמּוֹת לְאַרְבָּעָה צְדָדִים בְּסוֹד שֶׁל שֶׁבַע, (ומתחומים) שֶׁהֵם עֶשְׂרִים וּשְׁמוֹנֶה שֶׁהֵם בָּאֹרֶךְ, מִשּׁוּם שֶׁשֶּׁבַע הוּא סוֹד עֶלְיוֹן בַּכֹּל. וְכָל אוֹתָם שְׁלֹשִׁים וּשְׁנַיִם שְׁבִילִים כְּלוּלִים בְּשֶׁבַע, בְּסוֹד הַשֵּׁם הַקָּדוֹשׁ.</p>\n<p>וְאִם תֹּאמַר, הֲרֵי כָּתוּב מִדָּה אַחַת לְכָל הַיְרִיעֹת - וַדַּאי שֶׁזּוֹ מִדָּה אַחַת, אַף עַל גַּב שֶׁהִתְפַּשְּׁטָה אַמָּה אַחַר אַמָּה, וְזֶה אַחַר זֶה, וְהַכֹּל בְּסוֹד (מסוד) הַמָּאוֹר הָעֶלְיוֹן זֶה בָּא, לִהְיוֹת מַעְלָה וּמַטָּה מִדָּה אַחַת.</p>\n<p>וְזוֹהִי הַמִּדָּה שֶׁהִיא בִּקְדֻשָּׁה יְתֵרָה, מִשּׁוּם שֶׁיֵּשׁ מִדָּה אַחֶרֶת שֶׁהִיא לְכַסּוֹת עַל זוֹ שֶׁהִיא בִּפְנִים. שֶׁהֲרֵי בְּמִדָּה אַחֶרֶת שֶׁמְּכַסָּה עַל זֶה עוֹלֶה בַּחֶשְׁבּוֹן לְחֶשְׁבּוֹן שְׁלֹשִׁים וְאַרְבַּע, וּבִפְנִים לְחֶשְׁבּוֹן שְׁלֹשִׁים וּשְׁתַּיִם, (שהיא לכסות על זה שהיא לבפנים ועולה בחשבון, בחשבון שלשים וארבע, ולבחוץ לחשבון שלשים ושתים) וְזֶהוּ סוֹד שֶׁמְּכַסֶּה זֶה עַל זֶה, שְׁלֹשִׁים וּשְׁתַּיִם לְבִפְנִים - שְׁלֹשִׁים וְאַרְבַּע (שלשים ושתים הוא עומד בפנים, שלשים וארבע הוא עומד) בַּחוּץ.</p>\n<p>מִשּׁוּם שֶׁהֲרֵי מִדָּה רִאשׁוֹנָה, שֶׁהִיא קְדוֹשָׁה בִּגְוָנִים קְדוֹשִׁים, שֶׁהֵם שֵׁשׁ מָשְׁזָר וּתְכֵלֶת וְאַרְגָּמָן וְתוֹלַעַת שָׁנִי, אֵלּוּ גְּוָנִים קְדוֹשִׁים, וְכָל חֶשְׁבּוֹנוֹ עוֹלֶה לְחֶשְׁבּוֹן שְׁלֹשִׁים וּשְׁתַּיִם. וּמִדָּה שְׁנִיָּה, שֶׁהִיא לַחוּץ לְכַסּוֹת עַל זֶה, עוֹלָה לְחֶשְׁבּוֹן שְׁלֹשִׁים וְאַרְבַּע, וְזֶהוּ סוֹד הַכָּתוּב (תהלים מא) אַשְׁרֵי מַשְׂכִּיל אֶל דָּל בְּיוֹם רָעָה יְמַלְּטֵהוּ ה'. בְּיוֹם רָעָה מַמָּשׁ יְמַלְּטֵהוּ ה'.</p>\n<p>סוֹד הַחֶשְׁבּוֹן לִפְנִים, שֶׁהוּא סוֹד שְׁלֹשִׁים וּשְׁתַּיִם. וּבְאוֹתוֹ חֶשְׁבּוֹן שֶׁל בַּחוּץ מַה כָּתוּב? וְעָשִׂיתָ יְרִיעֹת עִזִּים. יְרִיעֹת עִזִּים, לָמָּה עִזִּים? אֶלָּא הַסּוֹד הַגָּוֶן שֶׁלּוֹ, לָתֵת מָקוֹם בְּסוֹד הַקֹּדֶשׁ, וּמִשּׁוּם כָּךְ יְרִיעֹת עִזִּים וַדַּאי. כָּתוּב (שיר ו) אֶל גִּנַת אֱגוֹז יָרַדְתִּי וְגוֹ', הֲרֵי פֵּרְשׁוּהָ, אֲבָל מָה אֱגוֹז יֵשׁ לוֹ קְלִפָּה שֶׁמַּקִּיפָה וּמְכַסָּה אֶת הַמֹּחַ, וְהַמֹּחַ מִבִּפְנִים, אַף כָּךְ בְּכָל דָּבָר שֶׁל קֹדֶשׁ - הַקְּדֻשָּׁה בִּפְנִים, וְהַצַּד הָאַחֵר בַּחוּץ. וְסוֹד זֶה - (חבקוק א) רָשָׁע מַכְתִּיר אֶת הַצַּדִּיק. וְעַל כֵּן נִקְרָא אֱגוֹז, וַהֲרֵי פֵּרְשׁוּהָ.</p>\n<p>בֹּא וּרְאֵה, בְּאוֹתוֹ שֶׁבַּחוּץ - כָּל מַה שֶּׁמּוֹסִיף, גּוֹרֵעַ. וְסִימָנְךְ פָּרֵי הֶחָג, שֶׁמִּתְמַעֲטִים וְהוֹלְכִים. אַף כָּאן גַּם, בְּמַה שֶּׁבִּפְנִים כָּתוּב, וְאֶת הַמִּשְׁכָּן תַּעֲשֶׂה עֶשֶׂר יְרִיעֹת. וּבְמַה שֶּׁבַּחוּץ כָּתוּב, עַשְׁתֵּי עֶשְׂרֵה יְרִיעֹת. הוֹסִיף אוֹתִיּוֹת וְגָרַע מֵהַחֶשְׁבּוֹן. הוֹסִיף חֶשְׁבּוֹן וְגָרַע (אותיות). הוֹסִיף חֶשְׁבּוֹן, שֶׁכָּתוּב (שמות כו) אֹרֶךְ הַיְרִיעָה הָאַחַת שְׁלֹשִׁים בָּאַמָּה וְרֹחַב אַרְבַּע בָּאַמָּה הַיְרִיעָה. וּכְשֶׁעוֹלֶה לְחֶשְׁבּוֹן, עוֹלֶה לְחֶשְׁבּוֹן שְׁלֹשִׁים וְאַרְבַּע, שֶׁאֵין בְּכָל אוֹתָם מִינֵי הָעֹנִי כְּמוֹ אוֹתוֹ שֶׁנִּקְרָא דַּ\"ל. וּמִשּׁוּם כָּךְ, כְּשֶׁעוֹלֶה לְחֶשְׁבּוֹן יוֹתֵר, עוֹלֶה בְּחִסָּרוֹן.</p>\n<p>וּכְשֶׁהוּא גּוֹרֵעַ בַּחֶשְׁבּוֹן (גורע), עוֹלֶה בַּעֲלִיָּה, שֶׁעוֹלֶה לְסוֹד שֶׁל שְׁלֹשִׁים וּשְׁתַּיִם, שֶׁהֵם סוֹד כָּל הָאֱמוּנָה, וְהוּא סוֹד הַשֵּׁם הַקָּדוֹשׁ. וְלָכֵן זֶה עוֹלֶה וְזֶה גּוֹרֵעַ. זֶה עוֹלֶה וְגוֹרֵעַ, וְזֶה גּוֹרֵעַ וְעוֹלֶה. זֶה לִפְנִים, וְזֶה לַחוּץ.</p>\n<p>קַו הַמִּדָּה הַזֶּה מַתְחִיל לְהִתְפַּשֵּׁט וּמוֹדֵד הַמִּדָּה לַקְּרָשִׁים, שֶׁכָּתוּב (שמות לו) וַיַּעַשׂ אֶת הַקְּרָשִׁים לַמִּשְׁכָּן עֲצֵי שִׁטִּים עֹמְדִים. וְאֵלּוּ הֵם סוֹד הַשְּׂרָפִים, וַהֲרֵי פֵּרְשׁוּהָ, שֶׁכָּתוּב עֲצֵי שִׁטִּים עֹמְדִים, וְכָתוּב (ישעיה ו) שְׂרָפִים עֹמְדִים.</p>\n<p>מְדִידַת הַמִּדָּה הַזּוֹ - עֶשֶׂר אַמּוֹת אֹרֶךְ הַקָּרֶשׁ וְאַמָּה וַחֲצִי הָאַמָּה. כָּאן כָּתוּב עֶשֶׂר אַמּוֹת, וְלֹא כָתוּב עֶשֶׂר בָּאַמָּה. אֵלּוּ שָׁלֹשׁ שָׁלֹשׁ שָׁלֹשׁ שֶׁהֵן תֵּשַׁע, וְאֶחָד שֶׁשּׁוֹרֶה עֲלֵיהֶם, וְזֶהוּ רוּחַ אַחַת שֶׁשּׁוֹרָה עֲלֵיהֶם.</p>\n<p>וַהֲרֵי אָמַרְנוּ כַּמָּה הוּא שִׁעוּר הָאַמָּה, וְזֶהוּ סוֹד הַשִּׁעוּר - אַחַת עֶשְׂרֵה וָחֵצִי, שֶׁעוֹלִים וְלֹא עוֹלִים, מִשּׁוּם שֶׁגּוֹרְעִים מֵאוֹתָם הָאוֹפַנִּים. וּפֵרְשׁוּהָ בְּסוֹד הַמֶּרְכָּבָה הַקְּדוֹשָׁה, וְהֵם עֶשְׂרִים, עֶשֶׂר לְצַד זֶה וְעֶשֶׂר לְצַד זֶה, עַד שֶׁעוֹלִים לְסוֹד הַשְּׂרָפִים הָעֶלְיוֹנִים. וְאַחַר כָּךְ עוֹלֶה סוֹד הַקֹּדֶשׁ עַד שֶׁכֻּלָּם מִתְעוֹרְרִים (נפגשים) בְּסוֹד אוֹתוֹ הַבְּרִיחַ הַתִּיכוֹן, כְּמוֹ שֶׁבֵּאֲרוּהָ, וְלָכֵן חֲצִי יֵשׁ בּוֹ בְּלֹא שְׁלֵמוּת.</p>\n<p>סוֹד הַמִּדָּה הַזּוֹ, לְעֶשְׂרִים קְרָשִׁים הֵם מָאתַיִם וּשְׁלֹשִׁים, וְכָל זֶה עוֹמֵד בִּמְדִידָה בְּחֶשְׁבּוֹן, וְכָךְ עוֹלֶה כָּל חֶשְׁבּוֹן שֶׁיּוֹצֵא מֵהַמְּדִידָה הַזּוֹ בְּסוֹד אוֹתָם הַשְּׂרָפִים.</p>\n<p>יְרִיעוֹת הַמִּשְׁכָּן שֶׁאָמַרְנוּ, שֶׁהֵם סוֹדוֹת עֶלְיוֹנִים, סוֹד הַשָּׁמַיִם, וַהֲרֵי פֵּרְשׁוּהָ (תהליםקד) נוֹטֶה שָׁמַיִם כַּיְרִיעָה. וְהַסּוֹד שֶׁל זֶה בְּאוֹתוֹ חֶשְׁבּוֹן שֶׁאָמַרְנוּ. וְיֵשׁ יְרִיעוֹת שֶׁאָמַרְנוּ בְּסוֹד אֶחָד, וְיֵשׁ יְרִיעוֹת בְּסוֹד אַחֵר, וְהַכֹּל הוּא בְּסוֹד שֶׁלְּמַעְלָה. וְעַל כֵּן הַכֹּל הוּא כְּדֵי לָדַעַת חָכְמָה שֶׁל כָּל צַד וְצַד וְכָל דָּבָר וְדָבָר. וְעַל כֵּן מַבְחִין אָדָם בֵּין טוֹב לְרַע, בֵּין סוֹד הַחָכְמָה וּבֵין דָּבָר שֶׁאֵינוֹ עוֹמֵד בְּחָכְמָה. וּבְסוֹד הַמְּדִידָה הָרִאשׁוֹנָה הֲרֵי נִתְבָּאֵר בְּכַמָּה צְדָדִים הוּא.</p>\n<p>הַסּוֹד הַזֶּה סוֹד הָאָרוֹן שֶׁעוֹמֵד בְּחֶשְׁבּוֹן מִמַּה שֶּׁהוּא נוֹטֵל וּמִמַּה שֶׁהוּא מְקַבֵּל וּמִמַּה שֶּׁיֵּשׁ בּוֹ. וּמִמַּה הוּא מְקַבֵּל? שֶׁהוּא שְׁנֵי צְדָדִים, וְלוֹקֵחַ מֵאוֹתָם שְׁנֵי צְדָדִים. וְעַל כָּךְ אַמָּה הִיא בְּצַד זֶה וְאַמָּה בְּצַד זֶה, וַחֲצִי מִמֶּנּוּ. וּמִשּׁוּם כָּךְ, (שמות כה) אַמָּתַיִם וָחֵצִי אָרְכּוֹ. אַמָּתַיִם מִשְּׁנֵי צְדָדִים, וַחֲצִי שֶׁלּוֹ, הֲרֵי זֶה בָּאֹרֶךְ. בָּרֹחַב וּבַגֹּבַהּ אַמָּה וָחֵצִי, אֶחָד מֵאוֹתוֹ צַד יוֹתֵר, שֶׁנּוֹטֵל כְּמוֹ שֶׁיָּמִין וּשְׂמֹאל, וַחֲצִי שֶׁלּוֹ. שֶׁהֲרֵי אֵין שׁוֹרֶה הַדָּבָר אֶלָּא עַל דָּבָר, וּמִשּׁוּם כָּךְ חֲצִי בְּכָל חֶשְׁבּוֹן וְחֶשְׁבּוֹן, וּמִשּׁוּם כָּךְ הָאָרוֹן מְקַבֵּל מֵהַכֹּל וְעוֹמֵד בְּסוֹד הַחֶשְׁבּוֹן שֶׁל הַכֹּל.</p>\n<p>וַהֲרֵי פֵּרְשׁוּהָ, עַל מַה הוּא מְצֻפֶּה בְּזָהָב בִּפְנִים וּבַחוּץ, וַהֲרֵי הוּא שִׁעוּר לַעֲמֹד בִּמְדִידָה רִאשׁוֹנָה? וְהַכֹּל עוֹמֵד בְּסוֹד אֶחָד. הַשֻּׁלְחָן כְּמוֹ כֵן, שֶׁמּוֹדֵד בְּאוֹתוֹ הַשִּׁעוּר הָרִאשׁוֹן.</p>\n<p>אֲבָל מְדִידַת הָאָרוֹן הַזּוֹ, שֶׁעוֹמֶדֶת בְּסוֹד הַתּוֹרָה וּבְאוֹתָהּ מִדָּה רִאשׁוֹנָה שֶׁאָמַר אַבָּא, אֵין בָּהּ לַעֲשׂוֹת שִׁעוּר יוֹתֵר כְּמוֹ שֶׁהוּא גִּלָּה בְּסוֹד לַחֲכָמִים הָעֶלְיוֹנִים לָדַעַת בָּהּ אֶת סוֹד הַחָכְמָה, לְהַבְחִין בֵּין טוֹב לְרַע, בֵּין חָכְמָה עֶלְיוֹנָה לְחָכְמָה אַחֶרֶת, כֻּלָּם מַעֲשִׂים אֲחֵרִים, כֻּלָּם בִּמְדִידַת הָאַמָּה בְּאוֹתָהּ הַמִּדָּה, פְּרָט לְמִדַּת הַחֹשֶׁן שֶׁהִיא זֶרֶת, וַהֲרֵי פֵּרְשׁוּהָ.</p>\n<p>בֹּא וּרְאֵה, הַכֻּתֹּנֶת (אף על גב) שֶׁל כֻּלָּם נַעֲשׂוּ בְּסוֹד הַקֹּדֶשׁ, הַכֹּל הוּא בְּסוֹד שֶׁל שֵׁשׁ, וּבְמַעֲשֶׂה שֶׁל שֵׁשׁ, וְעוֹמֵד בְּשֵׁשׁ. וְכֻלָּם תִּקּוּנִים לְהִתְלַבֵּשׁ וּלְהַתְקִין בָּהֶם שֵׁשׁ וּבְסוֹד שֶׁל שֵׁשׁ.</p>\n<p>וְהַסֹל בְּסוֹד שֶׁל קַו הַמִּדָּה. וּקְנֵה הַמִּדָּה בְּאוֹתָהּ מְדִידַת יְחֶזְקֵאל, מִשּׁוּם שֶׁהוּא בַּיִת לְהִתְקַיֵּם (משום זה הבית לא התקים) בִּמְקוֹמוֹ בְּאוֹתָם כְּתָלִים, בְּאוֹתָן חוֹמוֹת, בְּאוֹתָם פְּתָחִים וּבְאוֹתָן דְּלָתוֹת כְּדֵי לִהְיוֹת הַכֹּל בִּמְדִידָה. אֲבָל לֶעָתִיד לָבא מַה כָּתוּב בְּאוֹתָהּ הַמִּדָּה? (יחזקאל מא) וְרָחֲבָה וְנָסְבָה לְמַעְלָה לְמַעְלָה. בְּשָׁעָה שֶׁיַּתְחִילוּ לִבְנוֹתָהּ, קְנֵה הַמִּדָּה הַזֶּה עוֹלֶה לְמַעְלָה לְמַעְלָה, לָאֹרֶךְ וְלָרֹחַב, שֶׁתִּהְיֶה הִתְפַּשְּׁטוּת הַבַּיִת לְכָל הַצְּדָדִים וְלֹא יִסְתַּכְּלוּ עָלֶיהָ לְרַע, כְּמוֹ שֶׁבֵּאֲרוּהָ, שֶׁכָּתוּב (זכריה ט) וְדַמֶּשֶׂק מְנוּחָתוֹ. שֶׁהֲרֵי בְּאוֹתוֹ זְמַן לֹא יִמָּצֵא דִין בָּעוֹלָם, מִשּׁוּם כָּךְ הַכֹּל מִתְקַיֵּם עַל מְקוֹמוֹ בְּקִיּוּם שָׁלֵם, כְּמוֹ שֶׁנֶּאֱמַר (שמואל ב ז) לֹא יִרְגַּז עוֹד וְלֹא יֹסִיפוּ בְנֵי עַוְלָה לְעַנּוֹתוֹ וְגוֹ'.</p>\n<p>וּבֹא רְאֵה, כָּל הַמִּדּוֹת וְכָל הַמְּדִידוֹת, כֻּלָּן עוֹמְדוֹת בָּעוֹלָם הַזֶּה, (וכל המדידות של המשכן הזה והבית הזה, כלם) כְּדֵי לְקַיֵּם אֶת הָעוֹלָם הַזֶּה בְּסוֹד כְּמוֹ שֶׁלְּמַעְלָה, לִקְשֹׁר אֶת הָעוֹלָם הַזֶּה בָּעוֹלָם שֶׁלְּמַעְלָה, לִהְיוֹת הַכֹּל אֶחָד בְּסוֹד אֶחָד. וּבְאוֹת זְמַן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יִתְעוֹרֵר לְחַדֵּשׁ אֶת הָעוֹלָם, אָז יִמָּצְאוּ כָּל הָעוֹלָמוֹת בְּסוֹד אֶחָד, וּכְבוֹדוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא בַּכֹּל, וְאָז כָּתוּב (זכריה יד) בַּיּוֹם הַהוּא יִהְיֶה ה' אֶחָד וּשְׁמוֹ אֶחָד.</p>"],[9522011888,"<p>פָּתַח רַבִּי יְהוּדָה אַחֲרָיו וְאָמַר, (תהלים כה) סוֹד ה' לִירֵאָיו וּבְרִיתוֹ לְהוֹדִיעָם. פָּסוּק זֶה הֲרֵי פֵּרְשׁוּהוּ, אֲבָל סוֹד ה' לִירֵאָיו - אוֹתוֹ סוֹד עֶלְיוֹן שֶׁעוֹמֵד בִּגְנִיזוּת, (שהוא סתום וגנוז) לֹא עוֹמֵד אֶלָּא לִירֵאָיו, שֶׁהֵם יְרֵאִים מֵהַקָּדוֹשׁ בָּרוּךְ הוּא תָּמִיד, וְהֵם רְאוּיִים לְאוֹתָם סוֹדוֹת עֶלְיוֹנִים, וְשֶׁיִּהְיוּ אוֹתָם סוֹדוֹת עֶלְיוֹנִים בִּגְנִיזוּת וּבְנִסְתָּר כָּרָאוּי, מִשּׁוּם שֶׁהֵם סוֹדוֹת עֶלְיוֹנִים. אֲבָל וּבְרִיתוֹ לְהוֹדִיעָם - הַסּוֹד שֶׁהוּא עוֹמֵד בִּבְרִית הַקֹּדֶשׁ, לְהוֹדִיעָם, מִשּׁוּם שֶׁהוּא מָקוֹם שֶׁעוֹמֵד לְהִגָּלוֹת וְלָדַעַת.</p>\n<p>וְעוֹד, סוֹד ה' לִירֵאָיו - שֶׁהֵם סוֹדוֹת הָעוֹמְדִים בְּיִרְאָה, וְאוֹתָם יִרְאֵי חֵטְא יְרֵאִים בָּהֶם בְּאוֹתָם סוֹדוֹת עֶלְיוֹנִים. אֲבָל וּבְרִיתוֹ לְהוֹדִיעָם - לָדַעַת וּלְפָרֵשׁ דְּבָרִים, מִשּׁוּם שֶׁאוֹתָם הַדְּבָרִים עוֹמְדִים לְפֵרוּשׁ.</p>\n<p>בֹּא וּרְאֵה, בְּאַרְבָּעִים וּשְׁתַּיִם אוֹתִיּוֹת נֶחְקַק הָעוֹלָם וְהִתְקַיֵּם, וְכֻלָּם עֲטָרָה שֶׁל הַשֵּׁם הַקָּדוֹשׁ. כְּשֶׁמִּצְטָרְפוֹת, עוֹלוֹת בָּאוֹתִיּוֹת שֶׁלְּמַעְלָה וְיוֹרְדוֹת לְמַטָּה, מִתְעַטְּרוֹת בַּעֲטָרוֹת בְּאַרְבַּעַת צִדְדֵי הָעוֹלָם, וְיָכוֹל לְהִתְקַיֵּם.</p>\n<p>אַחַר כָּךְ יָצְאוּ הָאוֹתִיּוֹת וּבָרְאוּ אֶת הָעוֹלָם לְמַעְלָה וּמַטָּה, בְּעוֹלַם הַיִּחוּד וּבְעוֹלַם הַפֵּרוּד, וְנִקְרָאִים (שיר השירים ב) הָרֵי בָתֶר, הָרֵי הַפֵּרוּד שֶׁנִּשְׁקִים, כְּשֶׁצַּד הַדָּרוֹם מַתְחִיל לִקְרַב אֵלָיו, וְאָז הַמַּיִם שׁוֹפְעִים, וּבַכֹּחַ הַזֶּה שֶׁלְּמַעְלָה שׁוֹפֵעַ, וְהַכֹּל הוּא בְּשִׂמְחָה.</p>\n<p>כְּשֶׁהַמַּחֲשָׁבָה עוֹלָה בָּרָצוֹן שֶׁל הַשִּׂמְחָה מִטְּמִיר כָּל הַטְּמִירִים, מַגִּיעַ וְשׁוֹפֵעַ מִתּוֹכָהּ זֹהַר אֶחָד, וּמִתְקָרְבִים זֶה בָּזֶה, וַהֲרֵי פֵּרְשׁוּהָ.</p>\n<p>וְאוֹתָן אַרְבָּעִים וּשְׁתַּיִם אוֹתִיּוֹת הֵן סוֹד עֶלְיוֹן, וּבָהֶן נִבְרָא הָעוֹלָם הָעֶלְיוֹן וְהָעוֹלָם הַתַּחְתּוֹן, וְהֵן הַקִּיּוּם וְסוֹד כָּל הָעוֹלָמוֹת. וְעַל שֶׁהֵן סוֹד הָעוֹלָמוֹת, כָּתוּב סוֹד ה' לִירֵאָיו וּבְרִיתוֹ לְהוֹדִיעָם. זֶה סוֹד הָאוֹתִיּוֹת הַחֲקוּקוֹת בְּהֶצְנֵעַ, מְפֹרָשׁוֹת בַּחֲקִיקוֹתָיו בְּגָלוּי.</p>\n<p>כָּתוּב (שמות כו) וְנָתַתָּ אֶל חֹשֶׁן הַמִּשְׁפָּט אֶת הָאוּרִים וְאֶת הַתֻּמִּים, וַהֲרֵי פֵּרְשׁוּהָ. אֶת הָאוּרִים - שֶׁמְּאִירִים סוֹד הָאַסְפַּקְלַרְיָה הַמְּאִירָה, וְזוֹהִי חֲקִיקַת הַשֵּׁם הַקָּדוֹשׁ בְּסוֹד שֶׁל אַרְבָּעִים וּשְׁתַּיִם שֶׁבָּהֶן נִבְרְאוּ הָעוֹלָמוֹת וְהָיוּ מְשֻׁקָּעוֹת בּוֹ. וְאֶת הַתֻּמִּים - סוֹד אוֹתָן הָאוֹתִיּוֹת שֶׁכְּלוּלוֹת בִּמְקוֹם הָאַסְפַּקְלַרְיָה שֶׁאֵינָהּ מְאִירָה, וְהִיא מִתְנַהֶגֶת (נאורה) בְּע\"ב אוֹתִיּוֹת חֲקוּקוֹת, שֶׁהֵן סוֹד הַשֵּׁם הַקָּדוֹשׁ, וְכֻלָּן נִקְרָאוֹת אוּרִים וְתֻמִּים.</p>\n<p>בֹּא וּרְאֵה, כְּשֶׁאוֹתָן אוֹתִיּוֹת מְשֻׁקָּעוֹת שָׁם, בְּאוֹתוֹ כֹּחַ, מְאִירוֹת אוֹתִיּוֹת אֲחֵרוֹת בַּחֲקִיקַת אוֹתָם שְׁמוֹת הַשְּׁבָטִים, וּמְאִירִים אוֹ נֶחְשָׁכִים, וְהַכֹּל הוּא בְּסוֹד אוֹתָן הָאוֹתִיּוֹת שֶׁל הַשֵּׁמוֹת הַקְּדוֹשִׁים כְּמוֹ שֶׁאָמַרְנוּ. וְאוֹתָן הָאוֹתִיּוֹת שֶׁל הַשֵּׁמוֹת הַקְּדוֹשִׁים בָּאוֹת עַל סוֹד הַתּוֹרָה, וְכָל הָעוֹלָמוֹת בָּאִים (נבראו) בַּסּוֹד שֶׁל אֵלּוּ הָאוֹתִיּוֹת. הַשֵּׁמוֹת הַלָּלוּ הָיוּ גְנוּזִים מְשֻׁקָּעִים שָׁם, וּבִשְׁמוֹת הַשְּׁבָטִים הָיוּ הָאוֹתִיּוֹת שֶׁלָּהֶם בּוֹלְטוֹת לְמַעְלָה. וְעַל כֵּן הַכֹּל מִסּוֹד אוֹתָן הָאוֹתִיּוֹת, וְהַכֹּל בֵּאַרְנוּ.</p>\n<p>וַהֲרֵי נֶאֱמַר בְּסוֹד הָאוֹתִיּוֹת שֶׁל הַתּוֹרָה. ב' - שֶׁהַתּוֹרָה הִתְחִילָה בָּהּ, וַהֲרֵי פֵּרְשׁוּהָ, ב' בָּרָא וַדַּאי בְּכֹחַ עֶלְיוֹן, בְּתֹקֶף שֶׁל סוֹד אוֹתָן הָאוֹתִיּוֹת. ב' נְקֵבָה, א' זָכָר. כְּמוֹ שֶׁב' בָּרָא, גַּם כָּךְ א', הוֹצִיא אוֹתִיּוֹת, כְּלַל כָּל עֶשְׂרִים וּשְׁתַּיִם הָאוֹתִיּוֹת.</p>\n<p>ה' - זִוּוּג אֶחָד עִם שָׁמַיִם לָתֵת לָהּ חַיִּים וּלְהַשְׁרוֹת לָהּ. ו' - הָאָרֶץ, לָתֵת לָהּ מָזוֹן וּלְתַקֵּן לָהּ סִפּוּקָהּ הָרָאוּי לָהּ. וְסוֹד זֶה בְּרֵאשִׁית וְגוֹ', עַד הַשָּׁמַיִם וְאֵת הָאָרֶץ. ו' וְאֶת - כְּלָל שֶׁל עֶשְׂרִים וּשְׁתַּיִם אוֹתִיּוֹת, וְנִזּוֹנֵית הָאָרֶץ, וְהָאָרֶץ כּוֹלֶלֶת אוֹתָן לְתוֹכָהּ, כְּמוֹ שֶׁנֶּאֱמַר (קהלת א) כָּל הַנְּחָלִים הֹלְכִים אֶל הַיָּם. וְהַיְנוּ סוֹד וְאֵת הָאָרֶץ, שֶׁכּוֹנֶסֶת הַכֹּל לְתוֹכָהּ וּמְקַבֶּלֶת אוֹתָם. הָאָרֶץ נוֹטֶלֶת ו' וּמְקַבֶּלֶת אוֹתָהּ לְהִזּוֹן.</p>\n<p>וְסוֹד זֶה, שֶׁאֵין הַמִּשְׁכָּן נִתְקָן אֶלָּא עַל יְדֵי מֹשֶׁה, מִשּׁוּם שֶׁמֵּאוֹתוֹ צַד מִתְעוֹרֶרֶת דַּרְגָּה אַחֶרֶת עֶלְיוֹנָה לְהַעֲמִידוֹ וְלִהְיוֹת קִיּוּם שֶׁל הַכֹּל. וְסוֹד זֶה - וַיָּקֶם מֹשֶׁה אֶת הַמִּשְׁכָּן. קִיּוּמוֹ הָיָה בְּאוֹתָן אוֹתִיּוֹת שֶׁנִּבְרְאוּ בָהֶן שָׁמַיִם וָאָרֶץ.</p>\n<p>וּמִשּׁוּם כָּךְ אֶת כָּל מַעֲשֵׂי הַמִּשְׁכָּן הָיָה בְּצַלְאֵל עוֹשֶׂה אוֹתָם בְּסוֹד חֲקִיקַת (צרוף) הָאוֹתִיּוֹת שֶׁנִּבְרְאוּ בָהֶן שָׁמַיִם וָאָרֶץ, וְלָכֵן נִקְרָא בְּצַלְאֵל, מִשּׁוּם שֶׁבְּצַלְאֵל הָיָה יוֹדֵעַ חֲקִיקַת (צרוף) הָאוֹתִיּוֹת שֶׁבָּהֶן נִבְרְאוּ שָׁמַיִם וָאָרֶץ. וְאִם בְּצַלְאֵל לֹא הָיָה יוֹדֵעַ אוֹתָן, לֹא הָיָה יָכוֹל לַעֲשׂוֹת אֶת אוֹתָן עֲבוֹדוֹת הַמִּשְׁכָּן. מָה הַטַּעַם? אֶלָּא, כְּמוֹ שֶׁהַמִּשְׁכָּן הָעֶלְיוֹן לֹא הָיָה וְלֹא הָיוּ מְתֻקָּנִים כָּל מַעֲשָׂיו אֶלָּא בְּאוֹתוֹ סוֹד שֶׁל אוֹתָן אוֹתִיּוֹת, אַף כָּאן בַּמִּשְׁכָּן שֶׁלְּמַטָּה לֹא הָיָה וְלֹא נִתְקַן אֶלָּא בְּסוֹדוֹת אוֹתָן הָאוֹתִיּוֹת.</p>\n<p>בְּצַלְאֵל הָיָה מְצָרֵף אוֹתָן אוֹתִיּוֹת, וּבְסוֹד כָּל צֵרוּף וְצֵרוּף הָיָה עוֹשֶׂה אֻמָּנוּת. וְכָל מַעֲשֶׂה וּמַעֲשֶׂה שֶׁל הַמִּשְׁכָּן, בְּכָל צֵרוּף הָיָה עוֹשֶׂה אֻמָּנוּת אַחַת, וְכָל מַה שֶּׁרָאוּי לָהּ. וְכֵן בְּכָל מַעֲשֵׂי הַמִּשְׁכָּן וְכָל אוֹתָם הַפְּרָקִים וְהַתִּקּוּנִים שֶׁל הַמִּשְׁכָּן, הַכֹּל הָיָה בְּצֵרוּף אוֹתִיּוֹת הַשֵּׁם הַקָּדוֹשׁ.</p>\n<p>וּכְשֶׁבָּא לַהֲקִימוֹ, לֹא יָכוֹל הָיָה לַהֲקִימוֹ. מָה הַטַּעַם? מִשּׁוּם שֶׁהָרָצוֹן שֶׁעוֹלֶה עַל אוֹתָן הָאוֹתִיּוֹת לֹא נִמְסַר אֶלָּא לְמֹשֶׁה לְבַדּוֹ, וְהוּא הָיָה יוֹדֵעַ אוֹתוֹ הָרָצוֹן שֶׁעוֹלֶה לְאוֹתָן אוֹתִיּוֹת, וְעַל כֵּן הוּקַם הַמִּשְׁכָּן עַל יָדוֹ, שֶׁכָּתוּב וַיָּקֶם מֹשֶׁה. וַיִּתֵּן מֹשֶׁה. וַיָּשֶׂם מֹשֶׁה. וּבְצַלְאֵל לֹא הָיָה יוֹדֵעַ, וְלֹא יָכוֹל הָיָה לְהַעֲמִידוֹ.</p>"],[9522011889,"<p>פָּתַח רַבִּי יִצְחָק אַחֲרָיו וְאָמַר, (תהלים כא) ה' בְּעָזְּךְ יִשְׂמַח מֶלֶךְ וּבִישׁוּעָתְךְ מַה יָּגֶיל מְאֹד תַּאֲוַת לִבּוֹ וְגוֹ', חַיִּים שָׁאַל מִמְּךְ וְגוֹ'. אֶת הַשִּׁירָה הַזּוֹ לֹא אָמַר דָּוִד אֶלָּא עַל תִּשְׁבַּחְתָּהּ שֶׁל כְּנֶסֶת יִשְׂרָאֵל, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מְשַׂמֵּחַ אוֹתָהּ בְּשִׂמְחַת הַתּוֹרָה שֶׁנִּקְרֵאת עֹז, שֶׁכָּתוּב (שם כט) ה' עֹז לְעַמּוֹ יִתֵּן וְגוֹ'. יִשְׂמַח מֶלֶךְ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא (זו כנסת ישראל) שֶׁנִּקְרָא מֶלֶךְ, שֶׁכָּתוּב (דברים לג) וַיְהִי בִישֻׁרוּן מֶלֶךְ.</p>\n<p>וּבִישׁוּעָתְךָ מַה יָּגֶיל מְאֹד - זוֹ יְשׁוּעַת הַיָּמִין, כְּמוֹ שֶׁנֶּאֱמַר (תהלים ס) הוֹשִׁיעָה יְמִינְךְ וַעֲנֵנִי. וַתּוֹשַׁע לוֹ יְמִינוֹ. (דבר אחר) מַה יָּגֶיל מְאֹד, י' יְתֵרָה, וְזֶהוּ סוֹד בְּרִית הַקֹּדֶשׁ, שֶׁהוּא שִׂמְחַת הַכֹּל (שלה), וְהַכֹּל נֶאֱמַר עַל הַמֶּלֶךְ הַזֶּה.</p>\n<p>חַיִּים שָׁאַל מִמְּךְ נָתַתָּה לּוֹ אֹרֶךְ יָמִים עוֹלָם וָעֶד. מִכָּאן לָמַדְנוּ שֶׁלְּדָוִד הַמֶּלֶךְ לֹא הָיוּ חַיִּים כְּלָל, פְּרָט לְזֶה שֶׁאָדָם הָרִאשׁוֹן נָתַן לוֹ מִשֶּׁלּוֹ. וַהֲרֵי בֵּאֲרוּהָ, שֶׁדָּוִד הַמֶּלֶךְ הִתְקַיֵּם שִׁבְעִים שָׁנָה, וְאוֹתָן שִׁבְעִים שָׁנִים נָתַן לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא מֵאוֹתָן שָׁנִים שֶׁל אָדָם הָרִאשׁוֹן, וּבָהֶן הוּא הִתְקַיֵּם, וְנִתְּנָה לוֹ אֲרִיכוּת יָמִים בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, וְעַל זֶה - חַיִּים שָׁאַל מִמְּךְ נָתַתָּה לּוֹ.</p>\n<p>גָּדוֹל כְּבוֹדוֹ, מִשּׁוּם שֶׁהוּא גָּדוֹל, שֶׁכָּתוּב (שם קמז) גָּדוֹל אֲדוֹנֵינוּ וְרַב כֹּחַ. וַדַּאי נִקְרָא גָּדוֹל, וְסוֹד זֶה - (בראשית א) וַיַּעַשׂ אֱלֹהִים אֶת שְׁנֵי הַמְּאֹרֹת הַגְּדלִים. גְּדוֹלִים הָיוּ וַדַּאי. וְעִם כָּל זֶה הוּא נִקְרָא גָּדוֹל, כְּמוֹ שֶׁנֶּאֱמַר גָּדוֹל אֲדוֹנֵינוּ וְרַב כֹּחַ. וְהַקָּדוֹשׁ בָּרוּךְ הוּא לֹא נִקְרָא גָּדוֹל אֶלָּא בָּזֶה, שֶׁכָּתוּב (תהלים מח) גָּדוֹל ה' וּמְהֻלָּל מְאֹד בְּעִיר אֱלֹהֵינוּ הַר קָדְשׁוֹ. בַּמָּה הוּא גָּדוֹל? בְּעִיר אֱלֹהֵינוּ הַר קָדְשׁוֹ.</p>\n<p>כִּי תְשִׁיתֵהוּ בְרָכוֹת לָעַד (תהליםכא). כִּי תְשִׁיתֵהוּ בְרָכוֹת, מִשּׁוּם שֶׁזּוֹהִי בִּרְכַּת כָּל הָעוֹלָם, וְכָל הַבְּרָכוֹת שֶׁל כָּל הָעוֹלָם מִכָּאן יוֹצְאוֹת, וְזוֹהִי בְּרָכָה. וְסוֹד זֶה - וֶהְיֵה בְּרָכָה. שֶׁהֲרֵי כָּאן שׁוֹרוֹת כָּל הַבְּרָכוֹת שֶׁלְּמַעְלָה וּמִכָּאן יוֹצְאוֹת לְכָל הָעוֹלָם, וְלָכֵן נִקְרֵאת בְּרָכָה.</p>\n<p>תְּחַדֵּהוּ בְשִׂמְחָה. כָּתוּב כָּאן תְּחַדֵּהוּ בְשִׂמְחָה, וְכָתוּב שָׁם (שמות יח) וַיִּחַדְּ יִתְרוֹ, מִשּׁוּם שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהָקִים אֶת כְּנֶסֶת יִשְׂרָאֵל מִן הֶעָפָר וּלְהַחֲזִיק בָּהּ בְּסוֹד הַיָּמִין, וּלְחַדֵּשׁ אוֹתָהּ חִדּוּשׁ הַלְּבָנָה בַּשֶּׁמֶשׁ.</p>\n<p>כָּתוּב תְּחַדֵּהוּ בְשִׂמְחָה אֶת פָּנֶיךְ. אֶת פָּנֶיךְ - לִהְיוֹת לְפָנֶיךְ וְלִהְיוֹת בְּשִׂמְחָה כְּנֶגֶד פָּנֶיךְ בְּאוֹתָהּ שְׁלֵמוּת שֶׁתִּשְׁתַּלֵּם בְּאוֹתוֹ הַזְּמַן, שֶׁהֲרֵי בִּזְמַן שֶׁנֶּחֱרַב בֵּית הַמִּקְדָּשׁ, הִתְרוֹקְנָה מִכָּל מַה שֶּׁהִתְמַלְּאָה, כְּמוֹ שֶׁנֶּאֱמַר (ירמיהטו) אֻמְלָלָה יֹלֶדֶת הַשִּׁבְעָה. וְכָתוּב (יחזקאל כו) אִמָּלְאָה הָחֳרָבָה.</p>"],[9522011890,"<p>בֹּא וּרְאֵה, בְּאוֹתוֹ זְמַן שֶׁהֵקִים מֹשֶׁה אֶת הַמִּשְׁכָּן, הִסְתַּכֵּל בְּכָל אוֹתָן הָעֲבוֹדוֹת שֶׁהָיוּ כָּרָאוּי, וְאָז הֵקִים אוֹתוֹ. וְכָל אוֹתָן הָעֲבוֹדוֹת שֶׁיִּהְיוּ בוֹ בַּמִּשְׁכָּן, אֶת כָּל אַחַת וְאַחַת הֵבִיאוּ לְמֹשֶׁה. וְסוֹד זֶה - (תהלים מה) בְּתוּלוֹת אַחֲרֶיהָ רֵעוֹתֶיהָ מוּבָאוֹת לָךְ. מוּבָאוֹת לָךְ, שֶׁכָּתוּב וַיָּבִיאוּ אֶת הַמִּשְׁכָּן אֶל מֹשֶׁה.</p>\n<p>לָמָּה וַיָּבִיאוּ אֶל הַמִּשְׁכָּן? מִשּׁוּם שֶׁהֲרֵי בְּאוֹתָהּ שָׁעָה הָיָה הַזִּוּוּג שֶׁל מֹשֶׁה לְהִזְדַּוֵּג, וְעַל זֶה וַיָּבִיאוּ אֶת הַמִּשְׁכָּן אֶל מֹשֶׁה, כְּמוֹ שֶׁמְּבִיאִים כַּלָּה לְבֵית הֶחָתָן. מִשּׁוּם שֶׁבָּרִאשׁוֹנָה צָרִיךְ לְהַכְנִיס אֶת הַכַּלָּה לֶחָתָן, כְּמוֹ שֶׁנֶּאֱמַר (דברים כב) אֶת בִּתִּי נָתַתִּי לָאִישׁ הַזֶּה לְאִשָּׁה. וְאַחַר כָּךְ הוּא יָבֹא אֵלֶיהָ, שֶׁכָּתוּב (בראשית ל) וַיָּבֹא אֵלֶיהָ. וְכָתוּב (במדבר יז) וַיָּבֹא מֹשֶׁה אֶל אֹהֶל הָעֵדוּת.</p>\n<p>וְכָאן מַה כָּתוּב? וְלֹא יָכֹל מֹשֶׁה לָבֹא אֶל אֹהֶל מוֹעֵד כִּי שָׁכַן עָלָיו הֶעָנָן וְגוֹ'. מָה הַטַּעַם? מִשּׁוּם שֶׁהִיא הָיְתָה מִתְתַּקֶּנֶת, כְּאִשָּׁה הַזּוֹ שֶׁמִּתְתַּקֶּנֶת וּמִתְקַשֶּׁטֶת לְבַעְלָהּ, וּבְאוֹתָהּ שָׁעָה שֶׁהִיא מִתְקַשֶּׁטֶת, לֹא רָאוּי לְבַעְלָהּ לְהִכָּנֵס אֵלֶיהָ. וְעַל כֵּן, וְלֹא יָכֹל מֹשֶׁה לָבֹא אֶל אֹהֶל מוֹעֵד כִּי שָׁכַן עָלָיו הֶעָנָן. מִשּׁוּם כָּךְ, וַיָּבִיאוּ אֶת הַמִּשְׁכָּן אֶל מֹשֶׁה. עוֹד מַה כָּתוּב? וַיַּרְא מֹשֶׁה אֶת כָּל הַמְּלָאכָה וְגוֹ'.</p>\n<p>בֹּא וּרְאֵה, בְּכָל הַמַּעֲשִׂים שֶׁל הַמִּשְׁכָּן, בְּכֻלָּם הָיָה גָּוֶן שֶׁל תְּכֵלֶת, מִשּׁוּם שֶׁתְּכֵלֶת הוּא גָּוֶן לְהִתְעַטֵּר בְּסוֹד כָּל הַגְּוָנִים. מַה כָּתוּב? וַיַּעֲשׂוּ אֶת צִיץ נֵזֶר הַקֹּדֶשׁ וְגוֹ', וַיִּתְּנוּ עָלָיו פְּתִיל תְּכֵלֶת וְגוֹ', וַהֲרֵי פֵּרְשׁוּהָ בְּסוֹד הַכָּתוּב, (שמות כח) וְעָשִׂיתָ צִּיץ זָהָב טָהוֹר וּפִתַּחְתָּ עָלָיו פִּתּוּחֵי חֹתָם קֹדֶשׁ לַה'. וַיִּכְתְּבוּ עָלָיו מִכְתַּב פִּתּוּחֵי חוֹתָם קֹדֶשׁ לַה'.</p>"],[9522011891,"<p>בַּסּוֹדוֹת הָעֶלְיוֹנִים. צוּרוֹת קְמוּטוֹת נִמְצָאוֹת, אֵלּוּ עוֹלוֹת וְיוֹרְדוֹת וְאֵלּוּ עוֹמְדוֹת עַל קִיּוּמָן. גַּלְגַּלִּים הַסּוֹבְבִים הָיוּ קַיָּמִים מֵאוֹתוֹ זְמַן שֶׁהֶעָפָר הִתְכַּנֵּס. אֵלּוּ הַגַּלְגַּלִּים סוֹבְבִים הָעוֹלָם בְּסִבּוּב.</p>\n<p>בַּסִּבּוּב שֶׁסּוֹבְבִים הַמִּדְבָּרִיּוֹת, שְׁלִיטַת הַקְּלִיטָה בְּתוֹכָם. גַּלְגַּל אֶחָד יֵשׁ בְּתוֹכָם. הַגַּלְגַּל הַזֶּה סוֹבֵב וְלֹא סוֹבֵב, עוֹמֵד בִּשְׁנֵים עָשָׂר אֶלֶף עוֹלָמוֹת וְנִמְצָא בֵינֵיהֶם, עוֹלֶה וְיוֹרֵד בְּתוֹכָם.</p>\n<p>תַּחַת אוֹתוֹ גַּלְגַּל עוֹמֵד עַמּוּד אֶחָד שֶׁנָּעוּץ עַד לַתְּהוֹם הַגְּדוֹלָה, וּבוֹ מִתְגַּלְגְּלִים אֲבָנִים בְּתוֹךְ הַתְּהוֹמוֹת, הֵם עוֹלִים וְיוֹרְדִים. וְאוֹתוֹ עַמּוּד עוֹמֵד עֲלֵיהֶם, נוֹסֵעַ וְלֹא נוֹסֵעַ, נָעוּץ מִלְמַעְלָה לְמַטָּה, סוֹבְבִים מָאתַיִם וְעֶשְׂרִים גַּלְגַּלִּים אֲחֵרִים סְבִיב אוֹתוֹ הָעַמּוּד.</p>\n<p>אוֹתוֹ גַּלְגַּל אַחֵר שֶׁעָלָיו שֶׁעוֹמֵד בִּשְׁנֵים עָשָׂר אֶלֶף עוֹלָמוֹת, הוּא סוֹבֵב לְתוֹךְ הַמִּשְׁכָּן, סוֹבֵב וְלֹא סוֹבֵב. אוֹתוֹ מִשְׁכָּן עוֹמֵד עַל שְׁנֵים עָשָׂר אֶלֶף עוֹלָמוֹת, וּבוֹ עוֹמֵד אוֹתוֹ כָּרוֹז שֶׁקּוֹרֵא: הִשָּׁמְרוּ מֵהַגַּלְגַּל שֶׁסּוֹבֵב.</p>\n<p>מִי שֶׁהוּא בַּעַל עֵינַיִם בְּהַשְׂכֵּל, יֵדַע וְיִתְבּוֹנֵן בְּחָכְמַת רִבּוֹנוֹ, וְיֵדַע שֶׁאוֹתָם דְּבָרִים עֶלְיוֹנִים שֶׁמַּפְתְּחוֹת רִבּוֹנוֹ עוֹמְדִים שָׁם, שֶׁהֵם טְמוּנִים בְּתוֹךְ הַמִּשְׁכָּן הַקָּדוֹשׁ. אַשְׁרֵיהֶם בָּעוֹלָם הַזֶּה וְאַשְׁרֵיהֶם בָּעוֹלָם הַבָּא. עֲלֵיהֶם כָּתוּב, (תהלים פד) אַשְׁרֵי אָדָם עוֹז לוֹ בָךְ מְסִלּוֹת בִּלְבָבָם. (שם סה) אַשְׁרֵי תִּבְחַר וּתְקָרֵב יִשְׁכֹּן חֲצֵרֶיךְ נִשְׂבְּעָה בְּטוּב בֵּיתֶךְ קְדֹשׁ הֵיכָלֶךְ.</p>"],[9522011892,"<p>בְּסוֹד הַמִּשְׁכָּן עוֹמְדִים סוֹדוֹת עֶלְיוֹנִים בְּסוֹד הַשֵּׁם הַקָּדוֹשׁ (העליון) אֲדֹנָ\"י, זֶהוּ סוֹד הַמִּשְׁכָּן, כְּמוֹ הַסּוֹד הָעֶלְיוֹן, סוֹד הָאָרוֹן, כַּכָּתוּב (יהושע ג) הִנֵּה אֲרוֹן הַבְּרִית אֲדוֹן כָּל הָאָרֶץ. אֲדוֹן כָּל הָאָרֶץ - זֶהוּ הַסּוֹד הַקָּדוֹשׁ שֶׁל הַשֵּׁם שֶׁל אָלֶ\"ף דָּלֶ\"ת נוּ\"ן יוֹ\"ד. וְזֶהוּ כְּמוֹ שֶׁהַסּוֹד שֶׁל הַשֵּׁם הַקָּדוֹשׁ הָעֶלְיוֹן יְדֹוָ\"ד. וְהָאוֹתִיּוֹת הַלָּלוּ כְּמוֹ הַלָּלוּ.</p>\n<p>א' הִיא י', סוֹד שֶׁל יוֹ\"ד (זה) כְּמוֹ זֶה א', וַהֲרֵי פֵּרְשׁוּהָ. ד' הִיא סוֹד ה', וְזֶה כְּמוֹ זֶה, וְהַכֹּל כְּצוּרָה וְסוֹד שֶׁל אֶחָד. נ' הִיא סוֹד הָאוֹת ו'. וְאַף עַל גַּב שֶׁזֶּה זָכָר וְזוֹ נְקֵבָה, אֲבָל זוֹ נִכְלֶלֶת בָּזוֹ, וַהֲרֵי פֵּרְשׁוּהָ ן' ו' הִיא בָּאֶמְצַע, מִשּׁוּם שֶׁהוּא כְּלָל אֶחָד. ה' הִיא סוֹד הָאוֹת י', (י' היא סוד האות ה') מִשּׁוּם שֶׁכָּאן (של ה') זוֹהִי חָכְמָה קְטַנָּה, שֶׁנִּקְרֵאת חָכְמַת שְׁלֹמֹה.</p>\n<p>וְהָאוֹתִיּוֹת נִכְלְלוּ אֵלֶּה בְּאֵלֶּה, וְהַכֹּל הוּא סוֹד אֶחָד, כְּלוּלִים אֵלֶּה בְּאֵלֶּה, וְהַכֹּל אֶחָד, וְהַכֹּל הוּא סוֹד אֶחָד בְּאוֹתִיּוֹת קְדוֹשׁוֹת. וְלָכֵן הַמִּשְׁכָּן שֶׁלְּמַטָּה בָּאָרֶץ עוֹמֵד בְּסוֹד הַמִּשְׁכָּן הָעֶלְיוֹן, וְאוֹתוֹ מִשְׁכָּן עֶלְיוֹן עוֹמֵד בְּסוֹד שֶׁל מִשְׁכָּן אַחֵר עֶלְיוֹן עַל הַכֹּל. וְהַכֹּל כָּלוּל זֶה בָּזֶה לִהְיוֹת אֶחָד, וְלָכֵן כָּתוּב (שמות כו) וְהָיָה הַמִּשְׁכָּן אֶחָד.</p>"],[9522011893,"<p>כָּתוּב, (במדבר כד) רֵאשִׁית גּוֹיִם עֲמָלֵק וְאַחֲרִיתוֹ עֲדֵי אֹבֵד. בֹּא וּרְאֵה, בַּיּוֹם שֶׁהוּקַם הַמִּשְׁכָּן שֶׁהֵקִים אוֹתוֹ מֹשֶׁה, כְּמוֹ שֶׁנֶּאֱמַר, שֶׁכָּתוּב וַיָּקֶם מֹשֶׁה אֶת הַמִּשְׁכָּן, שֶׁלֹּא הָיָה יָכוֹל לָקוּם עַד שֶׁהוּא הֵקִים אוֹתוֹ. לִגְבִירָה שֶׁאֵין רְשׁוּת לְאִישׁ אַחֵר לַהֲקִימָהּ אֶלָּא בַּעְלָהּ. אַף כָּאן, כָּל אוֹתָם הָאֻמָּנִים, כֻּלָּם בָּאוּ לְהָקִים אֶת הַמִּשְׁכָּן, וְלֹא יָכֹל לַעֲמֹד עַל יְדֵיהֶם, עַד שֶׁבָּא מֹשֶׁה וְהֵקִים אוֹתוֹ, מִשּׁוּם שֶׁהוּא הָיָה בַּעַל הַבַּיִת.</p>\n<p>כֵּיוָן שֶׁהֵקִים מֹשֶׁה אֶת הַמִּשְׁכָּן לְמַטָּה, הוּקַם מִשְׁכָּן אַחֵר לְמַעְלָה, כְּמוֹ שֶׁבֵּאֲרוּהָ, שֶׁכָּתוּב הוּקַם, וְלֹא פֵרַשׁ עַל יְדֵי מִי. (אלא) שֶׁלֹּא הוּקַם אֶלָּא מִסּוֹד הָעוֹלָם הָעֶלְיוֹן, שֶׁהוּא נִסְתָּר וְגָנוּז, עַל יְדֵי הַסּוֹד שֶׁל מֹשֶׁה, כְּדֵי לְהִתְתַּקֵּן עִמּוֹ.</p>\n<p>מַה כָּתוּב לְמַעְלָה? (שמות לו) וַיָּבֹאוּ כָּל הַחֲכָמִים הָעֹשִׂים אֵת כָּל מְלֶאכֶת הַקֹּדֶשׁ וְגוֹ'. מִי הֵם הַחֲכָמִים הָעֹשִׂים? אֵלּוּ הֵם יָמִין וּשְׂמֹאל וְכָל שְׁאָר הַצְּדָדִים, שֶׁהֵם דְּרָכִים וּשְׁבִילִים לְהִכָּנֵס לְתוֹךְ הַיָּם וּלְמַלֵּא אוֹתוֹ, וְהֵם עָשׂוּ אֶת הַמִּשְׁכָּן לְמַעְלָה וְהִתְקִינוּ אוֹתוֹ.</p>\n<p>כְּמוֹ כֵן לְמַטָּה, (שם) וְעָשָׂה בְצַלְאֵל וְאָהֳלִיאָב. זֶה בְּצַד יָמִין, וְזֶה בְּצַד שְׂמֹאל. בְּצַלְאֵל לְיָמִין, וְאָהֳלִיאָב לִשְׂמֹאל. זֶה מִיהוּדָה, וְזֶה מִדָּן. וְאַחַר כָּךְ - וְכֹל אִישׁ חֲכַם לֵב, וַיָּבֹאוּ כָּל הַחֲכָמִים הָעֹשִׂים. וַהֲרֵי בֵּאַרְנוּ, וְהַכֹּל כְּמוֹ שֶׁלְּמַעְלָה.</p>\n<p>בְּאוֹתוֹ יוֹם שֶׁהוּקַם הַמִּשְׁכָּן הִתְבַּטֵּל הַמָּוֶת מֵהָעוֹלָם. אַל תֹּאמַר הִתְבַּטֵּל, אֶלָּא הִסְתַּלֵּק מִן הָעוֹלָם, שֶׁלֹּא יָכֹל לִשְׁלֹט, כְּמוֹ שֶׁבֵּאַרְנוּ. מִשּׁוּם שֶׁלֹּא יִתְבַּטֵּל יֵצֶר הָרָע מֵהָעוֹלָם עַד שֶׁיָּבֹא מֶלֶךְ הַמָּשִׁיחַ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא יִשְׂמַח בְּמַעֲשָׂיו, וְאָז - (ישעיה כה) בִּלַּע הַמָּוֶת לָנֶצַח. כְּשֶׁהוּקַם הַמִּשְׁכָּן עַל יְדֵי מֹשֶׁה, אָז נִפְרַד כֹּחַ הַיֵּצֶר הָרָע וְנִכְנַע וְלֹא יָכֹל לִשְׁלֹט. בְּאוֹתָהּ שָׁעָה נִפְרַד סָמָאֵ\"ל, כֹּחַ הָרֹגֶז שֶׁל הַשְּׂמֹאל, מֵעַל תֹּקֶף הַנָּחָשׁ הָרָע, וְלֹא יָכֹל לִשְׁלֹט עַל הָעוֹלָם וְלֹא יָכֹל לְהִתְחַבֵּר בְּאָדָם וּלְהַסְטוֹת אוֹתוֹ.</p>\n<p>רַבִּי יְהוּדָה אָמַר, כְּשֶׁעָשׂוּ יִשְׂרָאֵל אֶת הָעֵגֶל, מַה כָּתוּב? (שמות לג) וּמֹשֶׁה יִקַּח אֶת הָאֹהֶל וְנָטָה לוֹ מִחוּץ לַמַּחֲנֶה. מָה הַטַּעַם? מִשּׁוּם שֶׁרָאָה יֵצֶר הָרָע שֶׁהָיָה הוֹלֵךְ בֵּינֵיהֶם. אָמַר מֹשֶׁה: צַד הַקְּדֻשָּׁה לֹא יִשְׁרֶה בְּתוֹךְ צַד הַטֻּמְאָה. רַבִּי אֶלְעָזָר אוֹמֵר, כָּל זְמַן שֶׁצַּד הַקְּדֻשָּׁה שׁוֹלֵט, צַד הַטֻּמְאָה לֹא יָכוֹל לִשְׁלֹט וְנִכְנָע לְפָנָיו. וְעַל כֵּן שָׁנִינוּ, כָּל זְמַן שֶׁיְּרוּשָׁלַיִם תִּהְיֶה מְלֵאָה - צוֹר הָרְשָׁעָה תִּהְיֶה חֲרֵבָה.</p>"],[9522011894,"<p>פָּתַח וְאָמַר, (בראשית כד) וַתֹּאמֶר אֶל הָעֶבֶד מִי הָאִישׁ הַלָּזֶה הַהֹלֵךְ בַּשָּׂדֶה לִקְרָאתֵנוּ וַיֹּאמֶר הָעֶבֶד וְגוֹ'. מַה כָּתוּב לְמַעְלָה? וַתִּשָּׂא רִבְקָה אֶת עֵינֶיהָ וַתֵּרֶא אֶת יִצְחָק וַתִּפֹּל מֵעַל הַגָּמָל.</p>\n<p>מַדּוּעַ הֻצְרַךְ לִכְתֹּב אֶת הַפָּסוּק הַזֶּה בַּתּוֹרָה? וְעוֹד, וְכִי מִשּׁוּם שֶׁרָאֲתָה אֶת יָפְיוֹ שֶׁל יִצְחָק (מה הטעם) נִשְׁמְטָה מִן הַגָּמָל? אֶלָּא, פָּסוּק זֶה הוּא סוֹד. בֹּא רְאֵה, (ותרא את יצחק. מגין ידעה שהוא יצחק, ' אלא ותרא את יצחק, ראתה באותה שעה מה שלא ידעה) (בא וראה, בשעה שהגיעה רבקה אל יצחק, שעת תפלת המנחה היתה, ובאותו זמן מתעורר דיןבעולם), וְרָאֲתָה אוֹתוֹ בְּרֹגֶז הַדִּין הַקָּשֶׁה, וְרָאֲתָה שֶׁהֲרֵי סִיּוּם הָרֹגֶז הַקָּשֶׁה הוּא גָּמָל לְמַטָּה, וְזֶהוּ סוֹד הַמָּוֶת. וּמִשּׁוּם כָּךְ נִרְכְּנָה וְהִשְׁמִיטָה עַצְמָהּ מֵאוֹתוֹ הַגָּמָל. שֶׁהֲרֵי כְּשֶׁמִּסְתַּכֵּל הַדִּין הַקָּשֶׁה, אוֹתוֹ גָּמָל מִתְחַזֵּק. וּמִשּׁוּם כָּךְ הִשְׁמִיטָה אֶת עַצְמָהּ מִמֶּנּוּ (סוד של המות. וכאשר הדין הקשה הזה התעורר, אותו גמל התחזק, ומשום כך הרכינה והשמיטה עצמה מאותו גמל) וְלֹא יָשְׁבָה שָׁם.</p>"],[9522011895,"<p>בֹּא וּרְאֵה, הַגָּמָל הַזֶּה הַיְנוּ סוֹד הַכָּתוּב (משלי יט) וּגְמֻלוֹ יְשַׁלֶּם לוֹ. זֶהוּ גְּמוּל אוֹתָם הָרְשָׁעִים, שֶׁכָּתוּב (ישעיהג) אוֹי לְרָשָׁע רָע כִּי גְמוּל יָדָיו יֵעָשֶׂה לּוֹ. וְזֶהוּ הַגָּמָל שֶׁעוֹמֵד לֶאֱכֹל הַכֹּל וּלְהַשְׁמִיד הַכֹּל, וְזֶהוּ שֶׁמְּזֻמָּן תָּמִיד כְּנֶגֶד (להרג נ\"א להזיק) בְּנֵי הָאָדָם. וּמִשּׁוּם כָּךְ, מִי שֶׁרוֹאֶה בַחֲלוֹמוֹ גָּמָל, הֶרְאוּ לוֹ מָוֶת שֶׁנִּגְזַר עָלָיו וְנִצַּל מִמֶּנּוּ.</p>\n<p>בֹּא וּרְאֵה, צַד הַטֻּמְאָה הַזֶּה נִקְרָא כָּךְ - שֶׁגָּרַם מָוֶת לְכָל הָעוֹלָם, וְזֶה הָיָה שֶׁהִסְטָה אֶת אָדָם וְאֶת אִשְׁתּוֹ, וְאוֹתוֹ שֶׁרָכַב עָלָיו הוּא סָמָאֵ\"ל, וְהוּא בָּא לְהַטְעוֹת אֶת הָעוֹלָם וְגָרַם מָוֶת לָכֹּל, וּמִשּׁוּם כָּךְ בָּא וְשׁוֹלֵט עַל הַכֹּל. אָדָם הוּא שֶׁהִמְשִׁיךְ אוֹתוֹ אֵלָיו, וְכֵיוָן שֶׁהִמְשִׁיךְ אוֹתוֹ אֵלָיו, אָז הוּא נִמְשַׁךְ אַחֲרֵיהֶם עַד שֶׁהִסְטָה אוֹתָם. וּמִשּׁוּם כָּךְ אָמַר שְׁלֹמֹה, (משליה) וְאַל תִּקְרַב אֶל פֶּתַח בֵּיתָהּ. שֶׁכָּל מִי שֶׁמִּתְקָרֵב לְבֵיתָהּ, אָז הִיא יוֹצֵאת וְנִקְשֶׁרֶת וְנִמְשֶׁכֶת אַחֲרָיו.</p>\n<p>וְעַל זֶה רִבְקָה, כְּשֶׁרָאֲתָה שֶׁהָיָה לוֹ לִדְבֹּק בְּצַד הַדִּין הַקָּשֶׁה, כֵּיוָן שֶׁרָאֲתָה אֶת יִצְחָק בְּסוֹד הַדִּין הַקָּשֶׁה וְרָאֲתָה שֶׁמֵּאוֹתוֹ צַד יוֹצֵא דִין אַחֵר תַּקִּיף מִזֻּהֲמַת הַזָּהָב, כְּשֶׁרָאֲתָה אֶת זֶה, מִיָּד - וַתִּפֹּל מֵעַל הַגָּמָל, כְּדֵי לְהִתְרַפּוֹת מִן הַדִּין מֵאוֹתָהּ זֻהֲמָה. כָּתוּב (ישעיה סו) קוֹל ה' מְשַׁלֵּם גְּמוּל לְאֹיְבָיו, מֵאוֹתָהּ זֻהֲמָה.</p>"],[9522011896,"<p>בֹּא וּרְאֵה, כְּשֶׁעָשׂוּ יִשְׂרָאֵל אוֹתוֹ מַעֲשֶׂה וְגָרְמוּ אֶת אוֹתוֹ הַחֵטְא, מָה הַטַּעַם עֵגֶל וְלֹא צַד אַחֵר? וְאִם תֹּאמְרוּ שֶׁהֵם בָּחֲרוּ עֵגֶל - לֹא כָּךְ! אֶלָּא הֵם אָמְרוּ, (שמותלב) קוּם עֲשֵׂה לָנוּ אֱלֹהִים אֲשֶׁר יֵלְכוּ לְפָנֵינוּ, וּרְצוֹנוֹ שֶׁל אַהֲרֹן הָיָה לְעַכֵּב אוֹתָם.</p>\n<p>אֶלָּא וַדַּאי הַמַּעֲשֶׂה נַעֲשָׂה כָּרָאוּי, שֶׁהֲרֵי מִצַּד הַזָּהָב יוֹצֵאת פְּסֹלֶת כְּשֶׁנִּבְרָר הַזָּהָב, וּמִשָּׁם מִתְפַּשְּׁטִים כָּל אוֹתָם צִדְדֵי הַשְּׂמֹאל, שֶׁהֵם הִתּוּכוֹ שֶׁל אוֹתָהּ פְּסֹלֶת שֶׁל הַזָּהָב, וְנִפְרָדִים לְכַמָּה צְדָדִים. וְכָל אוֹתָם שֶׁיֵּשׁ לָהֶם מַרְאֶה אָדם, גָּוֶן שֶׁל זָהָב עוֹמֵד בֶּהָרִים, כְּשֶׁהַשֶּׁמֶשׁ בְּתָקְפּוֹ, מִשּׁוּם שֶׁתֹּקֶף הַשֶּׁמֶשׁ מַרְאֶה זָהָב, וּמוֹלִיד אוֹתוֹ בָּאָרֶץ. וְאוֹתוֹ שֶׁמְּמֻנֶּה בְּאוֹתוֹ הַתֹּקֶף שֶׁל הַשֶּׁמֶשׁ, הַמַּרְאֶה שֶׁלּוֹ כְּעֵגֶל, וְנִקְרָא (תהלים צא) קֶטֶב יָשׁוּד צָהֳרָיִם, וְזֶה יוֹצֵא מִתּוֹךְ עֵגֶל הִתּוּךְ הָאָדם שֶׁל הַזָּהָב, וְכָל אֵלֶּה בָּאִים מֵאוֹתוֹ הַצַּד הָאָדם, רוּחַ הַטֻּמְאָה, שֶׁכָּל אוֹתָם שֶׁנִּפְרָדִים מֵרוּחַ הַטֻּמְאָה מִתְפַּשְּׁטִים בָּעוֹלָם.</p>\n<p>וְרוּחַ הַטֻּמְאָה הַזּוֹ הִיא הַנָּחָשׁ הָרָע, וְיֵשׁ מִי שֶׁרוֹכֵב עָלָיו, וְהֵם זָכָר וּנְקֵבָה, וְנִקְרָאִים אֵלֶּה, שֶׁהֵם מִזְדַּמְּנִים בָּעוֹלָם בְּכָל אוֹתָם הַצְּדָדִים שֶׁלָּהֶם, וְרוּחַ הַקֹּדֶשׁ נִקְרֵאת זאת, שֶׁהִיא סוֹד הַבְּרִית, הָרֹשֶׁם הַקָּדוֹשׁ שֶׁנִּמְצָא תָמִיד עִם הָאָדָם. וְכֵן (ישעיה כה) זֶה ה', (שמות טו) זֶה אֵלִי. אֲבָל אֵלּוּ נִקְרָאִים אֵלֶּה, וְעַל זֶה כָּתוּב אֵלֶּה אֱלֹהֶיךְ יִשְׂרָאֵל. וּמִשּׁוּם כָּךְ כָּתוּב (ישעיהמט) גַּם אֵלֶּה תִשְׁכַּחְנָה, וְאָנֹכִי - סוֹד שֶׁל זאת - לֹא אֶשְׁכָּחֵךְ. וְכָתוּב (איכה א) עַל אֵלֶּה אֲנִי בוֹכִיָּה. שֶׁאוֹתוֹ חֵטְא גָּרַם לָהֶם לִבְכּוֹת כַּמָּה בְכִיּוֹת.</p>\n<p>דָּבָר אַחֵר עַל אֵלֶּה אֲנִי בוֹכִיָּה, מָה הַטַּעַם? מִשּׁוּם שֶׁנִּתְּנָה רְשׁוּת לַמָּקוֹם הַזֶּה לִשְׁלֹט עַל יִשְׂרָאֵל וּלְהַחֲרִיב אֶת בֵּית הַמִּקְדָּשׁ, וּמִשּׁוּם שֶׁנִּתְּנָה לָהֶם רְשׁוּת לִשְׁלֹט, כָּתוּב עַל אֵלֶּה אֲנִי בוֹכִיָּה. סוֹד הַדָּבָר עַל אֵלֶּה - זֶהוּ צַד הַטֻּמְאָה שֶׁנִּתְּנָה לָהֶם רְשׁוּת לִשְׁלֹט. אֲנִי בוֹכִיָּה - זוֹ רוּחַ הַקֹּדֶשׁ שֶׁנִּקְרֵאת אֲנִי.</p>\n<p>וְאִם תֹּאמַר, הֲרֵי כָּתוּב (דברים כח) אֵלֶּה דִּבְרֵי הַבְּרִית - כָּךְ הוּא וַדַּאי. שֶׁכָּל אוֹתָם שֶׁלֹּא מִתְקַיְּמִים אֶלָּא מִתּוֹךְ אֵלֶּה, שֶׁשָּׁם כָּל הַקְּלָלוֹת, כְּמוֹ שֶׁבֵּאַרְנוּ שֶׁהוּא אָרוּר, שֶׁכָּתוּב (בראשיתג) אָרוּר אַתָּה מִכָּל הַבְּהֵמָה. וּמִשּׁוּם כָּךְ הִקְדִּים וְאָמַר אֵלֶּה, שֶׁעוֹמֵד לְמִי שֶׁעָבַר דִּבְרֵי הַבְּרִית. (ויקרא כז) אֵלֶּה הַמִּצְות אֲשֶׁר צִוָּה ה' אֶת מֹשֶׁה, מִשּׁוּם שֶׁמִּצְווֹת הַתּוֹרָה לְטַהֵר אֶת הָאָדָם, וְלֹא יִסְטֶה מֵהַדֶּרֶךְ הַזּוֹ, וְיִשָּׁמֵר מִשָּׁם וְיִפָּרֵד מֵהֶם.</p>\n<p>וְאִם תֹּאמַר, (בראשית ו) אֵלֶּה תּוֹלְדֹת נֹחַ נֹחַ - כָּךְ הוּא וַדַּאי. שֶׁהֲרֵי יָצָא חָם, שֶׁהוּא אֲבִי כְנַעַן, וְכָתוּב (שם ט) אָרוּר כְּנָעַן, וְהוּא סוֹד זֶה שֶׁל אֵלֶּה.</p>\n<p>וְעַל זֶה כָּל אֵלֶּה הִתּוּךְ פְּסֹלֶת הַזָּהָב, וְאַהֲרֹן הִקְרִיב זָהָב, שֶׁהוּא הַצַּד (האחר) שֶׁלּוֹ, שֶׁהוּא כָּלוּל בְּתֹקֶף הָאֵשׁ, וְהַכֹּל אֶחָד, וְצַד זֶה זָהָב וְאֵשׁ.</p>\n<p>וְרוּחַ הַטֻּמְאָה שֶׁתָּמִיד נִמְצֵאת בַּמִּדְבָּר, מָצְאָה מָקוֹם בְּאוֹתוֹ זְמַן לְהִתְחַזֵּק בּוֹ. וּמַה שֶּׁהָיוּ יִשְׂרָאֵל טְהוֹרִים מֵאוֹתָהּ זֻהֲמָה רִאשׁוֹנָה שֶׁהִטִּיל בָּעוֹלָם וְגָרַם מָוֶת לַכֹּל - כְּשֶׁעָמְדוּ עַל הַר סִינַי גָּרַם לָהֶם כְּמוֹ מִקֹּדֶם לְטַמֵּא אוֹתָם וּלְהִתְגַּבֵּר עֲלֵיהֶם, וְגָרַם מָוֶת לָהֶם וּלְכָל הָעוֹלָם וּלְדוֹרוֹתֵיהֶם אַחֲרֵיהֶם. זֶהוּ שֶׁכָּתוּב (תהלים פב) אֲנִי אָמַרְתִּי אֱלֹהִים אַתֶּם וְגוֹ'. אָכֵן כְּאָדָם תְּמוּתוּן וְגוֹ'. וּמִשּׁוּם כָּךְ אַהֲרֹן חָזַר אַחַר כָּךְ לְהִטָּהֵר בְּסוֹד הָאֱמוּנָה הָעֶלְיוֹנָה בְּאוֹתָם שִׁבְעָה יָמִים קְדוֹשִׁים, וְאַחַר כָּךְ לְהִטָּהֵר בָּעֵגֶל.</p>"],[9522011897,"<p>וּבֹא רְאֵה, בַּכֹּל רָצָה אַהֲרֹן לְהִטָּהֵר, שֶׁאִלּוּ הוּא לֹא הָיָה, לֹא הָיָה יוֹצֵא עֵגֶל. מָה הַטַּעַם? מִשּׁוּם שֶׁאַהֲרֹן הוּא יָמִין, וְהוּא חֹזֶק הַשֶּׁמֶשׁ, וְהַזָּהָב מֵהַשֶּׁמֶשׁ. רוּחַ טֻמְאָה יָרְדָה וְנִכְלְלָה שָׁם, וְיִשְׂרָאֵל נִטְמְאוּ, וְהוּא נִטְמָא, עַד שֶׁנִּטַּהֲרוּ.</p>\n<p>מָה הַטַּעַם נִטְמָא? מִשּׁוּם שֶׁיָּצָא עֵגֶל, שֶׁהוּא מִצַּד הַשְּׂמֹאל, שֶׁהוּא שׁוֹר, וּמִימִינוֹ עֵגֶל. וְהוּא שְׂמֹאל כְּמוֹ שֶׁנֶּאֱמַר, שֶׁכָּתוּב וּפְנֵי שׁוֹר מֵהַשְּׂמֹאול לְאַרְבַּעְתָּן. וְאַהֲרֹן שֶׁהוּא יָמִין, נִכְלָל בּוֹ שְׂמֹאל וְיָצָא עַל יָדוֹ. וְעַל כֵּן נִתַּן לוֹ עֵגֶל, כְּמוֹ שֶׁהוּא גָּרַם.</p>\n<p>וּמִשּׁוּם כָּךְ, כְּשֶׁרוּחַ הַטֻּמְאָה הַזּוֹ מִתְגַּבֶּרֶת וְשׁוֹלֶטֶת כְּמִקֹּדֶם עַל הָעוֹלָם, שֶׁהֲרֵי בִּזְמַן שֶׁחָטְאוּ יִשְׂרָאֵל, הִמְשִׁיכוּ עֲלֵיהֶם אוֹתוֹ יֵצֶר הָרָע כְּמִקֹּדֶם. כְּשֶׁנִּטְהֲרוּ יִשְׂרָאֵל וְרָצוּ לְהִטָּהֵר, הִצְטָרְכוּ לְהַקְרִיב שָׂעִיר, מִשּׁוּם שֶׁשָּׂעִיר הוּא חֶלְקוֹ שֶׁל אוֹתוֹ יֵצֶר הָרָע, אוֹתוֹ רוּחַ טֻמְאָה שֶׁאָמַרְנוּ.</p>\n<p>כָּתוּב (תהלים קו) וַיָּמִירוּ אֶת כְּבוֹדָם בְּתַבְנִית שׁוֹר אֹכֵל עֵשֶׂב. מַה זֶּה תַּבְנִית שׁוֹר? זֶה עֵגֶל. שׁוֹר מִצַּד הַשְּׂמֹאל, אַהֲרֹן יָמִין, וְנִכְלָל בּוֹ שְׂמֹאל וְהִתְגַּבֵּר בּוֹ וְיָצָא עַל יָדוֹ. בּא וּרְאֵה, וַיָּמִירוּ אֶת כְּבוֹדָם - זוֹ שְׁכִינָה שֶׁהָלְכָה לִפְנֵיהֶם, וְהֶחֱלִיפוּ אוֹתָהּ בְּמָקוֹם טָמֵא, אֵל אַחֵר. וּמִשּׁוּם כָּךְ לֹא עָבְרָה הַזֻּהֲמָה הַזּוֹ מֵהָעוֹלָם עַד אוֹתוֹ זְמַן שֶׁיַּעֲבִירֶנָּה הַקָּדוֹשׁ בָּרוּךְ הוּא מֵהָעוֹלָם, כְּמוֹ שֶׁנֶּאֱמַר (זכריה יג) וְאֶת רוּחַ הַטֻּמְאָה אַעֲבִיר מִן הָאָרֶץ, וַהֲרֵי בֵּאַרְנוּ.</p>\n<p>כָּתוּב (שמות לב) וַיַּעֲשֵׂהוּ עֵגֶל מַסֵּכָה, וְכָתוּב וָאַשְׁלִכֵהוּ בָאֵשׁ וַיֵּצֵא הָעֵגֶל הַזֶּה. מַשְׁמָע שֶׁלֹּא עָשָׂה אוֹתוֹ. אִם כָּךְ, מַה זֶּה וַיַּעֲשֵׂהוּ? אֶלָּא וַדַּאי כְּמוֹ שֶׁבֵּאַרְנוּ, שֶׁאִלְמָלֵא אַהֲרֹן לֹא הִתְגַּבְּרָה רוּחַ הַטֻּמְאָה לְהִכָּלֵל בַּזָּהָב, אֲבָל כָּל תִּקּוּן שֶׁצָּרִיךְ, יֵשׁ לִבְנוֹת אוֹתוֹ (להתרוות).</p>\n<p>בֹּא וּרְאֵה, יֵשׁ מִי שֶׁעוֹשֶׂה כְשָׁפִים וּמַצְלִיחַ בְּיָדוֹ. וְיֵשׁ מִי שֶׁעוֹשֶׂה אוֹתָם בְּאוֹתוֹ גָּוֶן מַמָּשׁ וְלֹא מַצְלִיחַ בְּיָדוֹ, שֶׁהֲרֵי לַמַּעֲשִׂים הַלָּלוּ צָרִיךְ אָדָם מֻכְשָׁר.</p>\n<p>בֹּא וּרְאֵה מִבִּלְעָם, שֶׁהוּא הָיָה מֻכְשָׁר לְאוֹתָם הַכְּשָׁפִים שֶׁלּוֹ לְהַצְלָחָה בְּיָדוֹ, מִשּׁוּם שֶׁכָּתוּב (במדבר כד) וּנְאֻם הַגֶּבֶר שְׁתֻם הָעָיִן. שְׁתֻם הָעַיִן וּסְתוּם הָעַיִן הַכֹּל אֶחָד. שֶׁעַיִן אַחַת סְתוּמָה תָּמִיד, וּמַרְאֵה עֵינָיו לֹא הָיָה בְּדֶרֶךְ יְשָׁרָה. מוּם הָיָה לוֹ בְּעֵינוֹ. כָּתוּב (ויקרא טז) וְשִׁלַּח בְּיַד אִישׁ עִתִּי, מְזֻמָּן בַּכֹּל, הַמַּרְאֶה שֶׁל עֵינָיו שֶׁלֹּא כַּשּׁוּרָה. אֲבָל רוּחַ הַקֹּדֶשׁ, מִי שֶׁיִּשְׁתַּמֵּשׁ עִמָּהּ מַה כָּתוּב? (שם כא) כָּל אִישׁ אֲשֶׁר בּוֹ מוּם לֹא יִקְרָב אִישׁ עִוֵּר אוֹ פִסֵּחַ.</p>\n<p>וְכָאן הַכֹּל הֻתְקַן לְרוּחַ הַטֻּמְאָה לָתֵת לָהּ מָקוֹם לִשְׁלֹט. מָצָא מִדְבָּר שֶׁהוּא חָרֵב מֵהַכֹּל, כַּכָּתוּב (דברים ח) נָחָשׂ שָׂרָף וְעַקְרָב וְגוֹ', שֶׁמִּשָּׁם הוּא הַשִּׁלְטוֹן שֶׁלּוֹ. מָצָא זָהָב מַסְפִּיק כָּרָאוּי. מָצָא אַהֲרֹן כְּדֵי לְהִתְחַזֵּק בַּיָּמִין וּלְהִכָּלֵל בּוֹ. אָז הִשְׁלִים אֶת מְקוֹמוֹ כָּרָאוּי, וְיָצָא וְנִשְׁלַם הַמַּעֲשֶׂה.</p>\n<p>וּמִנַּיִן לָנוּ שֶׁרוּחַ טֻמְאָה הָיְתָה? שֶׁכָּתוּב (שמות לב) אָנָּא חָטָא הָעָם הַזֶּה חֲטָאָה גְדלָה. זוֹ רוּחַ הַטֻּמְאָה, נָחָשׁ הַקַּדְמוֹנִי, כְּפִי שֶׁאָמַרְנוּ בְּכַמָּה מְקוֹמוֹת. וּבִזְמַן שֶׁרָצָה אַהֲרֹן לְהִטָּהֵר, הִקְרִיב עֵגֶל מֵאוֹתוֹ הַצַּד לַעֲשׂוֹת בּוֹ דִּין. בָּרִאשׁוֹנָה עָשָׂה אוֹתוֹ לִשְׁלֹט, וְעַכְשָׁו שֶׁעָשָׂה בּוֹ דִּין לְהַכְנִיעוֹ, שֶׁהֲרֵי כְּשֶׁנַּעֲשָׂה דִין בַּצַּד הַזֶּה, נִכְנָעִים כָּל אוֹתָם שֶׁשּׁוֹלְטִים מִצִּדּוֹ.</p>"],[9522011898,"<p>בֹּא וּרְאֵה, בְּמִצְרַיִם, בְּאוֹתוֹ הַצַּד שֶׁלָּהֶם כָּתוּב (שם יב) אַל תֹּאכְלוּ מִמֶּנּוּ נָא וְגוֹ'. צְלִי אֵשׁ, כְּדֵי שֶׁיַּעֲלֶה רֵיחוֹ נוֹדֵף. רֹאשׁוֹ עַל כְּרָעָיו, לִשְׁבֹּר אוֹתוֹ וּלְהַכְנִיעוֹ, וְאָז כָּל אֵלּוּ שֶׁבָּאִים מִצִּדּוֹ לֹא שׁוֹלְטִים. כְּמוֹ כֵן (במדבר יט) פָּרָה אֲדֻמָּה תְּמִימָה וְגוֹ', כְּדֵי לְהַכְנִיעַ כָּל אוֹתָם הַצְּדָדִים הַטְּמֵאִים שֶׁלֹּא יִשְׁלְטוּ.</p>\n<p>אָמַר לוֹ רַבִּי אַבָּא, וַהֲרֵי הַפָּרָה הִיא קְדוֹשָׁה, הִיא טְהוֹרָה, וְלָמָּה? אָמַר לוֹ, כָּךְ הוּא, וַהֲרֵי פֵּרְשׁוּהָ, כְּלָל שֶׁל אַרְבַּע מַלְכֻיּוֹת הָיְתָה פָּרָה, כְּמוֹ שֶׁנֶּאֱמַר (הושעד) כִּי כְּפָרָה סֹרֵרָה סָרַר יִשְׂרָאֵל. אֲדֻמָּה - זוֹ מַלְכוּת בָּבֶל, שֶׁכָּתוּב (דניאלב) אַתָּה הוּא רֹאשׁ הַזָּהָב. תְּמִימָה - זוֹ מַלְכוּת מָדַי. אֲשֶׁר אֵין בָּהּ מוּם - זוֹ מַלְכוּת יָוָן (שהם קרובים לדרכי האמונה). אֲשֶׁר לֹא עָלָה עָלֶיהָ עֹל - זוֹ מַלְכוּת אֱדוֹם, שֶׁלֹּא עָלָה עָלֶיהָ עֹל. וְהַסּוֹד שֶׁל הַדָּבָר הַזֶּה, אַף עַל גַּב שֶׁכַּמָּה דְבָרִים נִתְּנוּ לִדְרשׁ בַּכְּתוּבִים - כֻּלָּם אֶחָד.</p>\n<p>הֲרֵי נֶאֱמַר, שֶׁכָּתוּב (איוב יד) מִי יִתֵּן טָהוֹר מִטָּמֵא לֹא אֶחָד. מִי יִתֵּן טָהוֹר מִטָּמֵא - סוֹד זֶה כָּךְ הוּא, שֶׁזֶּהוּ טָהוֹר שֶׁיּוֹצֵא מִטָּמֵא. שֶׁהֲרֵי בַּהַתְחָלָה טָמֵא, וְעַכְשָׁו שֶׁנַּעֲשֶׂה בּוֹ דִּין וְנִתָּן לִשְׂרֵפַת אֵשׁ בְּאֵשׁ בּוֹעֶרֶת וְנַעֲשֶׂה עָפָר, עַכְשָׁו הוּא טָהוֹר מִטָּמֵא, טָהוֹר שֶׁיָּצָא מִטָּמֵא.</p>\n<p>וּמִשּׁוּם כָּךְ, כָּל אֵלּוּ שֶׁמִּתְעַסְּקִים בָּהּ, כֻּלָּם נִטְמָאִים, שֶׁהֲרֵי כָּךְ הוּא וַדַּאי. וְכֵיוָן שֶׁנַּעֲשֵׂית אֵפֶר, אָז עַד שֶׁיִּתְכַּנֵּס וְיִסְתַּלֵּק מִשָּׁם, מְטַמֵּא אֶת כֻּלָּם, כְּמוֹ שֶׁנֶּאֱמַר וְכִבֶּס הָאֹסֵף וְגוֹ' וְטָמֵא. אֵפֶר, מָה הַטַּעַם? כְּמוֹ שֶׁנֶּאֱמַר (מלאכי ג) וְעַסּוֹתֶם רְשָׁעִים כִּי יִהְיוּ אֵפֶר תַּחַת כַּפּוֹת רַגְלֵיכֶם. וְכֵיוָן שֶׁנִּתָּן עַל אוֹתוֹ אֵפֶר מַיִם, אָז הוּא טָהוֹר מִטָּמֵא.</p>\n<p>וְסוֹד הַדָּבָר - שֶׁכָּתוּב (במדבר ח) מֵי חַטָּאת, כְּמוֹ שֶׁנֶּאֱמַר (בראשית ד) לַפֶּתַח חַטָּאת רֹבֵץ. וּמִשּׁוּם שֶׁהִיא פֶּתַח חַטָּאת רֹבֵץ וַדַּאי, בַּהַתְחָלָה כָּתוּב, וְהוֹצִיא אוֹתָהּ אֶל מִחוּץ לַמַּחֲנֶה. וּמִשּׁוּם כָּךְ נִתְּנָה לַסְּגָן וְלֹא לְכֹהֵן גָּדוֹל. וְזֶהוּ טָהוֹר מִטָּמֵא. בַּהַתְחָלָה טָמֵא, וְעַכְשָׁו טָהוֹר. וְכָל צַד רוּחַ הַטֻּמְאָה, כֵּיוָן שֶׁרוֹאֶה אֶת זֶה בּוֹרֵחַ, וְלֹא יוֹשֵׁב בְּאוֹתוֹ מָקוֹם.</p>\n<p>מֵי חַטָּאת וַדַּאי, מֵי נִדָּה, הַכֹּל טָמֵא. וְעַל כֵּן שׁוֹלֶטֶת רוּחַ הַקֹּדֶשׁ, וְרוּחַ הַטֻּמְאָה נִכְנַעַת, שֶׁלֹּא שׁוֹלֶטֶת כְּלָל. וְזֶהוּ דִּין שֶׁל רוּחַ הַטֻּמְאָה - מִחוּץ לַמַּחֲנֶה, מִשּׁוּם שֶׁהִיא רוּחַ טֻמְאָה, שֶׁכָּתוּב (דברים כג) וְהָיָה מַחֲנֶיךְ קָדוֹשׁ. בָּא רַבִּי אַבָּא וּנְשָׁקוֹ.</p>"],[9522011899,"<p>אָמַר רַבִּי שִׁמְעוֹן, אַף עַל גַּב שֶׁכָּל הַדְּבָרִים כְּפִי שֶׁאָמַרְנוּ, הַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן לוֹ שִׁלְטוֹן. וְרוּחַ הַטֻּמְאָה צָרִיךְ לְהַכְנִיעָהּ בְּכָל הַצְּדָדִים. בֹּא וְאֹמַר לְךְ סוֹד אֶחָד, וְשֶׁלֹּא נִתָּן לְגַלּוֹת פְּרָט לְאוֹתָם קְדוֹשִׁים עֶלְיוֹנִים.</p>\n<p>בֹּא וּרְאֵה, לַמָּקוֹם הַזֶּה שֶׁהוּא רוּחַ טֻמְאָה, נָתַן לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא שִׁלְטוֹן לִשְׁלֹט בָּעוֹלָם בְּכַמָּה צְדָדִים, וְיָכוֹל לְהַזִּיק, וְאֵין לוֹ (לנו) רְשׁוּת לִנְהֹג בּוֹ קָלוֹן, שֶׁצְּרִיכִים לְהִשָּׁמֵר מִמֶּנּוּ שֶׁלֹּא יְקַטְרֵג עָלֵינוּ בְּתוֹךְ הַקְּדֻשָּׁה שֶׁלָּנוּ. וְעַל כֵּן סוֹד אֶחָד יֵשׁ לָנוּ שֶׁצְּרִיכִים לָתֵת לוֹ מָקוֹם קָטָן בְּתוֹךְ הַקְּדֻשָּׁה שֶׁלָּנוּ, (שלא ימצא מקטרג בתוך הקדשה שלנו) שֶׁהֲרֵי מִתּוֹךְ הַקְּדֻשָּׁה יוֹצֵאת שְׁלִיטָתוֹ.</p>\n<p>שֶׁצְרִיכִים תּוֹךְ סוֹד הַתְּפִלִּין לְהַצְנִיעַ (סוד שער שבתפלין) שַׂעֲרָה אַחַת שֶׁל עֵגֶל שֶׁתֵּצֵא הַחוּצָה וְתֵרָאֶה, שֶׁהֲרֵי חוּט שֵׂעָר זֶה אֵינוֹ מְטַמֵּא, פְּרָט לְאִם מִתְחַבֶּרֶת שַׂעֲרָה זוֹ וְנַעֲשֵׂית כִּשְׂעוֹרָה, אֲבָל פָּחוֹת מִזֶּה לֹא מְטַמֵּא. וְאֶת אוֹתָהּ שַׂעֲרָה צָרִיךְ לְהַכְנִיס אוֹתָהּ בְּתוֹךְ הַקְּדֻשָּׁה הָעֶלְיוֹנָה שֶׁלָּנוּ וְלָתֵת לָהּ מָקוֹם, כְּדֵי שֶׁלֹּא תְקַטְרֵג עָלֵינוּ בַּקְּדֻשּׁוֹת שֶׁלָּנוּ.</p>\n<p>וְיֵצֵא מֵאוֹתָהּ שַׂעֲרָה הַחוּצָה שֶׁתֵּרָאֶה. שֶׁכְּשֶׁרוֹאֶה אֶת אוֹתוֹ אָדָם בִּקְדֻשָּׁה עֶלְיוֹנָה וְחֶלְקוֹ מִשְׁתַּתֵּף לְשָׁם, אָז לֹא יְקַטְרֵג לוֹ, וְלֹא יוּכַל לְהַזִּיק לוֹ לְמַעְלָה וּלְמַטָּה, שֶׁהֲרֵי נָתַן לוֹ מָקוֹם. וְאִם לֹא נוֹתְנִים לוֹ אוֹתוֹ חֵלֶק (מקום) בַּקְּדֻשָּׁה הַזּוֹ, יָכוֹל לְהַזִּיק לוֹ לְמַטָּה, וְעוֹלֶה לְקַטְרֵג עָלָיו לְמַעְלָה, וְאוֹמֵר: פְּלוֹנִי שֶׁעַכְשָׁו מְקַדֵּשׁ, כָּךְ וְכָךְ עָשָׂה בְּיוֹם פְּלוֹנִי וְכָךְ הֵם חֲטָאָיו. עַד שֶׁיַּגִּיעַ דִּין עַל אוֹתוֹ אָדָם וְיֵעָנֵשׁ עַל יָדוֹ. (וכן שעיר המשתלח).</p>\n<p>וּכְשֶׁהָיוּ יִשְׂרָאֵל עוֹשִׂים, שֶׁהָיוּ יוֹדְעִים סוֹד זֶה, כְּשֶׁמַּתְחִילִים לְהִתְקַדֵּשׁ בִּקְדֻשָּׁה עֶלְיוֹנָה בְּיוֹם הַכִּפּוּרִים, הָיוּ מִסְתַּכְּלִים מִיָּד לָתֵת אֶת חֶלְקוֹ לְאוֹתוֹ מָקוֹם וְלָתֵת לוֹ חֵלֶק בֵּינֵיהֶם, כְּדֵי שֶׁלֹּא יִמָּצֵא מְקַטְרֵג עֲלֵיהֶם וְלֹא יָבוֹאוּ לְהַזְכִּיר חֲטָאֵי יִשְׂרָאֵל. שֶׁכַּמָּה קְבוּצוֹת וְכַמָּה מַחֲנוֹת הֵם שֶׁמִּזְדַּמְּנִים לִטֹּל דָּבָר מִמֶּנּוּ כְּשֶׁבָּא לְקַטְרֵג. אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁיָּכוֹל לְהִשָּׁמֵר שֶׁלֹּא יִזָּכְרוּ חֲטָאָיו לְמַעְלָה, וְלֹא יַשְׁגִּיחוּ בוֹ לְרַע.</p>\n<p>בֵּין כָּךְ זָלְגוּ עֵינָיו שֶׁל רַבִּי אַבָּא. אָמַר לוֹ: אַבָּא אַבָּא, לֵךְ וְהַתֵּר קִשְׁרֵי צַעַרְךְ וְתַקְפִּיד בְּהַשָּׂגָתְךְ, שֶׁהֲרֵי סוֹדוֹת הַתּוֹרָה נִתְּנוּ לַצַּדִּיקִים, שֶׁכָּתוּב (תהלים כה) סוֹד ה' לִירֵאָיו.</p>\n<p>בֹּא וּרְאֵה, בַּיּוֹם שֶׁל רֹאשׁ הַשָּׁנָה הָעוֹלָם נִדּוֹן, וּבֵית הַדִּין הַקָּדוֹשׁ (הקדוש ברוך הוא) יוֹשֵׁב וְדָן אֶת כָּל הָעוֹלָם, וְאוֹתוֹ הַצַּד הָאַחֵר עוֹמֵד מִצַּד זֶה, וְכָל אוֹתָם שֶׁנִּדּוֹנוּ לַמָּוֶת הוּא מַשְׁגִּיחַ עֲלֵיהֶם, וְנִרְשָׁמִים לְפָנָיו. וּבְשָׁעָה שֶׁיִּשְׂרָאֵל מְעוֹרְרִים רַחֲמִים בְּאוֹתוֹ קוֹל שׁוֹפָר, אָז מִתְעַרְבֵּב לוֹ הַכֹּל, שֶׁלֹּא יוֹדֵעַ וְלֹא מַשְׁגִּיחַ בְּאוֹתָם שֶׁנִּדּוֹנוּ, עַד שֶׁאַחַר כָּךְ כָּל אֵלּוּ שֶׁלֹּא חָזְרוּ בִתְשׁוּבָה וְנִגְזַר עֲלֵיהֶם מָוֶת, וַדַּאי יוֹצְאִים עִם פְּתָקִים מִבֵּית הַמֶּלֶךְ וְנִמְסָרִים לוֹ. כֵּיוָן שֶׁנִּמְסְרוּ לוֹ, לֹא חוֹזְרִים הַפְּתָקִים, עַד שֶׁנַּעֲשָׂה הַדִּין.</p>\n<p>וְכָל יִשְׂרָאֵל צְרִיכִים לְהִשָּׁמֵר מִמֶּנּוּ, כָּל שֶׁכֵּן אָדָם לְבַדּוֹ. (וכל שכן וכל שכן) שֶׁהֲרֵי בְּסוֹד עֶלְיוֹן שֶׁלְּמַעְלָה צְרִיכִים לְהִשָּׁמֵר וְלָתֵת לוֹ בְּכָל חֹדֶשׁ וְחֹדֶשׁ, כְּשֶׁהַלְּבָנָה רוֹצָה לְהִתְחַדֵּשׁ, שָׂעִיר אֶחָד, כְּדֵי שֶׁלֹּא יְקַטְרֵג עַל הַהִתְחַדְּשׁוּת (השמחה) וְיִטֹּל אֶת חֶלְקוֹ כָּרָאוּי, וְהַלְּבָנָה הַקְּדוֹשָׁה תִּינַק בִּקְדֻשָּׁה לְהִתְחַדֵּשׁ כָּרָאוּי.</p>\n<p>וּכְשֶׁמִּתְחַדֶּשֶׁת בְּכָל חֹדֶשׁ וְחֹדֶשׁ, מִשּׁוּם כָּךְ נִקְרֵאת נַעַר, וַהֲרֵי בֵּאַרְנוּ. וְהָאַחֵר הַזֶּה, שֶׁהוּא תָּמִיד בְּטֻמְאָה וְלֹא יוֹצֵא מִמֶּנָּה, נִקְרָא מֶלֶךְ זָקֵן וּכְסִיל. וּמִשּׁוּם כָּךְ, יִשְׂרָאֵל הַקְּדוֹשִׁים, שֶׁהֵם עַם אֶחָד בְּיִחוּד קָדוֹשׁ, הַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן לָהֶם עֵצָה לְהִנָּצֵל מִן הַכֹּל. אַשְׁרֵיהֶם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, שֶׁכָּתוּב (ישעיה ס) וְעַמֵּךְ כֻּלָּם צַדִּיקִים לְעוֹלָם יִירְשׁוּ אָרֶץ נֵצֶר מַטָּעַי מַעֲשֵׂה יָדַי לְהִתְפָּאֵר.</p>"],[9522011900,"<p>וַיָּבִיאוּ אֶת הַמִּשְׁכָּן אֶל מֹשֶׁה וְגוֹ'. כָּתוּב (יחזקאלא) וּמִמַּעַל לָרָקִיעַ, זֶהוּ הָרָקִיעַ שֶׁעוֹמֵד עַל אַרְבַּע חַיּוֹת, שֶׁכְּשֶׁמִּתְעַלּוֹת בְּתוֹךְ אֲוִיר אֶחָד שֶׁמַּכֶּה בָהֶן, אֵינָן זוֹקְפוֹת רֹאשׁ לְהִסְתַּכֵּל לְמַעְלָה.</p>\n<p>מִשּׁוּם שֶׁאוֹתָהּ רוּחַ חַיָּה מַכָּה בְּכֻלָּן, וּבְאוֹתָהּ רוּחַ כֻּלָּן מִתְעַלּוֹת, שֶׁכָּתוּב וּבְהִנָּשֵׂא הַחַיּוֹת מֵעַל הָאָרֶץ יִנָּשְׂאוּ הָאוֹפַנִּים לְעֻמָּתָם. וְכָתוּב כִּי רוּחַ הַחַיָּה בָּאוֹפַנִּים.</p>\n<p>לָמָּה מִתְעַלּוֹת? אֶלָּא כְּשֶׁמַּכֶּה אוֹתוֹ אֲוִיר עֲלֵיהֶן, הוּא מַעֲלֶה אֶת אוֹתָן אַרְבַּע שֶׁתַּחַת הַחַיָּה הַזּוֹ, וְהֵן מַעֲלוֹת אוֹתָהּ לְמַעְלָה, עַד שֶׁמְּבִיאוֹת אוֹתָהּ לַזֹּהַר הָעֶליוֹן, וְהַיְנוּ סוֹד הַכָּתוּב, (תהלים מה) בְּתוּלוֹת אַחֲרֶיהָ רֵעוֹתֶיהָ מוּבָאוֹת לָךְ. מִשּׁוּם שֶׁאַרְבַּע הַלָּלוּ נִקְרָאוֹת כָּךְ, וְלֹא זָזוּ מֵהַחַיָּה הַזּוֹ, שֶׁהִיא כִּסֵּא, לְעוֹלָמִים. וּמַעֲלוֹת אוֹתָהּ מִמַּטָּה לְמַעְלָה לְהַתְקִין כִּסֵּא כְּלַפֵּי מַעְלָה. וְסוֹד זֶה - (בראשית ז) וַיִּשְׂאוּ אֶת הַתֵּבָה וַתָּרָם מֵעַל הָאָרֶץ. וּכְשֶׁמִּתְעַלָּה לְמַעְלָה וְאֵלֶּה מַעֲלוֹת אוֹתָהּ, אָז כָּתוּב, וַיָּבִיאוּ אֶת הַמִּשְׁכָּן אֶל מֹשֶׁה.</p>\n<p>וַיָּבִיאוּ אֶת הַמִּשְׁכָּן, כְּמוֹ שֶׁנֶּאֱמַר מוּבָאוֹת לָךְ, וְכָתוּב וַיִּשְׂאוּ אֶת הַתֵּבָה. אֶל מֹשֶׁה, כְּמוֹ שֶׁנֶּאֱמַר דְּמוּת כְּמַרְאֵה אָדָם עָלָיו מִלְמָעְלָה, וְהַיְנוּ סוֹד שֶׁל אָדָם. וּמִנַּיִן לָנוּ שֶׁנִּקְרָא אָדָם? שֶׁכָּתוּב (שם ו) לֹא יָדוֹן רוּחִי בָאָדָם לְעֹלָם בְּשַׁגַּם הוּא בָשָׂר, וְהַיְנוּ מֹשֶׁה. וּמִשּׁוּם כָּךְ עַל הַכִּסֵּא הַזֶּה דְּמוּת שֶׁל אָדָם עוֹמֶדֶת עָלָיו, וְהַיְנוּ מֹשֶׁה. וַיָּבִיאוּ אֶת הַמִּשְׁכָּן - אֵלּוּ אַרְבַּע הַחַיּוֹת כְּשֶׁעוֹלוֹת, כְּפִי שֶׁאָמַ רְנוּ.</p>\n<p>וַיָּבִיאוּ אֶת הַמִּשְׁכָּן - אֵלּוּ כָּל אֶבְרֵי הַגּוּף, שֶׁכֻּלָּם בִּתְשׁוּקָה קְדוֹשָׁה, (אמר רבי אבהו) כֻּלָּם אוֹחֲזִים בּוֹ לְהַדְבִּיק זָכָר וּנְקֵבָה כְּאֶחָד. וַיָּבִיאוּ אֶת הַמִּשְׁכָּן, לְהַכְנִיס כַּלָּה לַחֻפָּה. בָּרִאשׁוֹנָה הֵם צְרִיכִים לְהַעֲלוֹתָהּ וְלַהֲבִיאָהּ אֵלָיו, וְאַחַר כָּךְ הוּא יָבא אֵלֶיהָ תָּמִיד, וַהֲרֵי בֵּאַרְנוּ.</p>\n<p>וַיָּבִיאוּ אֶת הַמִּשְׁכָּן - סוֹד כָּל אוֹתָם הַקְּשָׁרִים, קִשְׁרֵי הַיִּחוּד, וּמְיַחֲדִים יִחוּד שֶׁל סוֹדוֹת הָאֱמוּנָה בְּכָל יוֹם, (אלו ארבע החיות) הֵם מַעֲלִים אוֹתָהּ לַכִּסֵּא הַזֶּה, עַד שֶׁמְּבִיאִים אוֹתָהּ לְמֹשֶׁה. וְכֵיוָן שֶׁמַּדְבִּיקִים אוֹתָהּ לְמֹשֶׁה, אָז הֵם הָיוּ שֶׁמַּרְוִיחִים בְּרָכוֹת מִמְּקוֹר הַחַיִּים עַל סוֹד זֶה, בַּקֶּשֶׁר שֶׁל הַיִּחוּד שֶׁל אוֹתָם הַקְּשָׁרִים. וְסוֹד זֶה, כְּשֶׁמְּקַשְּׁרִים הַיִּחוּד שֶׁל הַכֹּל כָּרָאוּי. וְסוֹד זֶה כָּתוּב, וַיַּרְא מֹשֶׁה אֶת כָּל הַמְּלָאכָה וְגוֹ', וַיְבָרֶךְ אֹתָם מֹשֶׁה. הִרְוִיחוּ בְרָכוֹת מִמְּקוֹם הַדַּרְגָּה שֶׁמֹּשֶׁה שָׁרוּי בָּהּ, וְזֶהוּ (שמות לו) הַחֲכָמִים הָעֹשִׂים אֵת כָּל מְלֶאכֶת הַקֹּדֶשׁ, מִשּׁוּם שֶׁהֵם יוֹדְעִים לְסַדֵּר אֶת עֲבוֹדַת הַקֹּדֶשׁ כָּרָאוּי.</p>\n<p>וְעַל כֵּן, כָּל מִי שֶׁמִּתְפַּלֵּל תְּפִלָּה (וקשור) וְקוֹשֵׁר יִחוּד, מִסְתַּכְּלִים בּוֹ אִם הִיא תְּפִלָּה וְקֶשֶׁר כָּרָאוּי. וְאִם אוֹתָהּ תְּפִלָּה וְאוֹתוֹ הַקֶּשֶׁר הֵם כָּרָאוּי, אֲזַי הוּא מִתְבָּרֵךְ בָּרִאשׁוֹנָה מֵהַמָּקוֹם שֶׁכָּל הַבְּרָכוֹת יוֹצְאוֹת. זֶהוּ שֶׁכָּתוּב, וְהִנֵּה עָשׂוּ אֹתָהּ וְגוֹ'. מִיָּד - וַיְבָרֶךְ אֹתָם מֹשֶׁה.</p>\n<p>וּמִשּׁוּם כָּךְ וַיָּבִיאוּ אֶת הַמִּשְׁכָּן אֶל מֹשֶׁה, שֶׁהוּא בַּעַל הַבַּיִת, לְהֵרָאוֹת בַּתִּקּוּן שֶׁל הַבַּיִת שֶׁלּוֹ, וְלוֹ צָרִיךְ לְהַרְאוֹת אֶת תִּקּוּנֶיה וְסוֹדוֹתֶיהָ, שֶׁלֹּא נִתְּנוּ לְאַחֵר לְהִתְבּוֹנֵן וְלִרְאוֹת אוֹתָהּ בְּאוֹתָם סְתָרִים וּבְאוֹתָם הַסּוֹדוֹת שֶׁלָּהּ, פְּרָט לְמֹשֶׁה לְבַדּוֹ.</p>\n<p>וְעַל כֵּן וַיָּבִיאוּ אֶת הַמִּשְׁכָּן אֶל מֹשֶׁה אֶת הָאֹהֶל וְאֶת כָּל כֵּלָיו. וּכְשֶׁהֵבִיאוּ אוֹתוֹ לְמֹשֶׁה, אֶת הַכֹּל הֵבִיאוּ לוֹ בְּאֵיבָרִים יְדוּעִים, לְתַקֵּן אֶת כָּל אֶחָד וְאֶחָד, אֵיבָר בְּאֵיבָר, לְהַכְנִיס זֶה בָּזֶה. וּכְשֶׁהָיוּ רוֹצִים לְתַקֵּן זֶה בָּזֶה וּלְהַכְנִיס זֶה בָּזֶה, לֹא הָיָה עוֹלֶה בִידֵיהֶם. כֵּיוָן שֶׁהֵבִיאוּ אוֹתוֹ לְמֹשֶׁה, מִיָּד הַכֹּל עָלָה בְיָדוֹ, וְכָל אֵיבָר וְאֵיבָר הָיָה עוֹלֶה וְנִכְנָס לִמְקוֹמוֹ. זֶהוּ שֶׁכָּתוּב, וַיָּקֶם מֹשֶׁה אֶת הַמִּשְׁכָּן, וְכָתוּב הוּקַם הַמִּשְׁכָּן, וַהֲרֵי בֵּאַרְנוּ.</p>\n<p>בֹּא וּרְאֵה, בְּאוֹתָהּ שָׁעָה כְּשֶׁהִתְחִיל מֹשֶׁה לְהָקִים אֶת הַמִּשְׁכָּן וְהִתְחִיל לְתַקֵּן אֶת תִּקּוּנָם שֶׁל הָאֵיבָרִים לְהַכְנִיסָם זֶה בָּזֶה, אָז רָפוּ כָּל הָאֵיבָרִים וְכָל הַתִּקּוּנִים שֶׁל הַצַּד הָאַחֵר הַטָּמֵא. כְּשֶׁהִתְחִיל לְהִתְחַזֵּק צַד הַקְּדֻשָּׁה הַזֶּה - מִתְרפֶּה הַצַּד הָאַחֵר הַטָּמֵא. זֶה מִתְחַזֵּק - וְזֶה מִתְרַפֶּה. וַהֲרֵי בֵּאַרְנוּ, שֶׁכָּל זְמַן שֶׁהִיא בְּחֹזֶק, מִתְרַפִּים כָּל אֶבְרֵי הַצַּד הָאַחֵר. זֶה מִתְמַלֵּא וְזֶה נֶחֱרָב. וְסוֹד זֶה - יְרוּשָׁלַים וְצוֹר הָרְשָׁעָה, כְּשֶׁזּוֹ מְלֵאָה - זוֹ חֲרֵבָה. וְעַל כֵּן, כְּשֶׁזֶּה מִתְחַזֵּק - זֶה נִרְפֶּה.</p>\n<p>וּמִשּׁוּם כָּךְ, וַיָּקֶם מֹשֶׁה אֶת הַמִּשְׁכָּן, לְהִתְחַזֵּק מִסּוֹד שֶׁל מַעְלָה, וְלֹא יִתְחַזֵּק מִסּוֹד שֶׁלְּמַטָּה. וְעַל כֵּן מֹשֶׁה, שֶׁהָיָה מִסּוֹד שֶׁל תּוֹךְ הָאַסְפַּקְלַרְיָה הַמְּאִירָה, צָרִיךְ הוּא לְהָקִים אֶת הַמִּשְׁכָּן לְהָאִיר מִמֶּנּוּ, וְלֹא מֵאַחֵר. (ועל זה) הַלְּבָנָה צְרִיכָה לְהָאִיר מִן הַשֶּׁמֶשׁ, וְלֹא מֵאַחֵר. בֹּא וּרְאֵה, כְּנֶסֶת יִשְׂרָאֵל צְרִיכָה לְהִתְעַלּוֹת לְמַעְלָה וּלְהִתְדַּבֵּק בְּתוֹךְ הַשֶּׁמֶשׁ.</p>"],[9522011901,"<p>פָּתַח וְאָמַר, (ויקרא ו) זאת תּוֹרַת הָעֹלָה הִיא הָעֹלָה. אָמַר רַבִּי שִׁמְעוֹן, כָּתוּב (תהלים לו) אָדָם וּבְהֵמָה תוֹשִׁיעַ ה'. עוֹלָה עֲלִיָּה וְקֶשֶׁר שֶׁל כְּנֶסֶת לְמַעְלָה, וְדִבּוּק שֶׁלָּהּ בְּתוֹךְ הָעוֹלָם הַבָּא, לִהְיוֹת הַכֹּל אֶחָד. נִקְרֵאת עוֹלָה קֹדֶשׁ קָדָשִׁים, וּמִשּׁוּם כָּךְ נִקְרָא עוֹלָה, שֶׁעוֹלָה וּמִתְעַטֶּרֶת לִהְיוֹת הַכֹּל אֶחָד בְּקֶשֶׁר אֶחָד בְּשִׂמְחָה.</p>\n<p>וּמִשּׁוּם שֶׁעוֹלָה לְמַעְלָה לְמַעְלָה, כָּתוּב זאת תּוֹרַת הָעֹלָה. סוֹד שֶׁל זָכָר וּנְקֵבָה כְּאֶחָד, תּוֹרָה שֶׁבִּכְתָב וְתוֹרָה שֶׁבְּעַל פֶּה. הָעֹלָה, שֶׁעוֹלָה לְתוֹךְ הָעוֹלָם הַבָּא לְהִתְקַשֵּׁר בְּתוֹכוֹ, שֶׁנִּקְרָא וַדַּאי קֹדֶשׁ הַקְּדָשִׁים, וְגַם הָעוֹלָה הִיא קֹדֶשׁ הַקְּדָשִׁים.</p>\n<p>וּמִשּׁוּם כָּךְ הַסִּדּוּר שֶׁל שְׁחִיטָתָהּ לְצַד צָפוֹן, שֶׁהוּא צַד שְׂמֹאל, שֶׁהֲרֵי תּוֹרָה שֶׁבְּעַל פֶּה לֹא עוֹלָה בַּחֲבִיבוּת, אֶלָּא רַק כְּשֶׁמִּתְעוֹרֵר צַד הַצָּפוֹן, שֶׁכָּתוּב (שיר ב) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי וִימִינוֹ תְּחַבְּגֵנִי. וְאָז הִיא עוֹלָה בַּחֲבִיבוּת וּמִתְעַטֶּרֶת בְּיָמִין, וּמִתְחַבֶּרֶת בָּאֶמְצַע, וְהַכֹּל מֵאִיר מֵהַסּוֹד שֶׁל קֹדֶשׁ הַקְּדָשִׁים, וְזֶה מִתּוֹךְ סוֹד הָאָדָם, בִּרְצוֹן הַכֹּהֵן וּבְשִׁירַת הַלְוִיִּם וּבִתְפִלַּת יִשְׂרָאֵל.</p>\n<p>וַהֲרֵי בֵּאַרְנוּ, שֶׁעוֹלָה קֹדֶשׁ הַקְּדָשִׁים בְּסוֹד הָרוּחַ הָעֶלְיוֹנָה, מִשּׁוּם שֶׁשָּׁלֹשׁ רוּחוֹת קְשׁוּרוֹת כְּאַחַת. רוּחַ תַּחְתּוֹנָה שֶׁנִּקְרֵאת רוּחַ הַקֹּדֶשׁ, רוּחַ שֶׁלְּפָנִים בָּאֶמְצַע שֶׁנִּקְרֵאת רוּחַ חָכְמָה וּבִינָה. וְכֵן נִקְרֵאת הָרוּחַ הַתַּחְתּוֹנָה. אֲבָל זוֹ נִקְרֵאת רוּחַ שֶׁיּוֹצֵאת מִתּוֹךְ הַשּׁוֹפָר, כְּלוּלָה בְּאֵשׁ וּבְמַיִם. הָרוּחַ הָעֶלְיוֹנָה, שֶׁהִיא נִסְתֶּרֶת בַּחֲשַׁאי, שֶׁבָּהּ עוֹמְדוֹת כָּל הָרוּחוֹת הַקְּדוֹשׁוֹת וְכָל הַפָּנִים מְאִירוֹת. וּמִשּׁוּם כָּךְ חוֹזֶרֶת הָעוֹלָה לְרוּחַ מַמָּשׁ.</p>\n<p>וְאַחַר כָּךְ, מִסּוֹד הַבְּהֵמָה מְקַבְּלִים וְנִזּוֹנִים, לִקְשֹׁר רוּחַ אַחֶרֶת שֶׁהִיא תּוֹךְ הַטֻּמְאָה, מֵאוֹתָם חֲלָבִים וְשֻׁמָּנִים, כְּמוֹ שֶׁנִּתְבָּאֵר. מִשּׁוּם כָּךְ עוֹלָה קֹדֶשׁ הַקְּדָשִׁים. שְׁאָר הַקָּרְבָּנוֹת, לַעֲשׂוֹת שָׁלוֹם בָּעוֹלָם, כֻּלָּם מִכַּמָּה צְדָדִים, וּבַעֲלֵי הַדִּינִים (להתעבר) לְהִתְעָרֵב (להתעטר) וְלִהְיוֹת נְאוֹרִים מִתּוֹךְ רָצוֹן לְהִתְבַּשֵּׂם נִקְרָאִים קָדָשִׁים קַלִּים, מִשּׁוּם שֶׁלֹּא מִתְעַטְּרִים לְמַעְלָה לְמַעְלָה בְּקֹדֶשׁ הַקְּדָשִׁים, וְלָכֵן הֵם קָדָשִׁים קַלִּים וּשְׁחִיטָתָם בְּכָל מָקוֹם, כְּמוֹ שֶׁאָמַרְנוּ. אֲבָל עוֹלָה, שֶׁהִיא סוֹד שֶׁל קֹדֶשׁ הַקְּדָשִׁים, אֵינָהּ כִּשְׁאָר הַקָּרְבָּנוֹת, שֶׁכָּל מַעֲשֶׂיהָ קֹדֶשׁ.</p>\n<p>בֹּא וּרְאֵה מַה כָּתוּב, (ויקראו) וְלָבַשׁ הַכֹּהֵן מִדּוֹ בַד. אֵלּוּ לְבוּשִׁים מְיֻחָדִים לִקְדֻשָּׁה. בַּד - יְחִידִי, מְיֻחָד לִקְדֻשָּׁה. וְכָתוּב (שם טז) בִּגְדֵי קֹדֶשׁ הֵם וְרָחַץ בַּמַּיִם אֶת בְּשָׂרוֹ וּלְבֵשָׁם. מָה הַטַּעַם (זה קדש) ? אֶלָּא סוֹד הַדָּבָר כְּמוֹ שֶׁאָמַרְנוּ, שֶׁהִיא קֹדֶשׁ הַקְּדָשִׁים, שֶׁכֻּלָּהּ עוֹלָה וּמִתְעַטֶּרֶת בְּקֹדֶשׁ הַקְּדָשִׁים בְּקֶשֶׁר אֶחָד, וְאַחַר כָּךְ מַפְנָה וּמַעֲבִירָה רוּחַ הַטֻּמְאָה שֶׁמְּטַמֵּאת הַכֹּל, שֶׁלֹּא תִשְׁלֹט וְלֹא תִתְקָרֵב לְתוֹךְ הַמִּקְדָּשׁ, וְתָעֳבַר מִכָּל צִדְדֵי הַקְּדֻשָּׁה, וְהַכֹּל יִשָּׁאֵר קֹדֶשׁ בִּקְדֻשָּׁה יְחִידָה.</p>\n<p>וְאָמַר רַבִּי שִׁמְעוֹן, הֲרֵי נֶאֱמַר, שֶׁכָּתוּב אָדָם וּבְהֵמָה תוֹשִׁיעַ ה'. וְכָךְ עוֹלֶה סוֹד הָאָדָם, מִצַּד שֶׁל אָדָם וַדַּאי. בְּהֵמָה - מִצַּד הַבְּהֵמָה. וּמִשּׁוּם כָּךְ כָּתוּב אָדָם כִּי יַקְרִיב מִכֶּם. אָדָם וַדַּאי, שֶׁזֶּה קָרְבָּנוֹ לְמַעְלָה, לִקְשֹׁר קֶשֶׁר בְּסוֹד שֶׁל אָדָם. וְאַחַר כָּךְ מִן הַבְּהֵמָה, וְהַכֹּל הוּא בְּסוֹד שֶׁל אָדָם וּבְהֵמָה. וְזֶהוּ הַסּוֹד שֶׁצָּרִיךְ לַקָּרְבָּן, אָדָם וּבְהֵמָה כְּמוֹ שֶׁאָמַרְנוּ. בֹּא וּרְאֵה, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, כָּךְ עָשָׂה - אָדָם וּבְהֵמָה.</p>\n<p>וְאִם תֹּאמַר, וַהֲרֵי כָּתוּב (בראשית א) וְעוֹף יְעוֹפֵף עַל הָאָרֶץ, שֶׁהֲרֵי מֵהֶם מַקְרִיבִים קָרְבָּנוֹת, וַאֲפִלּוּ עוֹלָה, כְּמוֹ שֶׁכָּתוּב (ויקרא א) וְאִם מִן הָעוֹף עֹלָה קָרְבָּנוֹ. בּא וּרְאֵה, מִכָּל אוֹתָם הָעוֹפוֹת לֹא מַקְרִיב אֶלָּא תוֹרִים וּבְנֵי יוֹנָה. (אלא סוד זה) מַה שֶּׁהֻכְשַׁר בָּזֶה - נִפְסַל בָּזֶה. זֶה יָמִין, וְזֶה שְׂמֹאל.</p>\n<p>אֲבָל הַסּוֹד הַזֶּה הֲרֵי בֵּאַרְנוּ, כָּתוּב וְעוֹף יְעוֹפֵף עַל הָאָרֶץ, שֶׁהוּא סוֹד הַמֶּרְכָּבָה, וּבָהֶם מִתְעַלָּה רוּחַ הַקֹּדֶשׁ לַעֲלוֹת לְמַעְלָה, שֶׁהֵם שְׁנַיִם, אֶחָד לְיָמִין וְאֶחָד לִשְׂמֹאל. עוֹף - לְיָמִין, וְזֶה מִיכָאֵל. יְעוֹפֵף - לִשְׂמֹאל, וְזֶה גַּבְרִיאֵל. זֶה לְיָמִין וְזֶה לִשְׂמֹאל. וּמִשּׁוּם כָּךְ מַקְרִיבִים שְׁנֵי אֵלֶּה, לְהַעֲלוֹת אֶת רוּחַ הַקֹּדֶשׁ, וְהַשְּׂמֹאל מְעַטֵּר וְזָן לְמַטָּה לְאוֹתוֹ צַד שְׂמֹאל, וְיָמִין לְיָמִין, וְנִקְשֶׁרֶת אִשָּׁה עִם בַּעְלָהּ לִהְיוֹת אֶחָד, וְהַכֹּל מִתְעַלֶּה וְנִקְשָׁר כְּאֶחָד לְמַעְלָה וּלְמַטָּה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מִתְעַלֶּה לְבַדּוֹ וּמִתְגַּבֵּר.</p>\n<p>וּבְסִפְרֵי הַקַּדְמוֹנִים, הֶעָנִי לֹא נוֹתֵן חֵלֶק לְהָזִין, אֶלָּא לְמַעְלָה לְהִתְקַשֵּׁר, אֲבָל הַכֹּל נִקְשָׁר לְמַעְלָה וּלְמַטָּה, וְכָל אֶחָד וְאֶחָד לְצִדּוֹ כָּרָאוּי, וַהֲרֵי בֵּאַרְנוּ.</p>\n<p>רַבִּי אֶלְעָזָר שָׁאַל אֶת רַבִּי שִׁמְעוֹן. אָמַר, הֲרֵי קֶשֶׁר שֶׁל הַכֹּל (העולה) נִקְשָׁר בְּקֹדֶשׁ הַקְּדָשִׁים לְהָאִיר. הַהִתְדַּבְּקוּת שֶׁל רְצוֹן הַכֹּהֵן וְהַלְוִיִּם וְיִשְׂרָאֵל לְמַעְלָה, עַד הֵיכָן הִיא עוֹלָה?</p>\n<p>אָמַר לוֹ, הֲרֵי בֵּאַרְנוּ, עַד אֵין סוֹף, שֶׁכָּל הַקֶּשֶׁר וְהַיִּחוּד וְהַשְּׁלֵמוּת, לְהַצְנִיעַ בְּאוֹתָהּ צְנִיעוּת שֶׁלֹּא מֻשֶּׂגֶת וְלֹא יְדוּעָה, שֶׁבָּהּ רְצוֹן כָּל הָרְצוֹנוֹת, הָאֵין סוֹף אֵינוֹ עוֹמֵד לְהִוָּדַע וְלֹא לַעֲשׂוֹת סוֹף וְלֹא לַעֲשׂוֹת רֹאשׁ, כְּמוֹ שֶׁהָאַיִ\"ן הָרִאשׁוֹן מוֹצִיא רֹאשׁ וָסוֹף. מִי הָרֹאשׁ? זוֹ הַנְּקֻדָּה הָעֶלְיוֹנָה שֶׁהִיא רֹאשׁ כָּל הַנִּסְתָּר שֶׁעוֹמֶדֶת בְּתוֹךְ הַמַּחֲשָׁבָה. וְעוֹשָׂה סוֹף, שֶׁנִּקְרָא (קהלת יב) סוֹף דָּבָר. אֲבָל לְשָׁם, אֵין סוֹף.</p>\n<p>אֵין רְצוֹנוֹת, אֵין אוֹרוֹת, אֵין מְאוֹרוֹת בְּאוֹתוֹ הָאֵין סוֹף. כָּל הַמְּאוֹרוֹת וְהָאוֹרוֹת הַלָּלוּ תְּלוּיִים לְהִתְקַיֵּם בָּהֶם וְלֹא נִתָּן לְהַשָּׂגָה מִי שֶׁיָּדוּעַ וְלֹא יָדוּעַ, אֵינוֹ אֶלָּא רְצוֹן עֶלְיוֹן, נִסְתַּר כָּל הַנִּסְתָּרִים, אַיִן.</p>\n<p>וּכְשֶׁהַנְּקֻדָּה הָעֶלְיוֹנָה וְהָעוֹלָם הַבָּא מִתְעַלִּים, אֵין יוֹדְעִים פְּרָט לְרֵיחַ, כְּמִי שֶׁמֵּרִיחַ אֶת הָרֵיחַ וּמִתְבַּשֵּׂם, וְאֵין זוֹ נַחַת הַנִּיחֹחַ, שֶׁהֲרֵי כָּתוּב (ויקרא כו) וְלֹא אָרִיחַ בְּרֵיחַ נִיחֹחֲכֶם, שֶׁהֲרֵי רֵיחַ נִיחֹחַ, הָרֵיחַ שֶׁל הָרָצוֹן שֶׁכָּל הָרְצוֹנוֹת הַלָּלוּ שֶׁל תְּפִלָּה, וְהָרָצוֹן שֶׁל שִׁירָה, וּרְצוֹנוֹ שֶׁל הַכֹּהֵן, שֶׁכֻּלָּם סוֹד שֶׁל אָדָם, וְאָז כֻּלָּם נַעֲשִׂים רָצוֹן אֶחָד. וְאוֹתוֹ נִקְרָא נִיחֹחַ, רָצוֹן, כְּתַרְגּוּמוֹ. וְאָז הַכֹּל נִקְשָׁר וּמֵאִיר כְּאֶחָד כָּרָאוּי, כְּמוֹ שֶׁנִּתְבָּאֵר.</p>\n<p>וְעַל זֶה נִתָּן הַצַּד הָאַחֵר הַזֶּה בְּיַד הַכֹּהֵן, שֶׁכָּתוּב (שם ו) צַו אֶת אַהֲרֹן וְאֶת בָּנָיו לֵאמֹר. הַסּוֹד כָּאן, שֶׁהֲרֵי בֵּאַרְנוּ אֵין צַו אֶלָּא עֲבוֹדָה זָרָה, וְכָאן נִתְּנָה לוֹ לִשְׂרֹף הַמַּחֲשָׁבָה הָרָעָה וּלְהַעֲבִירָהּ מִתּוֹךְ הַקֹּדֶשׁ בָּרָצוֹן הַזֶּה שֶׁעוֹלֶה לְמַעְלָה, בֶּעָשָׁן הַזֶּה וּבַחֲלָבִים שֶׁנִּשְׂרָפִים, כְּדֵי שֶׁיָּעָבְרוּ מִן הַקֹּדֶשׁ. וְהַצַּו הַזֶּה עוֹמֵד בִּרְשׁוּתָם לְהַפְרִידָהּ מִן הַקֹּדֶשׁ מִתּוֹךְ הַקָּרְבָּן הַזֶּה. וְאִם תֹּאמַר, (במדבר כח) צַו אֶת בְּנֵי יִשְׂרָאֵל - גַּם כָּךְ, שֶׁהֲרֵי בִּרְשׁוּתָם עוֹמֵד (להפריד אותה מן הקדשה) כָּל זְמַן שֶׁעוֹשִׂים רְצוֹנוֹ שֶׁל רִבּוֹנָם שֶׁלֹּא יוּכַל לִשְׁלֹט עֲלֵיהֶם.</p>\n<p>וְהַמִּקְרָא הַזֶּה כֻּלּוֹ בָּא לְהַרְאוֹת אֶת סוֹד הַדָּבָר, לְעַטֵּר אֶת אוֹתָהּ רוּחַ הַקֹּדֶשׁ לְמַעְלָה לְמַעְלָה, וּלְהַפְרִיד אֶת רוּחַ הַטֻּמְאָה הַזּוֹ לְהוֹרִידָהּ לְמַטָּה לְמַטָּה, וְזֶה בְּרָצוֹן וּבִתְפִלָּה כְּמוֹ שֶׁאָמַרְנוּ, וְזֶה בְּמַעֲשֶׂה, הַכֹּל כָּרָאוּי לוֹ.</p>\n<p>וּפָסוּק זֶה מוֹכִיחַ עֲלֵיהֶם, שֶׁכָּתוּב צַו אֶת אַהֲרֹן וְאֶת בָּנָיו לֵאמֹר. צַו - זוֹ עֲבוֹדָה זָרָה, רוּחַ הַטֻּמְאָה. לֵאמֹר - זוֹ אִשָּׁה, שֶׁנִּקְרֵאת יִרְאַת ה'. כָּתוּב כָּאן לֵאמֹר, וְכָתוּב שָׁם (ירמיה ג) לֵאמֹר הֵן יְשַׁלַּח אִישׁ אֶת אִשְׁתּוֹ, וַהֲרֵי פֵּרְשׁוּהָ. וּמִשּׁוּם כָּךְ הַכֹּל נֶאֱמַר, וְהַכֹּהֵן עוֹמֵד לְהַתְקִין אֶת הַכֹּל, בְּסוֹד שֶׁל אָדָם וּבְהֵמָה. אַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא לְאוֹתָם הַיּוֹדְעִים אֶת דַּרְכֵי הַתּוֹרָה וְהוֹלְכִים בָּהּ בְּדֶרֶךְ אֱמֶת, עֲלֵיהֶם כָּתוּב (ישעיה לח) ה' עֲלֵיהֶם יִחְיוּ. מַה זֶּה עֲלֵיהֶם? אֵלּוּ דַּרְכֵי הַתּוֹרָה. יִחְיוּ - יִתְקַיְּמוּ בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>\n<p>בֹּא וּרְאֵה, כָּתוּב זֹאת תּוֹרַת הָעֹלָה. אָמַר רַבִּי חִיָּיא, פָּסוּק זֶה בֵּאַרְנוּ אוֹתוֹ בַּגָּוֶן הַזֶּה: זאת תּוֹרַת - זוֹ כְּנֶסֶת יִשְׂרָאֵל. הָעֹלָה - שֶׁהִיא עוֹלָה וּמִתְעַטֶּרֶת לְמַעְלָה לְמַעְלָה לְהִתְקַשֵּׁר כָּרָאוּי עַד הַמָּקוֹם שֶׁנִּקְרָא קֹדֶשׁ הַקְּדָשִׁים.</p>\n<p>דָּבָר אַחֵר, זאת תּוֹרַת - זוֹ כְּנֶסֶת יִשְׂרָאֵל. הָעֹלָה - זוֹ מַחֲשָׁבָה רָעָה שֶׁעוֹלָה עַל רְצוֹן הָאָדָם לְהַסְטוֹתוֹ מִדֶּרֶךְ הָאֱמֶת. הִיא הָעֹלָה - הִיא הִיא שֶׁעוֹלָה וּמַסְטָה אֶת הָאָדָם, וְצָרִיךְ לְשָׂרְפָהּ בָּאֵשׁ כְּדֵי לֹא לָתֵת לָהּ מָקוֹם (להסטות) לִרְבּוֹת.</p>\n<p>וּמִשּׁוּם כָּךְ, עַל מוֹקְדָה עַל הַמִּזְבֵּחַ כָּל הַלַּיְלָה. מִי הוּא הַלַּיְלָה? זוֹ כְּנֶסֶת יִשְׂרָאֵל, (שהיא זאת משום) שֶׁבָּאָה לְטַהֵר אֶת הָאָדָם מֵאוֹתוֹ הָרָצוֹן. עַל מוֹקְדָה, מִשּׁוּם שֶׁנְּהַר דִּינוּר הוּא מָקוֹם לִשְׂרֹף כָּל אוֹתָם שֶׁלֹּא עוֹמְדִים עַל מְקוֹמָם, שֶׁהֲרֵי מַכְנִיסִים אוֹתָם בְּאוֹתָהּ אֵשׁ שֶׁדּוֹלֶקֶת, וּמַעֲבִירִים אֶת שִׁלְטוֹנָם מִן הָעוֹלָם. וּבִכְדֵי שֶׁלֹּא יִשְׁלֹט, צָרִיךְ עַל מוֹקְדָה עַל הַמִּזְבֵּחַ כָּל הַלַּיְלָה, וְנִכְנַעַת וְלֹא שׁוֹלֶטֶת.</p>\n<p>וְעַל כָּךְ, כְּשֶׁזֶּה נִכְנָע, עוֹלָה כְּנֶסֶת יִשְׂרָאֵל, שֶׁהִיא רוּחַ הַקֹּדֶשׁ, שֶׁעוֹלָה וּמִתְעַטּרֶת לְמַעְלָה, שֶׁהֲרֵי עֲלִיָּתָהּ כְּשֶׁנִּכְנָע הַכֹּחַ הָאַחֵר הַזֶּה וְנִפְרָד מִמֶּנָּה. וּמִשּׁוּם כָּךְ צְרִיכִים בְּסוֹד הַקָּרְבָּן לְהַפְרִיד אֶת הַצַּד הַזֶּה מֵרוּחַ הַקֹּדֶשׁ וְלָתֵת לוֹ חֵלֶק, כְּדֵי שֶׁרוּחַ הַקֹּדֶשׁ תִּתְעַלֶּה לְמַעְלָה.</p>\n<p>וּבֹא רְאֵה, בִּזְמַן שֶׁנִּבְנָה בֵּית הַמִּקְדָּשׁ וְנַעֲשָׂה, נִכְנַע הַצַּד הָאַחֵר וְהִסְתַּלֵּק מֵהָעוֹלָם. וּכְשֶׁהִסְתַּלֵּק מֵהָעוֹלָם וְהוּקַם הַמִּשְׁכָּן עַל יְדֵי מֹשֶׁה, אָז הוּקַם לְמַעְלָה וּלְמַטָּה. זֶהוּ שֶׁכָּתוּב וַיָּקֶם מֹשֶׁה אֶת הַמִּשְׁכָּן. מַה זֶּה וַיָּקֶם? אֶלָּא שֶׁהֵקִים אוֹתָהּ לְהִתְעַלּוֹת לְמַעְלָה לְמַעְלָה. וּלְכָךְ וַיָּקֶם מֹשֶׁה. מַה שֶּׁהָיָה נָמוּךְ - הוּא הֱקִימוֹ, כְּמִי שֶׁמֵּקִים אֶת מִי שֶׁנָּפַל. כְּמוֹ כֵן לֶעָתִיד לָבא כָּתוּב, (עמוס ט) אָקִים אֶת סֻכַּת דָּוִיד הַנּוֹפֶלֶת.</p>\n<p>כָּתוּב (שם ה) נָפְלָה לֹא תוֹסִיף קוּם בְּתוּלַת יִשְׂרָאֵל. מַה זֶּה לֹא תוֹסִיף קוּם? (משמע שבזמן אחר קמה) אֶלָּא שֶׁבִּזְמַן אַחֵר הִיא קָמָה. הִיא קָמָה מֵעַצְמָהּ, וְלֹא הֱקִימָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא. שֶׁהֲרֵי בְּגָלוּת מִצְרַיִם הַקָּדוֹשׁ בָּרוּךְ הוּא הֵקִים אוֹתָהּ וְעָשָׂה כַּמָּה נִסִּים כְּדֵי לַהֲקִימָהּ, וּבְגָלוּת בָּבֶל הוּא לֹא הֵקִים אוֹתָהּ, מִשּׁוּם שֶׁלֹּא עָשָׂה לָהֶם נִסִּים, שֶׁגָּרַם הַחֵטְא, אֶלָּא הִיא קָמָה. וְעָלוּ בְּנֵי הַגּוֹלָה כְּאוֹתָם שֶׁלֹּא הָיָה לָהֶם פְּדוּת, וְלֹא הָיְתָה תְשׁוּקָתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא עֲלֵיהֶם, מִשּׁוּם שֶׁגָּרַם אוֹתוֹ הַחֵטְא, שֶׁהֵם נָשִׁים נָכְרִיּוֹת.</p>\n<p>וְלָכֵן לֹא הֵקִים הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת כְּנֶסֶת יִשְׂרָאֵל וְלֹא עָשָׂה לָהֶם נִסִּים וּגְבוּרוֹת בְּאוֹתוֹ זְמַן כָּרָאוּי. אֲבָל לֶעָתִיד לָבא, לֹא תוֹסִיף קוּם כָּתוּב. לֹא תוֹסִיף קוּם מֵעַצְמָהּ, אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא יָקִים אוֹתָהּ, שֶׁכָּתוּב אָקִים אֶת סֻכַּת דָּוִיד הַנּוֹפֶלֶת. וְכָתוּב (ירמיה ל) וְאֵת דָּוִד מַלְכָּם אֲשֶׁר אָקִים לָהֶם. וּמִשּׁוּם כָּךְ כָּתוּב כָּאן, וַיָּקֶם מֹשֶׁה אֶת הַמִּשְׁכָּן. וַיָּקֶם מֹשֶׁה וְגוֹ'.</p>\n<p>בֹּא וּרְאֵה, כְּשֶׁמֹּשֶׁה הֵקִים אֶת הַמִּשְׁכָּן, הוּקַם מִשְׁכָּן אַחֵר עִמּוֹ, וְהַמִּשְׁכָּן הָעֶלְיוֹן הֵקִים (כבד) וְסָעַד הַכֹּל, מִשּׁוּם שֶׁהַמִּשְׁכָּן הָעֶלְיוֹן נִסְתָּר וְגָנוּז הוּא לְמַעְלָה לְמַעְלָה, וּמִשְׁכָּן אַחֵר הוּקַם עַל הַמִּשְׁכָּן לְמַטָּה וְעוֹמֵד עָלָיו (עמו. והמשכן העליון ההוא שגסתר וגנוז למעלה למעלה, הקים וסעד הכל. והמשכן האחר ההוא הוקם על ידי המשכן שלמטה עומד עליו) בְּכֹחוֹ שֶׁל אוֹתוֹ מִשְׁכָּן הָעֶלְיוֹן עַל הַכֹּל. וּכְמוֹ שֶׁהוּקַם הַמִּשְׁכָּן שֶׁלְּמַטָּה עַל יַד מֹשֶׁה, אַף כָּךְ לְמַעְלָה עַל יְדֵי אוֹתוֹ שֶׁבָּנָה מֹשֶׁה (דרגה של משה). מִנַּיִן לָנוּ? שֶׁכָּתוּב וַיָּקֶם מֹשֶׁה אֶת הַמִּשְׁכָּן. אֶת דַּוְקָא, לְהַרְאוֹת שֶׁשְּׁנֵי הַמִּשְׁכָּנוֹת נִתְקְנוּ (הוקמו) בְּסוֹד שֶׁל מֹשֶׁה.</p>\n<p>אָמַר רַבִּי יוֹסֵי, וְכִי וַיָּקֶם מֹשֶׁה? הֲרֵי הַכֹּל טֶרֶם הִתְתַּקֵּן, וְקִימָה אֵינָהּ אֶלָּא כְּשֶׁהַכֹּל נִשְׁלָם וְנִכְנָס אֵיבָר בְּאֵיבָרוֹ. מַה זֶּה וַיָּקֶם? אָמַר רַבִּי יִצְחָק, בִּשְׁלֹשָׁה צְדָדִים הֵקִים מֹשֶׁה אֶת הַמִּשְׁכָּן. מַה כָּתוּב? וַיָּקֶם מֹשֶׁה אֶת הַמִּשְׁכָּן, וַיִּתֵּן אֶת אֲדָנָיו, וַיָּשֶׂם אֶת קְרָשָׁיו. בִּשְׁלֹשֶׁת הַצְּדָדִים הַלָּלוּ הֵקִים מֹשֶׁה אֶת הַמִּשְׁכָּן, וּבִשְׁלֹשֶׁת הַצְּדָדִים הַלָּלוּ הִתְעַלָּה הַמִּשְׁכָּן וְנִכְנַע הַצַּד הָאַחֵר. וּלְכָךְ, כְּשֶׁמֹּשֶׁה הֵקִים אֶת הַצַּד הַזֶּה, נִכְנַע הַצַּד הָאַחֵר. מִשּׁוּם כָּךְ מֹשֶׁה הֱקִימוֹ וְלֹא אַחֵר.</p>\n<p>בֹּא וּרְאֵה, כָּתוּב וַיִּתֵּן אֶת אֲדָנָיו. בְּאוֹתָהּ שָׁעָה הִזְדַּעֲזַע סָמָאֵ\"ל מִמְּקוֹמוֹ, וְאַרְבָּעִים מֶרְכָּבוֹת שֶׁעִמּוֹ, וּבָרַח אַרְבַּע מֵאוֹת פַּרְסָאוֹת לְתוֹךְ סֵתֶר נֶקֶב הֶעָפָר. הִכְנִיס מֹשֶׁה אוֹתָם הָעַמּוּדִים, וְהִתְחַזֵּק הַצַּד הַזֶּה, וְאָז אוֹתָם הָעַמּוּדִים שֶׁל הַצַּד הָאַחֵר נָפְלוּ וְהִתְרַפּוּ.</p>\n<p>פָּתַח וְאָמַר, בַּיּוֹם הַהוּא אָקִים אֶת סֻכַּת דָּוִיד הַנּוֹפֶלֶת וְגוֹ'. מַה זֶּה בַּיּוֹם הַהוּא? בַּיּוֹם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יַעֲשֶׂה דִין בָּעוֹלָם וְיִפְקֹד עַל רִשְׁעֵי הָעוֹלָם כְּמַעֲשֵׂיהֶם. שֶׁהֲרֵי אֵין קִימָה לִכְנֶסֶת יִשְׂרָאֵל מִן הֶעָפָר בְּעוֹד שֶׁאוֹתָם רִשְׁעֵי יִשְׂרָאֵל יַעַמְדוּ בָעוֹלָם. מַה כָּתוּב לְמַעְלָה? (עמוס ט) בַּחֶרֶב יָמוּתוּ כֹּל חַטָּאֵי עַמִּי הָאֹמְרִים לֹא תַגִּישׁ וְתַקְדִּים בַּעֲדֵינוּ הָרָעָה. מַה כָּתוּב אַחֲרָיו? בַּיּוֹם הַהוּא אָקִים אֶת סֻכַּת דָּוִיד הַנּוֹפֶלֶת וְגוֹ'.</p>\n<p>בַּפָּסוּק הַזֶּה יֵשׁ לְהִתְבּוֹנֵן. אֶת פִּרְצֵיהֶן?! אֶת פִּרְצָהּ הָיָה צָרִיךְ לִהְיוֹת. וַהֲרִסתָיו?! וַהֲרִיסוֹתֶיהָ הָיָה צָרִיךְ לִהְיוֹת. אֶלָּא וְגָדַרְתִּי אֶת פִּרְצֵיהֶן, מִמִּי? מֵאוֹתָם הָרְשָׁעִים, שֶׁכָּתוּב בַּחֶרֶב יָמוּתוּ כֹּל חַטָּאֵי עַמִּי, שֶׁהֲרֵי אָז יַעֲשׂוּ פְרָצוֹת בְּיִשְׂרָאֵל. וְעַל זֶה, וְגָדַרְתִּי אֶת פִּרְצֵיהֶן וַהֲרִסֹתָיו אָקִים. וַהֲרִסֹתָיו, שֶׁל מִי? הֲרִיסוֹתָיו שֶׁל סֻכַּת דָּוִד. (ממי, ' מדוד) מִשּׁוּם שֶׁכְּשֶׁמִּתְחַזֶּקֶת מַלְכוּת הָרְשָׁעָה בָּעוֹלָם, אָז נִרְפֵּית הַמַּלְכוּת הַקְּדוֹשָׁה הַזּוֹ, וְסֻכַּת דָּוִד סוֹתֶרֶת אֶת הַבִּנְיָן שֶׁלָּהּ, וְעַל כֵּן וַהֲרִסֹתָיו אָקִים.</p>\n<p>שֶׁהֲרֵי שָׁנִינוּ, כָּל זְמַן שֶׁזֶּה מִתְחַזֵּק - זֶה מִתְרַפֶּה. זֶה מָלֵא - וְזֶה חָרֵב. וּמִפְּנֵי כֵן עַד הַיּוֹם הַהוּא מַלְכוּת הַרִשְׁעָה מִתְחַזֶּקֶת. בַּיּוֹם הַהוּא יִתְחַזֵּק וְיָקִים אוֹתָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא לְזוֹ הַמַּלְכוּת הַקְּדוֹשָׁה. וְעַל זֶה וַהֲרִסֹתָיו אָקִים, וּבְנִיתִיהָ כִּימֵי עוֹלָם, מַה זֶּה וּבְנִיתִיהָ כִּימֵי עוֹלָם? הַיְנוּ שֶׁכָּתוּב (ישעיה ל) וְהָיָה אוֹר הַלְּבָנָה כְּאוֹר הַחַמָּה וְגוֹ'.</p>\n<p>וַיָּקֶם מֹשֶׁה אֶת הַמִּשְׁכָּן. בַּמָּה הֵקִים אוֹתוֹ? שֶׁכָּתוּב וַיִּתֵּן אֶת אֲדָנָיו, וְנָתַן אוֹתָם הָעַמּוּדִים שֶׁתַּחְתָּיו לְהָקִים עֲלֵיהֶם וּלְסוֹבֵב בָּהֶם אוֹתָם הַצִּירִים שֶׁל פְּתָחִים, מִשּׁוּם שֶׁאוֹתָם הָעַמּוּדִים שֶׁתַּחְתֵּיהֶם הֵם הָעֲמִידָה לְהַקִּיפָם. לָמָּה וַיִּתֵּן? חִזֵּק וְהִתְקִין אוֹתָם בְּכֹחוֹ. בְּאוֹתָהּ שָׁעָה הוּסְרוּ אוֹתָם הַתּוֹמְכִים הָאֲחֵרִים שֶׁל הַצַּד הָאַחֵר.</p>\n<p>בֹּא וּרְאֵה, כָּתוּב (תהלים קלז) זְכֹר ה' לִבְנֵי אֱדוֹם אֶת יוֹם יְרוּשָׁלם הָאֹמְרִים עָרוּ עָרוּ עַד הַיְסוֹד בָּהּ. וְעַל כֵּן עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לִבְנוֹת אֶת יְסוֹדוֹתֶיהָ שֶׁל יְרוּשָׁלַיִם מִיסוֹדוֹת אֲחֵרִים שֶׁיִּשְׁלְטוּ עַל הַכֹּל, וּמִי הֵם? סַפִּירִים, שֶׁכָּתוּב (ישעיהנד) וִיסַדְתִּיךְ בַּסַּפִּירִים, שֶׁאֵלּוּ הֵם הַיְסוֹדוֹת וְהַתּוֹמְכִים הַחֲזָקִים וְהָעֶלְיוֹנִים שֶׁאֵין בָּהֶם חֻלְשָׁה בָּרִאשׁוֹנָה. מָה הַטַּעַם? כִּי הָאֲבָנִים הָרִאשׁוֹנוֹת מֵאוֹתָם הַיְסוֹדוֹת, יָכְלוּ שְׁאָר הָעַמִּים לִשְׁלֹט עֲלֵיהֶם. מָה הַטַּעַם? מִשּׁוּם שֶׁאֵין בָּהֶם אוֹר עֶלְיוֹן כָּרָאוּי. אֲבָל אֵלֶּה יִהְיוּ מְאִירִים מִתּוֹךְ הָאוֹר הָעֶלְיוֹן וּמְשֻׁקָּעוֹת בְּתוֹךְ הַתְּהוֹמוֹת, שֶׁלֹּא יְכוֹלִים לִשְׁלֹט עֲלֵיהֶם. וְאֵלּוּ הֵם הַסַּפִּירִים שֶׁיָּאִירוּ לְמַעְלָה וּלְמַטָּה, (ואם תאמר) מִשּׁוּם שֶׁבְּאוֹתוֹ זְמַן יִתּוֹסֵף אוֹר עֶלְיוֹן לְמַעְלָה וּלְמַטָּה.</p>\n<p>וְאִם תֹּאמַר שֶׁאוֹתָם יְסוֹדוֹת רִאשׁוֹנִים יִתְבַּטְּלוּ, הֲרֵי כָּתוּב (שם) הִנֵּה אָנֹכִי מַרְבִּיץ בַּפּוּךְ אֲבָנַיִךְ. מַרְבִּיץ לְתַקֵּן הַשָּׁבוּר. מַה זֶּה בַּפּוּךְ? כְּמוֹ שֶׁנֶּאֱמַר, (מלכים ב ט) וַתָּשֶׂם בַּפּוּךְ עֵינֶיהָ. יֵשׁ אֲבָנִים שֶׁנִּקְרָאוֹת פּוּךְ. מָה הַטַּעַם שֶׁל זֶה? אָמַר רַבִּי אֶלְעָזָר, סוֹד הוּא, וְסוֹד זֶה נִתָּן לָדַעַת לְקוֹצְרֵי הַשָּׂדֶה.</p>\n<p>בֹּא וּרְאֵה, אוֹתָן אֲבָנִים שֶׁל יְסוֹדוֹת צִיּוֹן וִירוּשָׁלַיִם, חַס וְשָׁלוֹםן שֶׁשָּׁלְטוּ עֲלֵיהֶם שְׁאָר הָעַמִּים, וְלֹא שָׂרְפוּ אוֹתָם וְלֹא נִשְׂרְפוּ, אֶלָּא כֻּלָּם נִגְנְזוּ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא גָּנַז אוֹתָם, וְכָל אוֹתָם יְסוֹדוֹת הַבַּיִת הַקָּדוֹשׁ נִגְנְזוּ, וְלֹא אָבַד מֵהֶם אֲפִלּוּ אֶחָד. וּכְשֶׁיַּחֲזֹר הַקָּדוֹשׁ בָּרוּךְ הוּא וְיָקִים אֶת יְרוּשָׁלַיִם עַל מְקוֹמָהּ, אוֹתָם הַיְסוֹדוֹת שֶׁל הָאֲבָנִים הָרִאשׁוֹנוֹת יַחְזְרוּ לִמְקוֹמָם וְלֹא תִשְׁלֹט בָּהֶם עַיִן אַחֶרֶת (רעה), פְּרָט לִזְמַן שֶׁאָדָם יִכְחֹל אֶת עֵינוֹ בְּאוֹתוֹ הַפּוּךְ וִימַלֵּא אֶת עֵינָיו מִמֶּנּוּ, וְאָז יִרְאֶה אֶת כָּל הָאֲבָנִים וְהַיְסוֹדוֹת שֶׁל יְרוּשָׁלַיִם מְתֻקָּנִים עַל מְקוֹמָם, שֶׁלֹּא שָׁלְטוּ בָהֶם שְׁאָר הָעַמִּים. וְכָל אוֹתָן אֲבָנִים יְקָרוֹת הָאֲחֵרוֹת, וְכָל אוֹתָם בִּנְיְנֵי הָאֲבָנִים, כֻּלָּם עוֹמְדִים עַל מְקוֹמָם.</p>\n<p>וְאָז, (ישעיה נב) כִּי עַיִן בְּעַיִן יִרְאוּ בְּשׁוּב ה' צִיּוֹן. מַה זֶּה בְּשׁוּב ה'? אֶלָּא כְּשֶׁשָּׁלְטוּ עָלֶיהָ שְׁאָר הָעַמִּים, הַקָּדוֹשׁ בָּרוּךְ הוּא הֶעֱלָה אוֹתָהּ לְמַעְלָה, וּבְאוֹתוֹ הַזְּמַן הוּא יַחֲזִירֶנָּה לִמְקוֹמָהּ, שֶׁכָּתוּב (שם) בְּשׁוּב ה' צִיּוֹן. בְּשׁוּב ה' וַדַּאי.</p>\n<p>וּבֹא רְאֵה, כָּל מַה שֶּׁנִּסְתָּר מִן הָעַיִן וְלֹא נִתְּנָה לָעַיִן רְשׁוּת לִשְׁלֹט בּוֹ, לֹא תוּכַל לִשְׁלֹט בּוֹ הָעַיִן, פְּרָט לַאֲשֶׁר בִּכְחִילַת הָעַיִן בִּדְבָרִים יְדוּעִים. וּמִשּׁוּם כָּךְ, הִנֵּה אָנֹכִי מַרְבִּיץ בַּפּוּךְ אֲבָנַיִךְ. וּבא רְאֵה, כָּל הָאֲבָנִים הַלָּלוּ יַעַמְדוּ בִמְקוֹמָן וְיִהְיוּ יְסוֹדוֹת כְּבָרִאשׁוֹנָה, וִיסוֹד שֶׁל סַפִּירִים (אחרים) יַעַמְדוּ בְמָקוֹם אַחֵר סָבִיב, לָרֹחַב וְלָאֹרֶךְ. זֶהוּ שֶׁכָּתוּב וִיסַדְתִּיךְ בַּסַּפִּירִים.</p>\n<p>בִּזְמַן שֶׁיָּקִים הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת בֵּיתוֹ, בְּאוֹתוֹ זְמַן מַה כָּתוּב? (שםכה) בִּלַּע הַמָּוֶת לָנֶצַח. בִּלַּע, כְּמוֹ שֶׁאָמַרְנוּ (איכה ב) בִּלַּע ה' וְלֹא חָמַל. אוֹתָהּ כּוֹס שֶׁשָּׁתָה זֶה, יִשְׁתֶּה זֶה.</p>\n<p>וְאִם תֹּאמַר, אוֹתוֹ בִּלַּע הוּא לִזְמַן יָדוּעַ וְקָצוּב כְּמוֹ יִשְׂרָאֵל - לֹא כָּךְ! כָּתוּב לָנֶצַח. מַה זֶּה לָנֶצַח? לְדוֹרֵי דוֹרוֹת, וְלֹא כְּמוֹ יִשְׂרָאֵל, וְלֹא כְּאוֹתוֹ הַזְּמַן שֶׁהֵקִים מֹשֶׁה אֶת הַמִּשְׁכָּן. אֶלָּא לָנֶצַח - לְעוֹלָמִים.</p>\n<p>וְאָז הַקָּדוֹשׁ בָּרוּךְ הוּא יָקִים אֶת כְּנֶסֶת יִשְׂרָאֵל, וְהוּא יָקִים עַמּוּדִים וְסִפִּים, וְכָל אוֹתָן תִּקְרוֹת הַבַּיִת בְּתִקּוּנָיו (בחזק), לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים. וְכָתוּב (ישעיה נד) הַרְחִיבִי מְקוֹם אָהֳלֵךְ וְגוֹ', מִשּׁוּם שֶׁיִּבָּלַע הַצַּד הָאַחֵר וְלֹא יָקוּם לְעוֹלָמִים. וְאָז, (שם כה) וְחֶרְפַּת עַמּוֹ יָסִיר מֵעַל כָּל הָאָרֶץ כִּי ה' דִּבֵּר.</p>\n<p>וַיָּקֶם מֹשֶׁה אֶת הַמִּשְׁכָּן, בְּאוֹתוֹ הַזְּמַן שֶׁהָעַמּוּדִים הַלָּלוּ הוּקְמוּ וְנִתְּנוּ בִמְקוֹמָם, בְּאוֹתוֹ הַזְּמַן הִתְרַפּוּ וְהָעָבְרוּ מִמְּקוֹמָם הָעַמּוּדִים בִּמְקוֹמוֹ שֶׁל הַצַּד הָאַחֵר, וְעַל זֶה וַיִּתֵּן אֶת אֲדָנָיו.</p>\n<p>מַה זֶּה וַיִּתֵּן? אֶלָּא לָמַדְנוּ שֶׁרָאָה מֹשֶׁה לְפָנָיו אֶת סָמָאֵ\"ל הָרָשָׁע, שֶׁהָיָה הוֹלֵךְ אֵלָיו לְקַטְרֵג לוֹ, וְאָז הֶחֱזִיק בּוֹ מֹשֶׁה וְקָשַׁר אוֹתוֹ לְפָנָיו, וְהֵקִים אֶת הַמִּשְׁכָּן וְנָתַן אֶת הַתּוֹמְכִים שֶׁלּוֹ, שֶׁכָּתוּב וַיִּתֵּן אֶת אֲדָנָיו. וַיִּתֵּן - בְּכֹחַ, שֶׁלֹּא יוּכַל אָדָם אַחֵר לִשְׁלֹט עָלָיו וְלָתֵת תּוֹמְכִים בִּמְקוֹמָם כְּמֹשֶׁה, שֶׁהֲרֵי בְּחֹזֶק רַב הֵקִים אוֹתוֹ מֹשֶׁה.</p>\n<p>בְּאוֹתוֹ יוֹם שֶׁהוּקַם הַמִּשְׁכָּן, כְּשֶׁהִתְחִיל מֹשֶׁה לְהָקִים אוֹתוֹ, זֶה הָיָה בְּאֶחָד בְּנִיסָן, וּבְאוֹתוֹ זְמַן הַחֹזֶק שֶׁל הַצַּד הָאַחֵר הָיָה בָּעוֹלָם, שֶׁהֲרֵי בִּימֵי נִיסָן, רֹאשׁ הַשּׁוֹר הוּא בָּאֵבוּס (עלהלגג), שָׁנִינוּ. וּבְנִיסָן הִתְחִיל מֹשֶׁה וְרָאָה אֶת סָמָאֵ\"ל הוֹלֵךְ סְבִיבוֹ לְעַרְבֵּב אוֹתוֹ, וְהִתְגַּבֵּר עָלָיו מֹשֶׁה, וְאָז - וַיִּתֵּן אֶת אֲדָנָיו. הוּא הִתְחִיל וְנָתַן לְמַטָּה, וְהִתְחִיל מִי שֶׁהִתְחִיל וְנָתַן לְמַעְלָה זֶה כְּנֶגֶד זֶה.</p>\n<p>בַּיּוֹם שֶׁהוּקַם הַמִּשְׁכָּן הַזֶּה לְמַטָּה, הוּקַם מִשְׁכָּן אַחֵר קָדוֹשׁ לְמַעְלָה, וְהַמִּשְׁכָּן הָעֶלְיוֹן הַטָּמִיר וְהַגָּנוּז הוֹצִיא אוֹרוֹת לְכָל צַד וְהוּאֲרוּ הָעוֹלָמוֹת.</p>\n<p>רַבִּי יוֹסֵי שָׁאַל אֶת רַבִּי שִׁמְעוֹן. אָמַר לוֹ, שְׁלֹשָׁה מִשְׁכָּנוֹת רָאִינוּ בַמִּקְרָא, שֶׁכָתוּב (במדבר ט) וּבְיוֹם הָקִים אֶת הַמִּשְׁכָּן, כִּסָּה הֶעָנָן אֶת הַמִּשְׁכָּן לְאֹהֶל הָעֵדֻת, וּבָעֶרֶב יִהְיֶה עַל הַמִּשְׁכָּן כְּמַרְאֵה אֵשׁ עַד בּקֶר. הֲרֵי שְׁלֹשָׁה מִשְׁכָּנוֹת כָּאן. וְלָמָּה מִשְׁכָּן וְלֹא בַּיִת, שֶׁהֲרֵי בַּיִת צָרִיךְ וְלֹא מִשְׁכָּן?</p>\n<p>פָּתַח וְאָמַר, (ישעיה סו) כֹּה אָמַר ה' הַשָּׁמַיִם כִּסְאִי וְגוֹ'. בּא וּרְאֵה, הַקָּדוֹשׁ בָּרוּךְ הוּא הִתְרַצָּה בְיִשְׂרָאֵל לְנַחֲלָתוֹ וְגוֹרָלוֹ וְקֵרַב אוֹתָם אֵלָיו, וַהֲרֵי בֵּאַרְנוּ שֶׁעָשָׂה מֵהֶם דְּרָגוֹת יְדוּעוֹת בָּעוֹלָם הַזֶּה כְּמוֹ שֶׁלְּמַעְלָה, לְתַקֵּן אֶת כָּל הָעוֹלָמוֹת כְּאֶחָד - מַעְלָה וּמַטָּה, שֶׁכָּתוּב הַשָּׁמַיִם כִּסְאִי וְהָאָרֶץ הֲדם רַגְלָי. לְתַקֵּן מַעְלָה וּמַטָּה וְלִהְיוֹת אֶחָד.</p>\n<p>בֹּא וּרְאֵה, הַשָּׁמַיִם כִּסְאִי - זֶה הָרָקִיעַ שֶׁיַּעֲקֹב שָׁרוּי בּוֹ, שֶׁהוּא דְּיוֹקָן עֶלְיוֹן לַכִּסֵּא (כסא עליון לדיוקן) הָעֶלְיוֹן הַקָּדוֹשׁ. וְהָאָרֶץ הֲדם רַגְלָי - זֶהוּ הָרָקִיעַ שֶׁדָּוִד הַמֶּלֶךְ שָׁרוּי בּוֹ לֵהָנוֹת מִזִּיו הָאַסְפַּקְלַרְיָה הַמְּאִירָה. וּמִשּׁוּם שֶׁרוֹצֶה לְהִתְפַּשֵּׁט יוֹתֵר לְמַטָּה, אָמַר הֲדֹם רַגְלָי. אֵי זֶה בַיִת אֲשֶׁר תִּבְנוּ לִי - זֶה בִּנְיַן בֵּית הַמִּקְדָּשׁ. וְאֵי זֶה מְקוֹם מְנוּחָתִי - זֶה בֵּית קֹדֶשׁ הַקְּדָשִׁים שֶׁלְּמַטָּה.</p>\n<p>אֲבָל בֹּא וּרְאֵה, כָּל זְמַן שֶׁהָלְכוּ יִשְׂרָאֵל בַּמִּדְבָּר, הָיָה לָהֶם מִשְׁכָּן, עַד שֶׁבָּאוּ לְשִׁילֹה וְהָיָה שָׁם. וְזֶהוּ סוֹד לְהַמְשִׁיךְ זֶה בָּזֶה וּלְהַכְנִיס זֶה בָּזֶה, לְהִתְקַשֵּׁר זֶה בָּזֶה כְּדֵי לְהָאִיר, אֲבָל לֹא לִמְנוּחָה. שֶׁזּוֹ לֹא לִמְנוּחָה, רַק כְּשֶׁיִּבָּנֶה בֵּית הַמִּקְדָּשׁ בִּימֵי שְׁלֹמֹה הַמֶּלֶךְ, שֶׁהֲרֵי אָז הִיא מְנוּחָה לְמַעְלָה וּלְמַטָּה, מִשּׁוּם שֶׁשָּׁם חֹזֶק הַמְּנוּחָה, וְלֹא לִנְסֹעַ מִמָּקוֹם לְמָקוֹם.</p>\n<p>וּמִשּׁוּם כָּךְ יֵשׁ מִשְׁכָּן וְיֵשׁ בַּיִת. מִשְׁכָּן - כְּמוֹ שֶׁנֶּאֱמַר (ויקרא כו) וְנָתַתִּי מִשְׁכָּנִי בְּתוֹכֲכֶם וְלֹא תִגְעַל נַפְשִׁי אֶתְכֶם. מַה זֶּה מִשְׁכָּנִי? מִשְׁכְּנוֹתָיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁיִּהְיוּ אֵצֶל יִשְׂרָאֵל. מָה הַטַּעַם? מִשּׁוּם שֶׁכָּתוּב וְלֹא תִגְעַל נַפְשִׁי אֶתְכֶם.</p>\n<p>מַה בֵּין זֶה לָזֶה? אֶלָּא מִשְׁכָּן, כְּמוֹ מֶלֶךְ שֶׁהוֹלֵךְ לַאֲהוּבוֹ, וְלֹא מֵבִיא אֶת כָּל גְּדוּדָיו עִמּוֹ. כְּדֵי לֹא לְהַטְרִיחַ עָלָיו, הוּא בָּא אֵלָיו בִּמְעַט חֲיָלוֹת. בַּיִת - שֶׁאֶת כָּל חֵילוֹתָיו וְאוּכְלוּסָיו, אֶת כֻּלָּם מֵבִיא עִמּוֹ לָדוּר בְּאוֹתוֹ הַבַּיִת. וְזֶהוּ בֵּין מִשְׁכָּן וּבֵין בַּיִת. בֵּית הַמִּקְדָּשׁ הוּא דִּיּוּר שֶׁל מְנוּחָה לְעוֹלָמִים בְּכָל אוֹתָן הַמֶּרְכָּבוֹת, וּבְכָל אוֹתָם הַדְּיוֹקְנָאוֹת, וּבְכָל אוֹתָם הַמַּעֲשִׂים כְּמוֹ שֶׁלְּמַעְלָה, לְשַׁבֵּר (לחבר) אֶת הַמַּעֲשִׂים שֶׁלְּמַטָּה כְּמוֹ שֶׁלְּמַעְלָה. מִשְׁכָּן, בְּקֹטֶן הַדְּמֻיּוֹת, בְּמַעֲשִׂים קְטַנִּים, לִנְסֹעַ מִמָּקוֹם לְמָקוֹם, וְהַכֹּל בַּסּוֹד שֶׁלְּמַעְלָה.</p>\n<p>בֹּא וּרְאֵה, כְּשֶׁצִּוָּה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת מֹשֶׁה עַל הַמִּשְׁכָּן, לֹא יָכוֹל הָיָה לַעֲמֹד בּוֹ, עַד שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הֶרְאָה לוֹ אֶת הַכֹּל בִּדְמוּתוֹ כָּל דָּבָר וְדָבָר. בַּמָּה הוּא הֶרְאָה לוֹ? בְּאֵשׁ לְבָנָה וּבְאֵשׁ שְׁחֹרָה וּבְאֵשׁ אֲדֻמָּה וּבְאֵשׁ יְרֻקָּה. מַה כָּתוּב? (שמות כה) וּרְאֵה וַעֲשֵׂה בְּתַבְנִיתָם כְּכָל אֲשֶׁר מָרְאֶה בָּהָר. עִם כָּל זֶה הִתְקַשָּׁה מֹשֶׁה.</p>\n<p>בֹּא וּרְאֵה, אַף עַל גַּב שֶׁהֶרְאָה לוֹ עַיִן בְּעַיִן, לֹא רָצָה מֹשֶׁה לַעֲשׂוֹת. וְאִם תֹּאמַר שֶׁהוּא לֹא יָדַע לַעֲשׂוֹת אוֹ שֶׁחָכְמָה לֹא הָיְתָה עִמּוֹ - בֹּא וּרְאֵה, בְּצַלְאֵל וְאָהֳלִיאָב וְכָל שְׁאָר אוֹתָם הָאֲחֵרִים, אַף עַל גַּב שֶׁלֹּא רָאוּ כְּמוֹ מֹשֶׁה, מַה כָּתוּב? וַיַּרְא מֹשֶׁה אֶת כָּל הַמְּלָאכָה וְהִנֵּה עָשׂוּ אֹתָהּ וְגוֹ'. אִם הֵם שֶׁלֹּא רָאוּ עָשׂוּ כָּךְ - מֹשֶׁה שֶׁרָאָה עַל אַחַת כַּמָּה וְכַמָּה. אֶלָּא מֹשֶׁה, אַף עַל גַּב שֶׁהִסְתַּלֵּק מֵהַמִּשְׁכָּן מֵהָעֲבוֹדָה שֶׁלּוֹ, הַכֹּל הָיָה בְּיָדוֹ וְעַל יָדוֹ, וְהוּא נִקְרָא עַל שְׁמוֹ, וְעַל זֶה כָּתוּב וּרְאֵה וַעֲשֵׂה.</p>\n<p>דָּבָר אַחֵר - מֹשֶׁה הִסְתַּלֵּק מִזֶּה וְנָתַן מְקוֹמוֹ לְאַחֵר, עַד שֶׁאָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, רְאֵה קָרָאתִי בְשֵׁם בְּצַלְאֵל, וְאִתּוֹ אָהֳלִיאָב. וְכָתוּב, וְעָשָׂה בְצַלְאֵל וְאָהֳלִיאָב וְכֹל אִישׁ חֲכַם לֵב. אִם הַכָּבוֹד הַזֶּה הָיָה שֶׁל מֹשֶׁה, שֶׁהוּא יַעֲשֶׂה אוֹתוֹ - יִתְקַיֵּם בּוֹ תָּמִיד (יותר תמיד).</p>\n<p>וְעִם כָּל זֶה, כֵּיוָן שֶׁהוּא צִוָּה וּבְמִצְוָתוֹ נַעֲשָׂה, הוּא עָשָׂה הַכֹּל. וְעוֹד, כָּל מַעֲשֶׂה אֵינוֹ עוֹמֵד אֶלָּא בְּסִיּוּם הַמַּעֲשֶׂה, וְעַל כֵּן וַיָּקֶם מֹשֶׁה אֶת הַמִּשְׁכָּן. רָצוּ לַהֲקִימוֹ כָּל אוֹתָם חַכְמֵי הַלֵּב, וְלֹא הָיָה מִתְקַיֵּם, מִשּׁוּם כְּבוֹדוֹ שֶׁל מֹשֶׁה, עַד שֶׁבָּא מֹשֶׁה וֶהֱקִימוֹ. וַהֲרֵי פֵּרְשׁוּהָ.</p>"],[9522011902,"<p>וַיָּקֶם מֹשֶׁה אֶת הַמִּשְׁכָּן. רַבִּי יְהוּדָה פָּתַח, (מיכה ז) אַל תִּשְׂמְחִי אֹיַבְתִּי לִי כִּי נָפַלְתִּי קָמְתִּי וְגוֹ'. מִי אֹיַבְתִּי לִי? זוֹ מַלְכוּת הָרְשָׁעָה שֶׁשּׂוֹנֵאת אֶת מַלְכוּת הַקְּדוֹשָׁה. וּפָסוּק זֶה אָמְרָה אוֹתוֹ כְּנֶסֶת יִשְׂרָאֵל, אַל תִּשְׂמְחִי אֹיַבְתִּי לִי כִּי נָפַלְתִּי קָמְתִּי, מַה שֶּׁאֵין לְךְ כָּךְ (לה כך) בְּמַלְכוּת אַחֶרֶת, שֶׁכֵּיוָן שֶׁתִּפֹּל, לֹא תָקוּם לְעוֹלָמִים. אֲבָל כְּנֶסֶת יִשְׂרָאֵל - אַף עַל גַּב שֶׁנָּפְלָה, תָּקוּם וְקָמָה שְׁאָר הַפְּעָמִים, שֶׁכָּתוּב כִּי נָפַלְתִּי קָמְתִּי.</p>\n<p>שֶׁהֲרֵי כַּמָּה פְעָמִים נָפְלָה כְּנֶסֶת יִשְׂרָאֵל בַּגָּלוּת וְיָשְׁבָה בֵּין אוֹתָם שְׁאָר בַּעֲלֵי יְרִיבוֹת, וּשְׁאָר הָעַמִּים קָמוּ עַל יִשְׂרָאֵל לְהַשְׁמִידָם מֵהָעוֹלָם, כְּמוֹ שֶׁנֶּאֱמַר (תהלים פג) עַל עַמְּךְ יַעֲרִימוּ סוֹד, וְכָתוּב כִּי נוֹעֲצוּ לֵב יַחְדָּו וְגוֹ', אָמְרוּ לְכוּ וְנַכְחִידֵם מִגּוֹי. וְעִם כָּל זֶה - אַף עַל גַּב שֶׁשְּׁאָר הָעַמִּים קָמוּ עֲלֵיהֶם, הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא הִנִּיחַ אוֹתָם בִּידֵיהֶם, וְאִם נָפְלוּ - קָמוּ, שֶׁכָּתוּב כִּי נָפַלְתִּי קָמְתִּי. שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא מֵקִים אוֹתָהּ תָּמִיד.</p>\n<p>וַעָתִידָה כְּנֶסֶת יִשְׂרָאֵל לוֹמַר בְּאוֹתוֹ זְמַן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יָקִים אוֹתָהּ מִן הֶעָפָר שֶׁל הַגָּלוּת וְתִסְתַּלֵּק מִמֶּנָּה: אַל תִּשְׂמְחִי אֹיַבְתִּי לִי כִּי נָפַלְתִּי קָמְתִּי. כִּי נָפַלְתִּי - בַּגָּלוּת וְהִשְׁתַּעְבְּדוּ בָנַי. קָמְתִּי - בַּזְּמַן הַזֶּה. וּמִשּׁוּם כָּךְ, בְּאוֹתוֹ זְמַן שֶׁמֹּשֶׁה הוֹצִיא אֶת יִשְׂרָאֵל, כְּשֶׁעָשָׂה לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹתָם הַנִּסִּים וְהַגְּבוּרוֹת שֶׁעָשָׂה לָהֶם, אָז - וַיָּקֶם מֹשֶׁה אֶת הַמִּשְׁכָּן, שֶׁהֲרֵי עַל יַד מֹשֶׁה הוּקַם בְּכָל זְמַן.</p>"],[9522011903,"<p>רַבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (יחזקאל א) בְּלֶכְתָּם יֵלֵכוּ וְגוֹ'. בְּלֶכְתָּם יֵלֵכוּ וּבְעָמְדָם יַעֲמֹדוּ. בְּפָסוּק זֶה יֵשׁ לְהִתְבּוֹנֵן בּוֹ. בְּלֶכְתָּם יֵלֵכוּ, וְכִי לֹא יָדַעְנוּ שֶׁבְּלֶכְתָּם יֵלֵכוּ וּבְעָמְדָם יַעֲמֹדוּ? אֶלָּא בְּלֶכְתָּם שֶׁל מִי? בְּלֶכְתָּם שֶׁל הַחַיּוֹת, כְּשֶׁהֵן הוֹלְכוֹת, אוֹתָם הָאוֹפַנִּים יֵלֵכוּ, כְּמוֹ שֶׁנֶּאֱמַר וּבְלֶכֶת הַחַיּוֹת יֵלְכוּ הָאוֹפַנִּים אֶצְלָם. וְעַל כָּךְ בְּלֶכְתָּם יֵלֵכוּ וּבְעָמְדָם יַעֲמֹדוּ, מִשּׁוּם שֶׁכָּל מַסְעֵיהֶם שֶׁל אוֹתָם הָאוֹפַנִּים אֵינָם אֶלָּא בַּמַּסָּעוֹת שֶׁל הַחַיּוֹת, וְקִיּוּמָם אֵינָם עוֹמְדִים בִּמְקוֹמָם, אֶלָּא הַכֹּל תָּלוּי בַּחַיּוֹת. וְכֵן כָּתוּב, וּבְהִנָּשֵׂא הַחַיּוֹת מֵעַל הָאָרֶץ יִנָּשְׂאוּ הָאוֹפַנִּים לְעֻמָּתָם, מִשּׁוּם שֶׁחַיּוֹת וְאוֹפַנִּים הוֹלְכִים כְּאֶחָד.</p>\n<p>וּבֹא רְאֵה, עֶשְׂרִים וְאַרְבָּעָה מַשְׁקוֹפִים שֶׁל הַמִּשְׁמָרוֹת הָעֶלְיוֹנוֹת עוֹמְדִים בְּתוֹךְ מַשְׁקוֹף אֶחָד שֶׁבְּצַד מִזְרָח. לַפֶּתַח הַזֶּה שׁוֹמְרִים עֶשְׂרִים וְאַרְבַּע מִשְׁמָרוֹת טְמוּנוֹת בְּתוֹךְ תֹּקֶף הַשַּׁלְהֶבֶת שֶׁעוֹטֶרֶת וְסוֹבֶבֶת לְתוֹךְ אוֹתוֹ הַמַּשִׁקוֹף מֵאוֹתוֹ צַד מִזְרָח.</p>\n<p>וְאַרְבָּעָֹה וְעֶשְׂרִים עַמּוּדִים תַּחְתֵּיהֶם, וְעַל אֵלּוּ הָעַמּוּדִים עוֹמְדִים עֶשְׂרִים וְאַרְבָּעָה עַמּוּדִים, וְאֵלּוּ הֵם שֶׁתָּמִיד עוֹמְדִים, וְלֹא פוֹרְחִים לְתוֹךְ הָאֲוִיר כְּמוֹ אוֹתָם הָאֲחֵרִים, וְאֵלּוּ הֵם שֶׁנִּקְרָאִים עוֹמְדִים, כְּמוֹ שֶׁנֶּאֱמַר (זכריהג) וְנָתַתִּי לְךְ מַהְלְכִים בֵּין הָעֹמְדִים הָאֵלֶּה. וְאֵלּוּ הָעַמּוּדִים עוֹמְדִים עַל אוֹתָם תּוֹמְכִים, בָּהֶם סוֹבְבִים לְהִתְקַיֵּם בִּמְקוֹמָם.</p>\n<p>כְּשֶׁהָעַמּוּדִים הַלָּלוּ עוֹמְדִים עַל מְקוֹמָם, כָּל הַשַּׁלִּיטִים שֶׁעוֹמְדִים עֲלֵיהֶם מְעוֹפְפִים וְטָסִים בְּכָל הָעוֹלָם, וְהָעֵינַיִם מַשְׁגִּיחוֹת, וְהֵם מַקְשִׁיבִים לַקּוֹלוֹת וּמַעֲלִים דְּבָרִים לְמַעְלָה, כְּמוֹ שֶׁנֶּאֱמַר כִּי עוֹף הַשָּׁמַיִם יוֹלִיךְ אֶת הַקּוֹל. וּמִשּׁוּם כָּךְ אוֹתָם הַתּוֹמְכִים עוֹמְדִים בְּקִיּוּם תְּמִידִי.</p>\n<p>בֹּא וּרְאֵה, בְּלֶכְתָּם יֵלֵכוּ, כְּפִי שֶׁאָמַרְנוּ. וּבְהִנָּשְׂאָם מֵעַל הָאָרֶץ יִנָּשְׂאוּ הָאוֹפַנִּים לְעֻמָּתָם. שֶׁהֲרֵי כְּמוֹ שֶׁהַחַיּוֹת הָאֵלֶּה נוֹסְעִים וְעוֹלִים, כָּךְ גַּם הֵם. מָה הַטַּעַם? מִשּׁוּם כִּי רוּחַ הַחַיָּה בָּאוֹפַנִּים. רוּחַ הַחַיָּה - רוּחַ הַקֹּדֶשׁ שֶׁנּוֹשֶׁבֶת וּמַכָּה בְּכָל הָאוֹפַנִּים לָלֶכֶת. נִמְצָא שֶׁכָּל מִי שֶׁהוּא בְּדַרְגָּה עֶלְיוֹנָה, הוּא נוֹשֵׂא אֶת מִי שֶׁנּוֹשֵׂא אוֹתוֹ. בּא וּרְאֵה, שֶׁהָאָרוֹן הָיָה נוֹשֵׂא אֶת מִי שֶׁנּוֹשֵׂא אוֹתוֹ. אַף כָּאן הַחַיּוֹת נוֹשְׂאוֹת אֶת הָאוֹפַנִּים.</p>\n<p>וְאִם תֹּאמַר, כָּתוּב כִּי רוּחַ הַחַיָּה בָּאוֹפַנִּים - גַּם כָּךְ, זוֹ חַיָּה שֶׁהִיא לְצַד יָמִין, לְצַד שְׂמֹאל, וְלַצַּד הַקִּדְמִי וְלַצַּד הָאֲחוֹרִי, וְזוֹהִי חַיָּה, וְאֵלּוּ הֵן חַיּוֹת.</p>\n<p>כָּתוּב (יחזקאל י) הִיא הַחַיָּה אֲשֶׁר רָאִיתִי תַּחַת אֱלֹהֵי יִשְׂרָאֵל בִּנְהָר כְּבָר. זוֹהִי חַיָּה שֶׁמְּרַבַּעַת לְאַרְבַּעַת צִדְדֵי הָעוֹלָם, וְזוֹהִי שֶׁעוֹמֶדֶת בְּכִסֵּא לִדְמוֹת הָאָדָם, כַּכָּתוּב (שם א) וְעַל דְּמוּת הַכִּסֵּא דְּמוּת כְּמַרְאֵה אָדָם עָלָיו מִלְמָעְלָה. וְהַכֹּל לְאוֹתָהּ דַּרְגָּה עֶלְיוֹנָה קְדוֹשָׁה נִסְתֶּרֶת שֶׁנִּקְרֵאת אֱלֹהֵי יִשְׂרָאֵל.</p>\n<p>וְזוֹ הַחַיָּה שֶׁלְּמַטָּה שֶׁעוֹמֶדֶת תַּחַת כָּל הַחַיּוֹת הָעֶלְיוֹנוֹת הַקְּדוֹשׁוֹת, מִשּׁוּם שֶׁיֵּשׁ חַיּוֹת עֶלְיוֹנוֹת אֵלּוּ עַל אֵלּוּ. הַכִּסֵּא שֶׁתַּחַת אֱלֹהֵי יִשְׂרָאֵל זוֹ הַדְּמוּת שֶׁל יַעֲקֹב. וְהַכִּסֵּא שֶׁלְּמַטָּה זוֹ הַדְּמוּת שֶׁל דָּוִד, הִיא הַמְרַבַּעַת לְאַרְבָּעָה צִדְדֵי הָעוֹלָם. וּמִשּׁוּם כָּךְ רוּחַ יוֹצֵאת מִלְמַעְלָה וְשׁוֹפַעַת וְנִמְשֶׁכֶת מִדַּרְגָּה לְדַרְגָּה, עַד שֶׁמַּכָּה בְּכָל הַתַּחְתּוֹנִים שֶׁלְּמַטָּה, וְאוֹתָהּ רוּחַ מַנְהִיגָה אֶת הַכֹּל, וּמַתְקִין אֶת תִּקּוּן הַכֹּל לְתַקֵּן.</p>\n<p>(באותו גון ממש שיש תקון למעלה באותו) וּבְאוֹתוֹ גָוֶן מַמָּשׁ מִתְתַּקֵּן לְמַטָּה. מַה כָּתוּב לְמַעְלָה? כִּי רוּחַ הַחַיָּה בָּאוֹפַנִּים. וְכָתוּב אֶל אֲשֶׁר יִהְיֶה שָּׁמָּה הָרוּחַ לָלֶכֶת יֵלֵכוּ. מַה כָּתוּב לְמַטָּה? וַיָּקֶם מֹשֶׁה אֶת הַמִּשְׁכָּן. בַּמֶּה? (למה,,) לִהְיוֹת הָרוּחַ שֶׁל אוֹתָהּ הַדַּרְגָּה שֶׁלְּמַטָּה בְּאוֹתָהּ הַדְּמוּת שֶׁל הָרוּחַ הָעֶלְיוֹנָה, הִיא הַחַיָּה אֲשֶׁר רָאִיתִי תַּחַת אֱלֹהֵי יִשְׂרָאֵל, וּמֵהַחַיָּה הַזּוֹ יוֹצֵאת רוּחַ לְהַתְקִין הַכֹּל. גַּם כָּךְ מֹשֶׁה. הִיא הַחַיָּה, שֶׁנָּתְנָה רוּחַ לְמַטָּה לְהַתְקִין הַכֹּל. מִשּׁוּם כָּךְ כָּתוּב, וַיָּקֶם, וַיִּתֵּן, וַיָּשֶׂם. וּבַכֹּל שָׂם רוּחַ לְהַתְקִין הַכֹּל.</p>"],[9522011904,"<p>בֹּא וּרְאֵה, בָּרִאשׁוֹנָה, בַּמִּשְׁכָּן שֶׁמֹּשֶׁה עָשָׂה, הוּא הִתְקִין אוֹתוֹ בְּסוֹד אוֹתָהּ דַּרְגָּה עֶלְיוֹנָה שֶׁהוּא עוֹמֵד בָּהּ. בַּמִּקְדָּשׁ שֶׁשְּׁלֹמֹה עָשָׂה, הוּא תִּקֵּן אוֹתוֹ בְּסוֹד אוֹתוֹ נָהָר שֶׁיּוֹצֵא מֵעֵדֶן, שֶׁהוּא שְׁלוֹם הַבַּיִת וְהוּא מְנוּחַת הַבַּיִת. וְעַל כֵּן בְּסוֹד הַמִּשְׁכָּן הוּא קִרְבַת הַחֲבִיבוּת בַּדַּרְגָּה (בסוד) שֶׁל הַגּוּף, אוֹתָהּ הַדַּרְגָּה שֶׁל מֹשֶׁה עוֹמֶדֶת בָּהּ קִרְבַת הַחֲבִיבוּת, וְלֹא שֶׁל מְנוּחָה. כְּשֶׁבָּא שְׁלֹמֹה וְהִתְקִין אֶת הַמִּקְדָּשׁ, אוֹתוֹ הַמִּקְדָּשׁ הִתְתַּקֵּן בַּסּוֹד שֶׁל חֲבִיבוּת הַמְּנוּחָה. וְלָכֵן כָּתוּב בִּשְׁלֹמֹה, הוּא יִהְיֶה אִישׁ מְנוּחָה.</p>\n<p>וּמִשּׁוּם כָּךְ, זֶה הִתְקִין בְּדַרְגָּה אַחַת, וְזֶה הִתְקִין בְּדַרְגָּה אַחַת, דְּיוֹקְנוֹ שֶׁל זֶה בָּזֶה. וְסוֹד זֶה - (בראשיתלז) אֵלֶּה תֹּלְדוֹת יַעֲקֹב יוֹסֵף.</p>\n<p>הָרֵאשִׁית שֶׁהִתְחִיל מֹשֶׁה לְהַתְקִין בַּמָּקוֹם הַזֶּה, שֶׁהוּא צַד הַקְּדֻשָּׁה, הֵקִים קִימָה שֶׁל נְקֻדָּה שֶׁעוֹמֶדֶת בָּאֶמְצַע שֶׁהָיְתָה חֲשׁוּכָה וּשְׁקוּעָה בִּמְקוֹמָהּ, וְלֹא נִרְאֵית וְלֹא מְאִירָה כְּלָל. וְרֵאשִׁית הַכֹּל הֵקִים אֶת הַנְּקֻדָּה הַזּוֹ שֶׁשָּׁקְעָה בִּמְקוֹמָהּ, וְאַחַר כָּךְ כָּל הַיֶּתֶר, שֶׁהוּא בִּנְיָנָהּ שֶׁל הַנְּקֻדָּה הַזּוֹ.</p>\n<p>וְאִם נְקֻדָּה זוֹ לֹא הָיְתָה מִתְתַּקֶּנֶת (מוקמת) בָּרִאשׁוֹנָה, כָּל מַה שֶּׁהִתְפַּשֵּׁט מִמֶּנָּה לֹא יָכוֹל הָיָה לְהִתְתַּקֵּן. וְכֵיוָן שֶׁנְּקֻדָּה זוֹ הוּקְמָה וּמְאִירָה, אָז כָּל שְׁאָר הַתִּקּוּן הָאַחֵר הִתְתַּקֵּן, וְהִתְיַשְּׁבָה בִּמְקוֹמָהּ. וְעַל כֵּן, וַיָּקֶם מֹשֶׁה אֶת הַמִּשְׁכָּן. (אות) זוֹ נְקֻדָּה שֶׁהָיְתָה חֲשׁוּכָה וּשְׁקוּעָה בִּמְקוֹמָהּ. וְאַחַר כָּךְ, וַיִּתֵּן אֶת אֲדָנָיו, אוֹתָם הָעַמּוּדִים שֶׁהֵם מִכָּאן וּמִכָּאן. (משום שיש אדנים ויש אדנים) וְכֻלָּם הָיוּ מֵאָה לְחֶשְׁבּוֹן, וְכֻלָּם נֶחְלְקוּ לִמְקוֹמָם, שֶׁכָּתוּב מְאַת אֲדָנִים לִמְאַת הַכִּכָּר כִּכָּר לָאָדֶן.</p>\n<p>וְאֵלּוּ הָאֲדָנִים הֲרֵי בֵּאַרְנוּ, אֲבָל לֹא כָתוּב בָּהֶם קִימָה, אֶלָּא וַיִּתֵּן, נְתִינָה, לָשִׂים עֲלֵיהֶם מַה שֶּׁצָּרִיךְ, מִשּׁוּם שֶׁיֵּשׁ תַּחְתּוֹנִים וְעֶלְיוֹנִים רוֹכְבִים זֶה עַל זֶה. וְעַל כֵּן כָּתוּב בָּהֶם נְתִינָה.</p>\n<p>בְּאוֹתָהּ שָׁעָה שֶׁהַנְּקֻדָּה הַזּוֹ הוּקְמָה, נִשְׁקַע הַצַּד הָאַחֵר וְלֹא נִמְחָה כְּלָל, שֶׁהֲרֵי אֵינוֹ נִמְחֶה אֶלָּא לְאוֹתוֹ הֶעָתִיד לָבֹא שֶׁיִּמָּחֶה מִן הָעוֹלָם, כְּמוֹ שֶׁנִּתְבָּאֵר, הוּקַם זֶה וְנִשְׁקַע זֶה.</p>\n<p>וַיִּתֵּן אֶת אֲדָנָיו, אָז הִתְחִיל לְהִתְחַזֵּק הַצַּד (הרוח) הַזֶּה שֶׁל קְדֻשָּׁה, וּכְשֶׁנִּתְּנוּ אֵלּוּ הָעַמּוּדִים, נִשְׁקְעוּ כָּל אֵלּוּ שֶׁל הַצַּד הָאַחֵר וְנִכְנְסוּ לְנֶקֶב תְּהוֹם רַבָּה, מִשּׁוּם שֶׁעָלָה הַצַּד הַזֶּה שֶׁל הַקְּדֻשָּׁה הָעֶלְיוֹנָה, וְהוּא חֶלְקוֹ לְהִתְעַלּוֹת, וְאָז נִשְׁקָע הַצַּד הָאַחֵר, וְנִכְנָס לְאוֹתוֹ נֶקֶב שֶׁל הַתְּהוֹם.</p>\n<p>וְאִלְמָלֵא שֶׁיִּשְׂרָאֵל חָטְאוּ (בראשונה), לֹא יָכוֹל לִשְׁלֹט בָּעוֹלָם יוֹתֵר. וְאַחַר כָּךְ אַף כָּךְ חָטְאוּ, וְהִמְשִׁיכוּ אוֹתוֹ עֲלֵיהֶם כְּמוֹ בָּרִאשׁוֹנָה, וּמֵאוֹתוֹ יוֹם לֹא הָיְתָה עֵצָה, אֶלָּא לָתֵת חֵלֶק לְאוֹתוֹ הַצַּד הָאַחֵר בַּכֹּל - בְּסוֹד הַקָּרְבָּנוֹת וְהַנְּסָכִים וְהָעוֹלוֹת. וּבא רְאֵה, מִשּׁוּם כָּךְ הָעוֹלָה נִשְׂרֶפֶת כֻּלָּהּ בָּאֵשׁ, לְהַכְנִיעַ אֶת הַצַּד הַזֶּה וּלְהַעֲלוֹת אֶת צַד הַקְּדֻשָּׁה, וּמִשּׁוּם כָּךְ, כְּשֶׁמֹּשֶׁה הֵקִים אֶת הַמָּקוֹם הַזֶּה, נִשְׁקַע הַמָּקוֹם הַזֶּה.</p>\n<p>בֹּא וּרְאֵה, וַיָּקֶם מֹשֶׁה - זֶהוּ צַד הַקְּדֻשָּׁה, וְנִשְׁקָע הַצַּד הָאַחֵר הַטָּמֵא. וַיִּתֵּן - לְצַד הַקְּדֻשָּׁה הַזֶּה, וְנִרְפֶּה הַצַּד הָאַחֵר הַטָּמֵא. וַיָּשֶׂם - לְצַד הַקְּדֻשָּׁה הַזֶּה, וְנִכְנָע הַצַּד הָאַחֵר שֶׁל הַטֻּמְאָה. וְאַחַר כָּךְ, וַיִּתֵּן אֶת בְּרִיחָיו.</p>\n<p>וְאַחַר כָּךְ וַיָּקֶם. מָה הַטַּעַם? כְּדֵי שֶׁתִּהְיֶה רֵאשִׁית וְסִיּוּם בְּקִימָה. הִתְחִיל בְּקִימָה וְסִיֵּם בְּקִימָה, מִשּׁוּם שֶׁבַּכֹּל צָרִיךְ קִימָה - רֵאשִׁית וְסִיּוּם. קִימָה בַּהַתְחָלָה שֶׁהִתְרַפָּה הַצַּד הָאַחֵר, וְזוֹהִי קִימָה לְצַד הַקְּדֻשָּׁה, כְּדֵי לְהִתְקַיֵּם וְלַעֲלוֹת לְמַעְלָה, לִהְיוֹת הִתְקַשְּׁרוּת אַחַת כָּרָאוּי. מִשּׁוּם שֶׁכָּל זְמַן שֶׁקְּדֻשָּׁה שׁוֹלֶטֶת וְעוֹלָה, הַטֻּמְאָה נִשְׁפֶּלֶת וּמֻנְמֶכֶת לְמַטָּה.</p>"],[9522011905,"<p>רֹאשׁ הַנְּקֻדָּה שֶׁעוֹמֶדֶת תַּחַת דְּרָגוֹת שֶׁבַּצַּד הָאַחֵר, הִיא רֹאשׁ הַדַּרְגָּה שֶׁלַּחוּץ, רֹאשׁ הַזָּכָר, וְעוֹמֵד רוֹכֵב עַל גָּמָל אֶחָד, הוּא רֹאשׁ לַחוּץ שֶׁל עִרְבּוּב אֶחָד שֶׁל חֹשֶׁךְ שֶׁמִּתְפַּשֵּׁט.</p>\n<p>שֶׁכְּשֶׁעָשָׁן יוֹצֵא מִתּוֹךְ רֹגֶז הַקָּשֶׁה, מִתְפַּשֵּׁט אוֹתוֹ עָשָׁן, וְהוֹלֵךְ רֹגֶז אַחַר רֹגֶז, זֶה עַל זֶה, וְזֶה רוֹכֵב וְשׁוֹלֵט עַל זֶה בְּמַרְאֶה שֶׁל זָכָר וּנְקֵבָה לִהְיוֹת הַכֹּל רֹגֶז קָשֶׁה.</p>\n<p>וּכְשֶׁמַּתְחִיל הֶעָשָׁן לְהִתְפַּשֵּׁט, דּוֹחֵק מִתּוֹךְ הָרֹגֶז בְּדחַק שֶׁל נְקֻדָּה אַחַת לְהִתְפַּשֵּׁט, וְאַחַר כָּךְ מִתְפַּשֵּׁט עֲשַׁן הָרֹגֶז בְּעַקְמִימוּת, כְּמוֹ נָחָשׁ אֶחָד חָכָם לְהָרַע.</p>\n<p>הָרֹאשׁ שֶׁמַּתְחִיל לְהִתְפַּשֵּׁט, הוּא דַּרְגָּה חֲשׁוּכָה, עוֹלֶה וְיוֹרֵד, הוֹלֵךְ וְשָׁט וְנָח בִּמְקוֹמוֹ, עַד שֶׁעוֹמֶדֶת הַדַּרְגָּה לְהִתְיַשֵּׁב מֵאוֹתוֹ הֶעָשָׁן שֶׁיּוֹצֵא מִתּוֹךְ הָרֹגֶז, וְהוּא צֵל. צֵל עַל מָקוֹם אַחֵר שֶׁנִּקְרָא מָוֶת. וּכְשֶׁשְּׁנֵיהֶם מִתְחַבְּרִים כְּאֶחָד, נִקְרָא צַלְמָוֶת, וַהֲרֵי בֵּאַרְנוּ, שְׁתֵּי דְרָגוֹת הֵן שֶׁמִּתְחַבְּרוֹת כְּאֶחָד.</p>\n<p>הַצֵל הַזֶּה הוּא רֵאשִׁית שֶׁל הַנְּקֻדָּה הַתַּחְתּוֹנָה הַחִיצוֹנָה, חֲשֵׁכָה שֶׁמְּרֻחֶקֶת מֵהַנְּקֻדָּה הַקְּדוֹשָׁה שֶׁעוֹמֶדֶת בָּאֶמְצַע. וְזוֹהִי נְקֻדָּה שֶׁלֹּא עוֹמֶדֶת וְלֹא נִרְשֶׁמֶת בִּגְוָנֶיהָ, וּמִמֶּנָּה מִתְפַּשֶּׁטֶת הִתְפַּשְּׁטוּת הַחוּצָה וּלְמַטָּה, וְהִיא שׁוֹקַעַת, וְלֹא נִרְאֵית וְלֹא נִרְשֶׁמֶת.</p>\n<p>זוֹ הִתְפַּשְּׁטָה לְמַטָּה, לְיָמִין וְלִשְׂמֹאל, וְהִתְפַּשְּׁטָה לְמַטָּה לְתוֹךְ הַחֲשֵׁכָה כְּנֶגֶד אֶלֶף וּמֵאָה. שְׁנֵי עַמּוּדִים נֶחְקָקִים לְצַד זֶה וּלְצַד זֶה, מִתְפַּשֶּׁטֶת הַחֲשֵׁכָה לְתוֹךְ גָּוֶן שָׁחֹר וְלֹא שָׁחֹר, שֶׁהֲרֵי אֵין לוֹ שׁוּם צֶבַע שֶׁיִּתְקַיֵּם בּוֹ. וּבְאוֹתָהּ הִתְפַּשְּׁטוּת עוֹמְדוֹת הַחֲשֵׁכוֹת אוֹתָן שֶׁשִּׁמְּשׁוּ בְמִצְרַיִם, שֶׁכָּתוּב (שמות י) וְלֹא רָאוּ אִישׁ אֶת אָחִיו וְלֹא קָמוּ אִישׁ מִתַּחְתָּיו שְׁלֹשֶׁת יָמִים. וְכָתוּב וְיָמֵשׁ חֹשֶׁךְ.</p>\n<p>הַהִתְפַּשְּׁטוּת הַזּוֹ מִתְפַּשֶּׁטֶת בְּכַמָּה מִינִים, מְשֻׁנִּים אֵלּוּ תּוֹךְ אֵלּוּ. בְּתוֹךְ אוֹתָהּ הִתְפַּשְּׁטוּת יוֹצֵא זהַר אֶחָד שֶׁצָּבוּעַ בְּזָהָב, וְזֶהוּ זָהָב אָדם. מִתְפַּשֵּׁט הַזֹּהַר הַזֶּה וּמְכַסֶּה אֶת הַחֹשֶׁךְ שֶׁל הָרֹאשׁ, וְהוּא הַזָּהָב שֶׁנִּכְלָל בּוֹ הַחֹשֶׁךְ.</p>\n<p>הַחֹשֶׁךָ הַזֶּה מִתְפַּשֵּׁט לְיָמִין וְלִשְׂמֹאל, וּמִתּוֹךְ שְׁנֵי הַצְּדָדִים הַלָּלוּ יוֹצֵא גָוֶן אֶחָד שֶׁל כֶּסֶף שֶׁלֹּא זוֹהֵר. מִתְפַּשֵּׁט הַגָּוֶן הַזֶּה שֶׁל הַכֶּסֶף, וּמְכַסֶּה אֶת הַחֹשֶׁךְ, וְנִכְלָל זֶה בָּזֶה וְיוֹרֵד לְמַטָּה.</p>\n<p>מִתְפַּשֵּׁט הַחֹשֶׁךְ, וְעוֹמְדוֹת שְׁתֵּי חֲשֵׁכוֹת, שֶׁעוֹמְדוֹת (שיוצאות) בָּרֹאשׁ הַשָּׁחֹר, וּמִשָּׁם מִתְפַּשֵּׁט וְיוֹצֵא גָוֶן אֶחָד שֶׁל נְחֹשֶׁת.</p>\n<p>וּמִשָּׁם מִתְפַּשֵּׁט לְמַטָּה אוֹתוֹ הַחֹשֶׁךְ, וְעוֹמֵד עַמּוּד, וְיוֹצֵא גָוֶן אֶחָד שָׁחֹר בְּמַרְאֶה שֶׁל בַּרְזֶל, וְהַכֹּל בְּסוֹד הַחֲשֵׁכָה.</p>\n<p>מִבֵּין שְׁנֵי הָעַמּוּדִים יוֹצֵא עַמּוּד אֶחָד חָשׁוּךְ בַּחֲשֵׁכָה, וְכָל הַגְּוָנִים הַלָּלוּ נִרְאִים בּוֹ, וְזוֹהִי הָעָרְלָה שֶׁמַּנְהִיגָה זָכָר לַנְּקֵבָה לְהִזְדַּוֵּג כְּאֶחָד וְלִהְיוֹת אֶחָד.</p>\n<p>הָעַמּוּדִים הַלָּלוּ יְדוּעִים בְּשֶׁבַע דְּרָגוֹת גְּדוֹלוֹת (זכרים), הַדַּרְגָּה הָרִאשׁוֹנָה הִיא הַדַּרְגָּה שֶׁעוֹמֶדֶת בַּצַּד שֶׁל הַחֲשֵׁכָה הַזּוֹ. זוֹ הַחֲשֵׁכָה עוֹלָה תּוֹךְ הַסְתָּרָה שֶׁל הֶעָשָׁן שֶׁל הָאֵשׁ, זֶה כָּלוּל בְּגָוֶן שֶׁל עָשָׁן, וּבְגָוֶן שֶׁל אֵשׁ, וּבְגָוֶן שָׁחֹר. שְׁלֹשֶׁת הַגְּוָנִים הַלָּלוּ נִפְרָדִים לְכַמָּה צְדָדִים, לְהִתְעַקֵּם בַּעֲקֻמֵּי הָעוֹלָם.</p>\n<p>גּוֹן הֶעָשָׁן הַזֶּה יוֹרֵד לָעוֹלָם וְנִכְנָס לְכַמָּה צְדָדִים, וְזֶה מִתְפַּשֵּׁט בָּעוֹלָם, וּמֵסִית אֶת רוּחוֹת הָאֲנָשִׁים לְרֹגֶז, לְהַסְטוֹת אֶת דַּרְכֵיהֶם וּלְהִתְחַזֵּק בְּרֻגְזָם. וְעַל זֶה כָּתוּב, (תהלים פא) לֹא יִהְיֶה בְךְ אֵל זָר וְלֹא תִשְׁתַּחֲוֶה לְאֵל נֵכָר. לֹא יִהְיֶה בְךְ אֵל זָר - זֶה הַזָּכָר. וְלֹא תִשְׁתַּחֲוֶה לְאֵל נֵכָר - זוֹ הַנְּקֵבָה. זֶהוּ הָרֹגֶז שֶׁשּׁוֹלֵט וּמִתְחַזֵּק בָּעוֹלָם וְנִכְנָס לְתוֹךְ בְּנֵי הָאָדָם וּמְחַזֵּק אוֹתָם לְהָרַע.</p>\n<p>גּוֹן הָאֵשׁ, הַגָּוֶן הַזֶּה יוֹרֵד לָעוֹלָם, וְנִכְנָס לְכַמָּה צְדָדִים לְהָרַע, לַהֲרֹג, וְלִשְׁפֹּךְ דָּמִים וּלְקַפֵּחַ בְּנֵי אָדָם, וְעַל זֶה כָּתוּב, (משלי א) אִם יֹאמְרוּ לְכָה אִתָּנוּ נֶאֶרְבָה לְדָם נִצְפְּנָה לְנָקִי חִנָּם. מִשּׁוּם שֶׁיֵּשׁ שׁוֹפְכֵי דָמִים לְחִנָּם וְהוֹרְגִים לְחִנָּם. וִישׁ שׁוֹפְכֵי דָמִים וְהוֹרְגִים בַּקְּרָב, וְזֶה מִצַּד הַזָּכָר וְזֶה מִצַּד הַנְּקֵבָה. צַד הַזָּכָר שׁוֹפֵךְ דָּמִים לְחִנָּם, כְּמוֹ שֶׁאָמַרְנוּ. צַד הַנְּקֵבָה, כְּדֵי לַעֲרֹךְ קְרָבוֹת וְלַהֲרֹג אֵלֶּה בְּאֵלֶּה, וְכָל הַקְּרָבוֹת וְהַהֶרֶג שֶׁל אֵלֶּה בְּאֵלֶּה בָּאִים מֵאוֹתוֹ צַד שֶׁל הַנְּקֵבָה.</p>\n<p>גָּוֶן שָׁחֹר, גָּוֶן זֶה יוֹרֵד לָעוֹלָם וְיוֹרֵד לְהִתְמַנּוֹת עַל כָּל הַפְּצוּעִים וְהַמֻּכִּים, וּתְפוּסֵי גוּף, וּצְלוּבִים וַחֲנוּקִים, לְהָרַע תָּמִיד לִבְנֵי אָדָם. שְׁלֹשֶׁת הַגְּוָנִים הַלָּלוּ נִפְרָדִים לְכַמָּה צְדָדִים שֶׁל הָעוֹלָם וּמִתְפַּשְּׁטִים בְּתוֹךְ בְּנֵי הָעוֹלָם.</p>\n<p>גּוֹן הֶעָשָׁן יוֹרֵד לָעוֹלָם, וְזֶהוּ הַגָּוֶן הָרִאשׁוֹן שֶׁיּוֹצֵא מִתּוֹךְ הַנְּקֻדָּה הַשְּׁקוּעָה מֵאוֹתוֹ הַצֵּל שֶׁאָמַרְנוּ, שֶׁהוּא סָמָאֵ\"ל, שֶׁרוֹכֵב עַל גָּמָל, כְּמוֹ שֶׁנִּתְבָּאֵר, וְגוֹן הֶעָשָׁן הַזֶּה נִקְרָא קַצְפִּיאֵ\"ל הַגָּדוֹל. וְזֶהוּ הָרֹגֶז שֶׁל בְּנֵי אָדָם שֶׁמְּחַזְּקִים אֶת הַלֵּב בְּרֹגֶז.</p>\n<p>תַּחַת זֶה מְמֻנִּים אֶלֶף וְשֵׁשׁ מֵאוֹת קְבוּצוֹת, שֶׁהֵן רֹגֶז הַגּוּפִים שֶׁל בְּנֵי אָדָם, מִשּׁוּם שֶׁיֵּשׁ רֹגֶז שֶׁשּׁוֹלֵט בָּעוֹלָם לַעֲשׂוֹת דִּין. אֲבָל זֶה (צד) הוּא רֹגֶז שֶׁשּׁוֹלֵט וְנִכְנָס לְגוּף בְּנֵי הָאָדם שֶׁמִּתְרַגְּזִים בָּרֹגֶז הַזֶּה. וְהָרֹגֶז הַזֶּה הוּא יְסוֹד לְכָל שְׁאָר הַגְּוָנִים לַעֲשׂוֹת בָּהֶם בִּנְיָן לְהָרַע, מִשּׁוּם שֶׁהֶעָשָׁן הַזֶּה יוֹצֵא מִתּוֹךְ רֹגֶז הָאֵשׁ הָעֶלְיוֹנָה שֶׁלּוֹהֶטֶת, וְזֶהוּ הָרִאשׁוֹן לְאוֹתָהּ הָאֵשׁ.</p>\n<p>אַרְבָּעָה רְגָזִים נִפְרָדִים מֵאוֹתוֹ הָרֹגֶז, וְרֹגֶז הָרִאשׁוֹן נִקְרָא רֹגֶז, וְזֶהוּ שֶׁמַּרְגִּיז אֶת לֵב בְּנֵי הָאָדָם, וְזֶהוּ שֶׁיּוֹרֵד וְהוֹלֵךְ וּמֵסִית אֶת בְּנֵי הָאָדָם שֶׁמִּתְרַגְּזִים בְּרָגְזָם, וְזֶהוּ שֶׁמּוֹשֵׁךְ אֶת הַמַּשְׁחִית עַל הָעוֹלָם. (ועל זה כתוב (חבקוק ג) ברגז רחם תזכר).</p>\n<p>הָרֹגֶז הַשֵּׁנִי, זֶהוּ שֶׁיּוֹרֵד לָעוֹלָם וּמְשׁוֹטֵט וּמִתְפַּשֵּׁט לְכָל הַצְּדָדִים, וְזֶה נִקְרָא שִׂנְאָה. וְזֶה יוֹרֵד וְנִכְנָס בִּבְנֵי אָדָם. וְזֶה, כֵּיוָן שֶׁהוּא נִכְנָס, נִקְרָא מַשְׁחִית שָׁקֵט, וְזֶהוּ רֹגֶז שֶׁשּׁוֹתֵק, וְזֶהוּ שֶׁמִּשְׁתַּתֵּף בְּאוֹתוֹ מָקוֹם שֶׁל הַנְּקֵבָה. וְזֶהוּ רֹגֶז שֶׁל שְׁתִיקָה שֶׁעוֹמֵד בַּעֲקִימוּת זֶהוּ הַקָּשֶׁה מִכֻּלָּם, מִשּׁוּם שֶׁהוּא כְּמוֹ הַנָּחָשׁ, שֶׁשּׁוֹתֵק תָּמִיד וְהוֹרֵג אַחַר כָּךְ.</p>\n<p>הָרֹגֶז הַשְּׁלִישִׁי, זֶהוּ רֹגֶז הָפוּךְ מֵהָרִאשׁוֹן - שֶׁהוֹלֵךְ וּמִתְחַזֵּק וְלֹא שׁוֹתֵק, אֶלָּא נִגְלֶה אוֹתוֹ רֹגֶז, וְכָל מַה שֶּׁהוּא מִתְגַּלֶּה - כָּךְ נִשְׁבָּר בְּכָל מַה שֶּׁהִתְגַּלָּה, וְלֹא שׁוֹתֵק. כָּךְ נִשְׁבָּר, וְכָךְ נִקְרָא: רֹגֶז שָׁבוּר.</p>\n<p>הָרֹגֶז הָרְבִיעִי, רֵאשִׁיתוֹ חָזָק וְסוֹפוֹ שָׁבוּר, וְעַל כֵּן זֶהוּ רֹגֶז שֶׁמְּהֻפָּךְ מִן הָרִאשׁוֹן. מִשּׁוּם כָּךְ זֶהוּ צַד הַשָּׁבוּר מִכֻּלָּם. וְעַל כֵּן הַכֹּל הוּא בְּדַרְגָּה רִאשׁוֹנָה.</p>\n<p>דַּרְגָּה שְׁנִיָּה, הִיא דַּרְגָּה שֶׁיּוֹצֵאת מֵחֲשֵׁכָה, וְזֶהוּ גָּוֶן חָשׁוּךְ שֶׁעוֹמֵד מִתּוֹךְ הַחֲשֵׁכָה הַזּוֹ, מִשּׁוּם שֶׁהַכֹּל קַיָּם מִתּוֹךְ הַחֲשֵׁכָה וְעוֹמֵד בִּדְרָגוֹת יְדוּעוֹת. וְזֶה מִתְפַּשֵּׁט מַטָּה בִּגְוָנִים יְדוּעִים.</p>\n<p>בַּדַּרְגָּה הַזּוֹ קַיָּמִים שְׁלֹשׁ מֵאוֹת צְדָדִים נִפְרָדִים זֶה מִזֶּה, וְכֻלָּם כְּלוּלִים זֶה בָּזֶה. וְאַף עַל גַּב שֶׁמְּשֻׁנִּים זֶה מִזֶּה וּמִתְגַּבְּרִים (ומאירים) זֶה מִזֶּה, הַכֹּל כָּלוּל זֶה בָּזֶה. וּמִשּׁוּם כָּךְ כָּל הַדְּרָגוֹת יְדוּעוֹת בַּצַּד הַזֶּה לְהָרַע.</p>\n<p>מִכָּאן יוֹצְאִים כָּל אֵלּוּ הַמַּשְׁחִיתִים הַמְחַבְּלִים שֶׁמְּשׁוֹטְטִים בָּעוֹלָם וְעוֹשִׂים דִּין בְּגָלוּי (בעולם) עַל הַמַּעֲשִׂים הַנִּסְתָּרִים שֶׁנַּעֲשׂוּ תּוֹךְ הַחֹשֶׁךְ בַּסֵּתֶר, וְהֵם מְשׁוֹטְטִים בָּעוֹלָם וְעוֹשִׂים בָּהֶם דִּין בְּגָלוּי. וּמִשּׁוּם כָּךְ, כָּל אֵלּוּ שֶׁמְּשׁוֹטְטִים בָּעוֹלָם וְעוֹשִׂים דִּין בְּגָלוּי, כֻּלָּם עוֹמְדִים כְּנֶגֶד בְּנֵי אָדָם לְהִזְדַּמֵּן תָּמִיד אֶל אוֹתָם חֲטָאִים נִסְתָּרִים שֶׁאָמַרְנוּ, וְאוֹתָם שֶׁנִּקְרָאִים אַף וְחֵמָה, מִתְחַבְּרִים עִמָּם, וְעוֹשִׂים דִּין עַל בְּנֵי אָדָם. זֶה נַעֲשֶׂה בָּעוֹלָם מִבַּעֲלֵי הַדִּין הַלָּלוּ שֶׁאָמַרְנוּ.</p>\n<p>דַּרְגָּה זוֹ עוֹמֶדֶת תּוֹךְ חֹשֶׁךְ וְאֵשׁ, שֶׁהוּא סוֹד אֶחָד, וּמִתּוֹךְ דַּרְגָּה זוֹ נִפְרָדוֹת כַּמָּה דְרָגוֹת חֲזָקוֹת (גברים) שֶׁעוֹמְדוֹת תַּחַת הַצַּד שֶׁל רָקִיעַ אֶחָד, שֶׁנִּקְרָא רָקִיעַ שָׁחֹר. דַּרְגָּה שְׁלִישִׁית זֶהוּ רָקִיעַ שֶׁמִּתְפַּשֵּׁט עַל כָּל אוֹתָן דְּרָגוֹת שֶׁהֵן אֲדֻמּוֹת כַּשּׁוֹשַׁנָּה, וְאֵלּוּ נִקְרָאוֹת הַזְּרוֹעוֹת שֶׁל הַצַּד הַזֶּה.</p>\n<p>תַּחַת אֵלּוּ מִתְפַּשְּׁטוֹת לְמַטָּה דְּרָגוֹת, עַד שֶׁמַּגִּיעוֹת לְתוֹךְ דַּרְגָּה שְׁלִישִׁית (אותו רקיע שחר), מִשּׁוּם שֶׁאֵלּוּ שֶׁבַּדַּרְגָּה הַשְּׁנִיָּה יוֹצְאִים מִתּוֹךְ אוֹתוֹ הָרָקִיעַ הַשָּׁחֹר וּמְשׁוֹטְטוֹת בָּעוֹלָם.</p>\n<p>אֵלּוּ מִיָּמִין, וְאֵלּוּ מִשְּׂמֹאל. אֵלּוּ שֶׁל הַיָּמִין נִפְרָדוֹת לִשְׁלֹשָׁה צְדָדִים, שֶׁהֵם שְׁלֹשָׁה קְשָׁרִים. וְאֵלּוּ שֶׁל הַשְּׂמֹאל נִפְרָדוֹת לִשְׁלֹשָׁה צְדָדִים, שֶׁהֵם שְׁלֹשָׁה קְשָׁרִים אֲחֵרִים.</p>\n<p>הַקֶּשֶׁר הָרִאשׁוֹן עוֹמֵד לְמַעְלָה. וְעָשָׁן חָשׁוּךְ בְּרֹגֶז נִקְשָׁר בּוֹ. בַּקֶּשֶׁר הַזֶּה יֵשׁ בּוֹ שְׁלֹשָׁה גְוָנִים חֲשׁוּכִים וּמְשֻׁנִּים זֶה מִזֶּה, וְנִכְלָלִים זֶה בָּזֶה. וְהַקֶּשֶׁר הַזֶּה הוּא כָּפוּף וְלֹא מִתְפַּשֵּׁט (נכנע), פְּרָט לִזְמַנִּים יְדוּעִים, וְזֶה הַנִּקְרָא עֶבְרָ\"ה.</p>\n<p>וְהוּא עוֹמֵד וְלֹא שׁוֹכֵךְ, מִשּׁוּם שֶׁלֹּא שׁוֹכֵךְ, פְּרָט לִזְמַן שֶׁיִּשְׂרָאֵל מַקְרִיבִים קָרְבָּן לְמַטָּה, מִשּׁוּם שֶׁבְּאוֹתוֹ זְמַן שׁוֹכֵךְ הָרֹגֶז וְנִכְנָע לְמַטָּה וְנֶחֱלָשׁ רָגְזוֹ (חזקו), וְלֹא יָכוֹל לִשְׁלֹט וּלְהִתְחַזֵּק. וּכְשֶׁזֶּה נֶחֱלָשׁ, אָז הַקֶּשֶׁר הַשֵּׁנִי, שֶׁהוּא בָּאֶמְצַע, לֹא יָכוֹל לִנְסֹעַ וּלְהַנְהִיג.</p>\n<p>הַקֶּשֶׁר הַשֵּׁנִי זֶהוּ שֶׁנִּקְרָא זַעַם, הַקֶּשֶׁר הַזֶּה הוּא שֶׁנּוֹסֵעַ מִמָּקוֹם לְמָקוֹם וּמַנְהִיג אֶת כָּל שְׁאָר הַקְּשָׁרִים, וְכָל שְׁאָר הַקְּשָׁרִים כֻּלָּם מִתְנַהֲגִים בּוֹ, וְכֻלָּם מֻחְזָקִים בְּקֶשֶׁר הַזֶּה. זֶהוּ שֶׁמַּנְהִיג אֶת כָּל הַצַּעַר שֶׁבָּעוֹלָם, מִשּׁוּם שֶׁכְּשֶׁמִּתְחַבֵּר בְּדַרְגָּה אַחֶרֶת, לְחַבֵּק אֶת הַנְּקֵבָה, אָז יוֹרְדִים לָעוֹלָם כָּל סוּגֵי הַצַּעַר וְכָל הַדְּחָקִים וְכָל הַצָּרוֹת, שֶׁהֲרֵי אֵינָם יְכוֹלִים לִשְׁלֹט זֶה בְּלִי זֶה. וְכָל הַדְּרָגוֹת נִתְּנוּ לַנְּקֵבָה לִשְׁלֹט וּלְהַסְטוֹת אֶת הָעוֹלָם, וְאִם לֹא שֶׁרוֹכֵב זֶה עַל זֶה וּמִתְחַבְּרִים זֶה לָזֶה, לֹא יְכוֹלִים לִשְׁלֹט.</p>\n<p>בֹּא וּרְאֵה, כְּשֶׁהָיָה אָדָם בְּגַן עֵדֶן לְהִתְעַסֵּק בַּעֲבוֹדַת רִבּוֹנוֹ, יָרַד סָמָאֵ\"ל הַזֶּה וְכָל אוֹתָן הַדְּרָגוֹת שֶׁבּוֹ, וְהָיָה רוֹכֵב עַל אוֹתוֹ הַנָּחָשׁ הָרָע כְּדֵי לְהַסְטוֹת אוֹתָם, מִשּׁוּם שֶׁאוֹתוֹ נָחָשׁ שֶׁעָמַד תַּחְתָּיו הוּא עָקֹם לְהַסְטוֹת אֶת בְּנֵי הָאָדָם וּלְפַתּוֹת אוֹתָם, מִשּׁוּם שֶׁכָּתוּב (משלי ה) כִּי נֹפֶת תִּ פְנָה שִׂפְתֵי זָרָה וְחָלָק מִשֶּׁמֶן חִכָּהּ. וְזֶה נוֹתֵן כֹּחַ, וְזֶה עוֹשֶׂה אֻמָּנוּת בָּעוֹלָם, וְזֶה בְּלִי זֶה לֹא יְכוֹלִים לִשְׁלֹט.</p>\n<p>מִשּׁוּם כָּךְ, כַּאֲשֶׁר אוֹתוֹ הַקֶּשֶׁר שֶׁל הָאֶמְצַע מִתְחַבֵּר בַּנְּקֵבָה, אָז הַדִּינִים יוֹרְדִים וְכָל הַדְּחָקִים לָעוֹלָם. וּכְשֶׁזֶּה לֹא מִתְחַזֵּק, שֶׁאֵינוֹ נוֹסֵעַ, הַכֹּל נִשְׁבָּר וְנִכְנָע, שֶׁלֹּא יָכוֹל לִשְׁלֹט. וְעַל כֵּן הַכֹּל נִשְׁבָּר וְנִכְנָע בְּסוֹד הַקָּרְבָּנוֹת שֶׁלְּמַטָּה. וְעוֹלֶה מִי שֶׁעוֹלֶה לְהִתְעַטֵּר לְמַעְלָה וּלְהִתְבָּרֵךְ מִן הָעֹמֶק הָעֶלְיוֹן, שֶׁמֵּאִיר לְכָל הַפָּנִים.</p>\n<p>הַקֶּשֶׁר הַשְּׁלִישִׁי הוּא קָשֶׁה בְּחֹזֶק יֶתֶר, וְזֶה נִקְרָא צָרָ\"ה, מִשּׁוּם שֶׁמִּזֶּה יוֹצְאִים שִׁלְטוֹן לְהַשְׁרוֹת דְּחָקִים וְלַעֲשׂוֹת צָרוֹת לַאֲנָשִׁים. וְהַסּוֹד שֶׁל שְׁלֹשֶׁת הַקְּשָׁרִים הַלָּלוּ, שֶׁכָּתוּב עֶבְרָה וְזַעַם וְצָרָה. אֵלּוּ שְׁלֹשֶׁת קִשְׁרֵי הַיָּמִין.</p>\n<p>שְׁלשָה קְשָׁרִים שֶׁל שְׂמֹאל, כְּשֶׁמִּתְחַזְּקִים כְּאֶחָד, אָז אוֹתוֹ הַשְּׂמֹאל נִקְרָא מִשְׁלַחַ\"ת מַלְאֲכֵי רָעִים, מִשּׁוּם שֶׁמֵּהַשְּׂמֹאל הַזֶּה נִשְׁלָחִים לְמַטָּה וְנוֹטְלִים חֹזֶק כָּל אוֹתָם הַמַּלְאָכִים הָרָעִים, אוֹתָם שֶׁיּוֹצְאִים מֵהַצַּד שֶׁלְּמַטָּה, כְּמוֹ שֶׁאָמַרְנוּ, וְכָל זֶה מִתּוֹךְ הַדַּרְגָּה הַשְּׁנִיָּה וְהַדַּרְגָּה הַשְּׁלִישִׁית.</p>\n<p>הַדַּרְגָּה הָרְבִיעִית, הִיא דַּרְגָּה שֶׁעוֹמֶדֶת מִתּוֹךְ עֹקֶם הָרֹגֶז, גּוֹן הָאֵשׁ. וְזוֹ נִקְרֵאת אֶמְצַע, שֶׁהוּא גּוּף שֶׁעוֹמֵד בֵּין שְׁתֵּי הַזְּרוֹעוֹת. כָּאן יֵשׁ לַהַט שֶׁלּוֹהֵט בְּאָדֹם כַּשּׁוֹשַׁנָּה. מִכָּאן יוֹצְאִים תֹּקֶף לָרֶדֶת לְמַטָּה, לִתְקֹף וְלִשְׁפֹּךְ דָּמִים. מִשּׁוּם שֶׁזֶּהוּ שֶׁנּוֹתֵן רְשׁוּת וְשִׁלְטוֹן לְמַטָּה לִתְקֹף וְלִשְׁפֹּךְ דָּמִים, זֶה נוֹבֵעַ לַנְּקֵבָה, וְזֶה צָרִיךְ אֶת זֶה כְּמוֹ שֶׁהַגּוּף צָרִיךְ אֶת הַנֶּפֶשׁ, וְהַנֶּפֶשׁ אֵינָהּ עוֹשָׂה אֻמָּנוּת אֶלָּא בַּגּוּף. וְעַל כֵּן כָּל הַכֹּחַ וְכָל הַתֹּקֶף יוֹצְאִים מִכָּאן, לְהַתְקִיף וְלַעֲשׂוֹת אֻמָּנוּת בָּעוֹלָם לְהָרַע, כִּנְקֵבָה שֶׁמְּקַבֶּלֶת מֵהַזָּכָר תָּמִיד.</p>\n<p>בְּכָל דַּרְגָּה וְדַרְגָּה וּבְכָל קֶשֶׁר וְקֶשֶׁר יֵשׁ כַּמָּה מְמֻנִּים וְכַמָּה גְּדוּדֵי מְחַבְּלִים, שֶׁכֻּלָּם מֻנְהָגִים בִּשְׁבִילָם, וְכָל הַמֻּנְהָגִים בִּגְלָלָם, כֻּלָּם לְמַטָּה, שֶׁהֵם חֵילוֹתֶיהָ שֶׁל הַנְּקֵבָה, וּלְכֻלָּם יֵשׁ דַּרְגָּה יְדוּעָה לְמַעְלָה לִהְיוֹת מֻנְהָגִים בָּהּ.</p>\n<p>כְּמוֹ שֶׁיֵּשׁ לַצַּד הָעֶלְיוֹן הַקָּדוֹשׁ הֵיכָלוֹת יְדוּעִים לִדְרָגוֹת עֶלְיוֹנוֹת לְהִכָּלֵל אֵלּוּ בְּאֵלּוּ - כָּךְ גַּם לְמַטָּה (בחשך) בְּהֵפֶךְ, בַּצַּד הָאַחֵר, יֵשׁ דְּרָגוֹת לְאוֹתָם הֵיכְלוֹת הַנְּקֵבָה לְהִכָּלֵל אֵלּוּ בְּאֵלּוּ.</p>\n<p>בַּדַּרְגָּה הַזּוֹ, שֶׁהִיא רְבִיעִית, עוֹמְדִים דִּינִים רָעִים לָרֶדֶת לְמַטָּה וּלְהִמָּסֵר לְאוֹתָם שֶׁעוֹשִׂים דִּין רַע קָשֶׁה. מִכָּאן יוֹנְקִים אֶת חָזְקָם לְהַתְקִיף וּלְהַשְׁלִים אוֹתוֹ הַדִּין שֶׁעוֹשִׂים. וּמִשּׁוּם כָּךְ, כָּל הַדְּרָגוֹת הַלָּלוּ כְּלוּלִים בָּהֶם, בְּכָל אוֹתָם הַהֵיכָלוֹת הַתַּחְתּוֹנִים שֶׁלְּצַד הַנְּקֵבָה שֶׁלְּמַטָּה. אַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים שֶׁמַּטִּים אֶת דַּרְכָּם מֵהַדֶּרֶךְ הַזּוֹ וְהוֹלְכִים אַחַר יִרְאַת הַקָּדוֹשׁ בָּרוּךְ הוּא לְהִתְקַדֵּשׁ בִּקְדֻשַּׁת רִבּוֹנָם. אַשְׁרֵיהֶם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>\n<p>דַּרְגָּה חֲמִישִׁית. הַדַּרְגָּה הַזּוֹ נֶחֱלֶקֶת לִשְׁתֵּי דְרָגוֹת (צדדים), יָמִין וּשְׂמֹאל. וְאֵלּוּ נִקְרָאִים שׁוֹקַיִם, מַשִּׂיגוֹת לְהָרַע וְלִרְדֹּף, מִשּׁוּם שֶׁכָּאן הַכֹּחַ שֶׁל הָרְדִיפָה שֶׁל כָּל הֶחֳלָאִים וְכָל הָרָעוֹת שֶׁרוֹדְפִים אַחַר הָרְשָׁעִים, וּכְשֶׁהַדִּין (הדרגה) הַזֶּה מִתְקָרֵב, אֲזַי (אסתר ג) הָרָצִים יָצְאוּ דְּחוּפִים. וְאוֹתָם הָרָצִים הֵם לְמַטָּה, לָרוּץ לְהָרַע. וְכָל אֵלּוּ נִקְרָאִים רוֹדְפִים, וְעַל זֶה כָּתוּב (איכה ד) קַלִּים הָיוּ רֹדְפֵינוּ מִנִּשְׁרֵי שָׁמָיִם.</p>\n<p>הַדַּרְגָּה הַזּוֹ נֶחֱלֶקֶת לִשְׁנֵי צְדָדִים, לְיָמִין וְלִשְׂמֹאל. שְׁלֹשָׁה קְשָׁרִים הֵם לְיָמִין, וּשְׁלֹשָׁה קְשָׁרִים הֵם לִשְׂמֹאל. וְהַקְּשָׁרִים הַלָּלוּ, וְאוֹתָם הַקְּשָׁרִים שֶׁאָמַרְנוּ, כֻּלָּם מִסְתַּכְּלִים לְאָחוֹר, מִשּׁוּם שֶׁכָּל הַקְּשָׁרִים הָעֶלְיוֹנִים הַקְּדוֹשִׁים מִסְתַּכְּלִים לְתוֹךְ הַפְּנִימִיִּים לַגּוּף, כְּמוֹ שֶׁנֶּאֱמַר (מלכים א ז) וְכָל אֲחֹרֵיהֶם בָּיְתָה. וְאֵלּוּ כֻּלָּם מִסְתַּכְּלִים לְאָחוֹר.</p>\n<p>מַה בֵּין זֶה לָזֶה? אֶלָּא אֵלּוּ הַקְּשָׁרִים הָעֶלְיוֹנִים הַקְּדוֹשִׁים כֻּלָּם בְּסוֹד שֶׁל אָדָם, וּמִשּׁוּם שֶׁהַכֹּל הוּא בְּסוֹד שֶׁל אָדָם, כָּתוּב כָּל אֲחֹרֵיהֶם בָּיְתָה. וְהַקְּשָׁרִים הָאֲחֵרִים הַלָּלוּ שֶׁאָמַרְנוּ, אוֹתָם קְשָׁרִים שֶׁל הָאֶמְצַע, כֻּלָּם מִסְתַּכְּלִים לְאָחוֹר, וְאֵלּוּ הֵם בְּסוֹד שֶׁל בְּהֵמָה. וּמִשּׁוּם כָּךְ כָּל אֲחוֹרֵיהֶם לְאָחוֹר. וְהַסּוֹד הַזֶּה כְּמוֹ שֶׁבֵּאַרְנוּ - (תהלים לו) אָדָם וּבְהֵמָה תּוֹשִׁיעַ ה'. זֶה בְּצַד שֶׁל אָדָם, וְזֶה בְּצַד שֶׁל הַבְּהֵמָה. וְכָךְ הַקָּרְבָּן עוֹלֶה - אָדָם וּבְהֵמָה.</p>\n<p>הַקֶּשֶׁר הָרִאשׁוֹן, בּוֹ עוֹמֵד גָּוֶן שֶׁל חֲשֵׁכָה בְּתוֹךְ עֲרָפֶל (בתוך טהר הערפל) שֶׁצּוֹמֵחַ בִּקְלָלָה תַּחַת הָאֶבֶן שֶׁעוֹמֶדֶת עָלָיו, שֶׁלֹּא צוֹמֵחַ. וְזֶה עוֹמֵד עַל הַזַּכָּאִים שֶׁיֵּשׁ בָּהֶם זְכֻיּוֹת, וְאֵין לָהֶם זְכוּת אָבוֹת לְהַחֲזִיק בָּהּ וּלְהָגֵן עֲלֵיהֶם.</p>\n<p>וּקְשָׁרִים אֲחֵרִים רוֹדְפִים אַחַר הָרְשָׁעִים שֶׁהִטּוּ אֶת דַּרְכָּם מִקֹּדֶם לָכֵן, וְרוֹדְפִים אַחֲרֵיהֶם, וְכָל אוֹתָם שֶׁרֹשֶׁם נִרְאֶה בָהֶם לִהְיוֹת מֻכָּרִים. מִשּׁוּם שֶׁכָּל אֵלּוּ שֶׁרְאוּיִים לְהֵעָנֵשׁ, מַלְאָךְ אֶחָד שָׁלִיחַ קָדוֹשׁ, שֶׁמִּצַּד הַגְּבוּרָה, יוֹרֵד וְרוֹשֵׁם בָּהֶם רֹשֶׁם, וְאוֹתוֹ הָרֹשֶׁם מֻכָּר לְמַעְלָה לְכָל אוֹתָם בַּעֲלֵי הַדִּין. וּכְשֶׁאוֹתוֹ רֹשֶׁם מֻכָּר לָהֶם - מִי שֶׁרָאוּי לֶחֳלָאִים, מַלְקִים אוֹתוֹ בֶּחֳלָאִים. מִי שֶׁרָאוּי לְמַכְאוֹבִים וְלִשְׁאָר הָעֳנָשִׁים, הַכֹּל רוֹאִים בְּאוֹתוֹ הָרֹשֶׁם.</p>\n<p>וּמִשּׁוּם כָּךְ כָּל אוֹתָם הַקְּשָׁרִים עוֹמְדִים לְאָחוֹר, וּבוֹעֲטִים בְּאוֹתָם שֶׁבּוֹעֲטִים בְּרִבּוֹנָם וּבְכָל אוֹתָם הָרְאוּיִים לִבְעֹט בָּהֶם, פְּרָט לְצַדִּיקִים וַחֲסִידִים וְשֶׁיֵּשׁ לָהֶם זְכוּת אָבוֹת שֶׁרוֹדְפִים אַחֲרֵיהֶם חֳלָאִים, שֶׁאֵלֶּה אֵין שׁוֹלְטִים בָּהֶם וְלֹא בָאִים לָהֶם חֳלָאִים מֵהַצַּד הַזֶּה.</p>\n<p>וְאִם תֹּאמַר, מֵאֵיזֶה מָקוֹם בָּאִים לָהֶם חֳלָאִים? בֹּא וּרְאֵה, כָּתוּב (ישעיה נג) וַה' חָפֵץ דַּכְּאוֹ הֶחֱלִי. וַה' חָפֵץ דַּכְּאוֹ, רוֹצֶה לְהַכּוֹת אוֹתוֹ וְלָתֵת לוֹ חֳלָאִים כְּדֵי לְזַכּוֹתָם לָעוֹלָם הַבָּא, וְלֹא מִצַּד הָאַחֵר, וְאֵלֶּה נִקְרָאִים יִסּוּרִים שֶׁל אַהֲבָה, וְהַכֹּל בְּמִשְׁקָל אֶחָד שֶׁל הַקֹּדֶשׁ עוֹלֶה.</p>\n<p>הַדַּרְגָּה הַשִּׁשִּׁית, זוֹ נִקְרֵאת עָרְלָה. וְזוֹ וְכָל אוֹתָן הַדְּרָגוֹת הַתַּחְתּוֹנוֹת לְמַטָּה, כֻּלָּן נִקְרָאוֹת עָרְלָה, כִּי יוֹנְקוֹת מֵהַצַּד הַזֶּה. וְזֶה תּוֹךְ סוֹד שֶׁל נָחָ\"שׁ בָּרִחַ (ישעיהכז), וְזֶה מֵינִיק אֶת אוֹתוֹ נָחָ\"שׁ עֲקַלָּתוֹ\"ן (שם). וְכָל הַדְּרָגוֹת הָאֲחֵרוֹת שֶׁנֶּאֱחָזוֹת בַּצַּד הַזֶּה נִקְרָאוֹת בֹּסֶר שֶׁל עָרְלָה, וְהַכֹּל בְּסוֹד אֶחָד הוֹלְכִים.</p>\n<p>וּבֹא רְאֵה, עַל זֶה כָּל אוֹתָם הָאִילָנוֹת שֶׁנִּנְטְעוּ בָאָרֶץ טֶרֶם הִשְׁרִישׁוּ, שׁוֹרָה עֲלֵיהֶם רוּחַ שֶׁל הָעָרְלָה הַזּוֹ, וְעַל זֶה כָּתוּב, (ויקרא יט) וַעֲרַלְתֶּם עָרְלָתוֹ אֶת פִּרְיוֹ שָׁלֹשׁ שָׁנִים יִהְיֶה לָכֶם עֲרֵלִים לֹא יֵאָכֵל. מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא, חֲבִיבוּתָם שֶׁל יִשְׂרָאֵל תָּמִיד אֵלָיו, וְהִרְחִיק אוֹתָם מִכָּל הַדְּרָכִים הָרעוֹת וּצְדָדִים הָרָעִים וְהַטְּמֵאִים לְהִדָּבֵק בְּצַד הַקְּדֻשָּׁה. אַשְׁרֵיהֶם בָּעוֹלָם הַזֶּה וְאַשְׁרֵיהֶם בָּעוֹלָם הַבָּא.</p>"],[9522011906,"<p>אָמַר רַבִּי שִׁמְעוֹן, הֲרֵי שָׁנִינוּ בְּאוֹתָם הַהֵיכָלוֹת, שֶׁהֵם עוֹמְדִים לְסַדֵּר אֶת סִדּוּר שִׁבְחוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, בֵּין סִדּוּר הָעוֹמֵד בְּדָבָר, בֵּין סִדּוּר הָעוֹמֵד בְּרָצוֹן. מִשּׁוּם שֶׁיֵּשׁ סִדּוּר הָעוֹמֵד בְּדָבָר, וְיֵשׁ סִדּוּר הָעוֹמֵד בְּרָצוֹן וְכַוָּנַת הַלֵּב, לָדַעַת וּלְהִסְתַּכֵּל, כְּדֵי לְהִסְתַּכֵּל לְמַעְלָה לְמַעְלָה עַד אֵין סוֹף, שֶׁשָּׁם נִתְקָעִים כָּל הָרְצוֹנוֹת וְהַמַּחֲשָׁבוֹת וְלֹא עוֹמְדִים בְּדָבָר כְּלָל. אֶלָּא כְּמוֹ שֶׁהוּא נִסְתָּר, כָּךְ כָּל דְּבָרָיו בַּסֵּתֶר.</p>\n<p>בֹּא וּרְאֵה, זֶה שֶׁאָמַרְנוּ בְּכָל אוֹתָם הַהֵיכָלוֹת (תלויים), כָּל אוֹתָם הַסִּדּוּרִים הֵם בִּכְלָל אֶחָד, כְּדֵי לְהַכְלִיל תַּחְתּוֹנִים בָּעֶלְיוֹנִים.</p>\n<p>אֲבָל בּא וּרְאֵה, כְּשֶׁסִּדֵּר מֹשֶׁה תְּפִלָּתוֹ בִּשְׁבִיל יִשְׂרָאֵל, הוּא הֶאֱרִיךְ בַּתְּפִלָּה הַזּוֹ, מִשּׁוּם שֶׁזּוֹ תְּפִלָּה שֶׁעוֹמֶדֶת לְמַעְלָה. וּכְשֶׁסִּדֵּר תְּפִלָּתוֹ בִּקְצָרָה עַל אֲחוֹתוֹ, הוּא לֹא הֶאֱרִיךְ בָּהּ, מִשּׁוּם שֶׁעוֹמֶדֶת לְמַטָּה, שֶׁכָּתוּב (במדבר יב) אֵל נָא רְפָא נָא לָהּ. וְלֹא הֶאֱרִיךְ יוֹתֵר, כִּי הוּא בַּעַל הַבַּיִת וְצִוָּה אֶת בֵּיתוֹ כָּרָאוּי, וּמִשּׁוּם כָּךְ לֹא הֶאֱרִיךְ יוֹתֵר בְּבַקָּשָׁתוֹ. (ועלזהכלם) וְכָל הַסִּדּוּרִים לְהַשְׁרוֹת שְׁכִינָה בָּעוֹלָם, כְּמוֹ שֶׁבֵּאַרְנוּ בְּכָל אוֹתָם (שאר) הֵיכָלוֹת שֶׁאָמַ רְנוּ.</p>\n<p>רַבִּי שִׁמְעוֹן קָם וְאָמַר, אַשְׁרֵי חֶלְקְךְ אָדָם הָרִאשׁוֹן, נִבְחָר מִכָּל הַנִּבְרָאִים שֶׁעוֹמְדִים בָּעוֹלָם, שֶׁהִגְדִּיל אוֹתְךְ הַקָּדוֹשׁ בָּרוּךְ הוּא עַל הַכֹּל וְהִכְנִיס אוֹתְךְ לְגַן עֵדֶן, וְתִקֵּן לְךְ שֶׁבַע חֻפּוֹת שָׁם לְהִשְׁתַּעֲשֵׁעַ בָּעֹנֶג שֶׁל הַנֹּעַם הָעֶלְיוֹן, כְּמוֹ שֶׁנֶּאֱמַר (תהלים כז) לַחֲזוֹת בְּנֹעַם ה' וּלְבַקֵּר בְּהֵיכָלוֹ. לַחֲזוֹת בְּנֹעַם ה' - לְמַעְלָה. וּלְבַקֵּר בְּהֵיכָלוֹ - לְמַטָּה. לַחֲזוֹת בְּנֹעַם ה', בְּאוֹתָם שִׁבְעַת הָרְקִיעִים לְמַעְלָה. וּלְבַקֵּר בְּהֵיכָלוֹ, בְּאוֹתָם שִׁבְעַת הָרְקִיעִים שֶׁלְּמַטָּה, וְאֵלֶּה עוֹמְדִים אֵלֶּה כְּנֶגֶד אֵלֶּה.</p>\n<p>וּבְכֻלָּם עָמַדְתָּ בְּגַן עֵדֶן. אוֹתָן שֶׁבַע הַחֻפּוֹת הָעֶלְיוֹנוֹת הַקְּדוֹשׁוֹת עוֹמְדוֹת עָלֶיךְ לְמַעְלָה לְהִתְעַטֵּר בָּהֶן, וְאוֹתָן שֶׁבַע תַּחְתּוֹנוֹת עָמַדְתָּ בָּהֶן לְהִשְׁתַּעֲשֵׁעַ בָּהֶן, וּבְכֻלָּן הִשְׁלִים אוֹתְךְ אֲדוֹנְךְ לִהְיוֹת שָׁלֵם בַּכֹּל.</p>\n<p>עַד שֶׁנִּדְחוּ רַגְלֶיךְ אַחַר עֲצַת אוֹתוֹ נָחָשׁ הָרָע, וְגֹרַשְׁתָּ מִגַּן עֵדֶן, וְגָרַמְתָּ לְךְ מָוֶת וּלְכָל הָעוֹלָם, מִשּׁוּם שֶׁעָזַבְתָּ אֶת הָעִדּוּנִים הַלָּלוּ שֶׁלְּמַעְלָה וּלְמַטָּה, וְנִמְשַׁכְתָּ אַחַר אוֹתָן תְּשׁוּקוֹת טְמֵאוֹת שֶׁנִּקְרָאוֹת רֹאשׁ פְּתָנִים, שֶׁהַגּוּף מוֹשֵׁךְ בָּהֶן וְלֹא הָרוּחַ, כְּמוֹ שֶׁנֶּאֱמַר (דברים לב) וְרֹאשׁ פְּתָנִים אַכְזָר. וְכָתוּב עֲנָבֵמוֹ עִנְּבֵי רוֹשׁ. עַד שֶׁבָּא אַבְרָהָם הֶחָסִיד וְהִתְחִיל לְתַקֵּן עוֹלָם, וְנִכְנַס לְתוֹךְ הָאֱמוּנָה הַקְּדוֹשָׁה וְתִקֵּן לְמַעְלָה וּלְמַטָּה בְּאוֹתָם רְקִיעִים עֶלְיוֹנִים וּבְאוֹתָם רְקִיעִים תַּחְתּוֹנִים.</p>\n<p>אוֹתָם הַתַּחְתּוֹנִים הֵם הֵיכָלוֹת לְאוֹתָם רְקִיעִים עֶלְיוֹנִים לְהֵאָחֵז זֶה בָּזֶה וּלְהִקָּשֵׁר זֶה בָּזֶה, כְּמוֹ שֶׁבֵּאַרְנוּ בְּאוֹתָם הֵיכָלוֹת שֶׁאָמַרְנוּ. וְאַף עַל גַּב שֶׁבֵּאַרְנוּ שָׁם בְּתוֹךְ הַכְּלָל, כָּאן יֵשׁ לָנוּ לְפָרֵט דְּבָרִים וּלְתַקֵּן אֶת הַיִּחוּד כָּרָאוּי, כְּדֵי שֶׁלֹּא יִטְעוּ הַחֲבֵרִים, וְיֵלְכוּ בְּדֶרֶךְ יְשָׁרָה, כַּכָּתוּב (הושע יד) כִּי יְשָׁרִים דַּרְכֵי ה' וְצַדִּיקִים וְגוֹ'.</p>"],[9522011907,"<p>הַהֵיכָל הָרִאשׁוֹן - רֵאשִׁית תּוֹךְ הָאֱמוּנָה, וְזוֹהִי רֵאשִׁית לְסוֹד הָאֱמוּנָה, וּבַדְּרָגוֹת שֶׁל מַרְאֵה הָאֱמוּנָה. נְבִיאֵי הָאֱמֶת הָיוּ רוֹאִים מִתּוֹךְ הָאַסְפַּקְלַרְיָה הַזּוֹ שֶׁאֵינָהּ מְאִירָה, וּמִשּׁוּם שֶׁזּוֹהִי רֵאשִׁית הָאֱמוּנָה, כָּתוּב (שם א) תְּחִלַּת דִּבֶּר ה' בְּהוֹשֵׁעַ. שֶׁרָאָה מִתּוֹךְ דַּרְגָּה זוֹ, שֶׁהִיא רֵאשִׁית כָּל הַדְּרָגוֹת לַעֲלוֹת לְמַעְלָה, וְסוֹף כָּל הַדְּרָגוֹת לָרֶדֶת לְמַטָּה.</p>\n<p>וּמִשּׁוּם שֶׁהוֹשֵׁעַ רָאָה מִתּוֹךְ הָרֵאשִׁית הַ את, סוֹף כָּל הַדְּרָגוֹת, הִצְטָרֵךְ לִטֹּל אֶת אֵשֶׁת הַזְּנוּנִים הַזֹּאת, מִשּׁוּם שֶׁיִּשְׂרָאֵל נֶאֶחְזוּ וְנִמְשְׁכוּ מִשָּׁם לְמַטָּה לְאוֹתוֹ מָקוֹם שֶׁנִּקְרָא אֵשֶׁת זְנוּנִים, מִשּׁוּם שֶׁעָזְבוּ וְלֹא נִדְבְּקוּ בְּאֵשֶׁת חַיִל הַזּוֹ, וְרָאָה מִשָּׁם כָּל אוֹתָם הֵיכָלוֹת שֶׁהֵם בְּצַד הַטֻּמְאָה (שיש לו).</p>\n<p>הֵיכְלוֹת הַטֻּמְאָה, כֻּלָּם טְמֵאִים לְמִי שֶׁנִּדְבָּק בָּהֶם, וְעַל זֶה כָּתוּב, קַח לְךְ אֵשֶׁת זְנוּנִים וְגוֹ'. וְכִי נְבִיא אֱמֶת צָרִיךְ אֶת זֶה? אֶלָּא מִשּׁוּם שֶׁאָסוּר לוֹ לְאָדָם לְהִכָּנֵס לְאוֹתָם הֵיכָלוֹת, כְּדֵי שֶׁלֹּא יִמָּשֵׁךְ אַחֲרֵיהֶם כְּמוֹ שֶׁעָשָׂה נֹחַ, שֶׁכָּתוּב (בראשית ט) וַיֵּשְׁתְּ מִן הַיַּיִן וַיִּשְׁכָּר וַיִּתְגַּל.</p>\n<p>וְהוֹשֵׁעַ פָּחַד לְהִסְתַּכֵּל בְּאוֹתָם הֵיכָלוֹת שֶׁנִּטְמְאוּ בָהֶם יִשְׂרָאֵל וְנִדְבְּקוּ, שֶׁלֹּא יִמָּשֵׁךְ אַחֲרֵיהֶם, כְּמוֹ שֶׁכָּתוּב בְּנֹחַ, וַיֵּשְׁתְּ מִן הַיַּיִן וַיִּשְׁכָּר וַיִּתְגַּל. עַד שֶׁאָמַר לוֹ, קַח לְךְ אֵשֶׁת זְנוּנִים וְיַלְדֵי זְנוּנִים. וְכָתוּב וַיֵּלֶךְ וַיִּקַּח אֶת גֹּמֶר בַּת דִּבְלָיִם. לָדַעַת בַּמֶּה נִדְבְּקוּ וְנִטְמְאוּ וְעָזְבוּ אֶת סוֹד הָאֱמוּנָה, בִּשְׁבִיל אֵל נֵכָר. וְעַל זֶה רָאָה מִתּוֹךְ הַהֵיכָל הַזֶּה, רֵאשִׁית כָּל הַדְּרָגוֹת.</p>\n<p>הַהֵיכָל הַזֶּה רֵאשִׁית שֶׁל הַכֹּל לַעֲלוֹת בִּדְרָגוֹת. הַהֵיכָל הַזֶּה הוּא מָדוֹר שֶׁעוֹמֵד בְּאוֹר, לְהִתְעַטֵּר בְּדַרְגוֹתָיו, לְהִסְתַּכֵּל בְּאוֹתָן דְּרָגוֹת עֶלְיוֹנוֹת, שֶׁכָּתוּב (שמות כד) וַיִּרְאוּ אֵת אֱלֹהֵי יִשְׂרָאֵל.</p>\n<p>בַּהֵיכָל הַזֶּה מְמֻנֶּה אֶחָד שַׁמָּשׁ, טָהֳרִיאֵ\"ל שְׁמוֹ, וְהוּא עוֹמֵד עַל פֶּתַח אוֹתוֹ הַהֵיכָל. וְכָל הַנְּשָׁמוֹת שֶׁעוֹלוֹת, עוֹמֵד הַמְמֻנֶּה הַזֶּה בַּפֶּתַח הַזֶּה, וְכַמָּה מְמֻנִּים אֲחֵרִים עִמּוֹ, וְכֻלָּם אֵשׁ לוֹהֶטֶת וְשַׁרְבִיטֵי אֵשׁ בִּידֵיהֶם, וְכֻלָּם בַּעֲלֵי עֵינַיִם. הַמְמֻנֶּה הַזֶּה עוֹמֵד בְּצַד זֶה. אִם זוֹכָה הַנְּשָׁמָה הַזּוֹ לְהִכָּנֵס, הַמְמֻנֶּה הַזֶּה פּוֹתֵחַ פֶּתַח וְהִיא נִכְנֶסֶת.</p>\n<p>וְאִם לֹא זוֹכָה, אוֹתוֹ הַמְמֻנֶּה הָאַחֵר שֶׁעוֹמֵד בַּצַּד הָאַחֵר מְזֻמָּן, וְכַמָּה אֶלֶף וּרְבָבוֹת שׁוֹמְרֵי הַחֻקִּים עִמּוֹ. דּוֹחֶה אוֹתָהּ אוֹתוֹ הַמְמֻנֶּה הָאַחֵר הַקָּדוֹשׁ, וְלוֹקֵחַ אוֹתָהּ הָאַחֵר הַזֶּה שֶׁבְּצַד הַטֻּמְאָה, וּמַכְנִיס אוֹתָהּ לְתוֹךְ אוֹתָם הַהֵיכָלוֹת הַטְּמֵאִים, וְכָל אוֹתָם שׁוֹמְרֵי הַחֻקִּים אוֹחֲזִים אוֹתָהּ, עַד שֶׁמּוֹרִידִים אוֹתָהּ לַגֵּיהִנֹּם, וְנִדּוֹנֵית שָׁם שְׁנֵים עָשָׂר חֳדָשִׁים. הַתִּקּוּן שֶׁל אוֹתוֹ הַצַּד הָאַחֵר, בֵּית דִּין לָדוּן בָּהֶם אֶת הָרְשָׁעִים.</p>\n<p>כְּמוֹ כֵן אוֹתוֹ הַמְמֻנֶּה הַקָּדוֹשׁ שֶׁעוֹמֵד עַל אוֹתוֹ פֶּתַח - כָּל אוֹתָן תְּפִלּוֹת שֶׁבּוֹקְעוֹת אֲוִירִים וּרְקִיעִים לְהִכָּנֵס לִפְנֵי הַמֶּלֶךְ, אִם תְּפִלַּת רַבִּים הֵם - הוּא פּוֹתֵחַ פֶּתַח וּמַכְנִיס אוֹתָהּ הַתְּפִלָּה, עַד שֶׁנַּעֲשׂוֹת כָּל תְּפִלּוֹת הָעוֹלָם עֲטָרָה בְּרֹאשׁ צַדִּיק חַי הָעוֹלָמִים, כְּמוֹ שֶׁבֵּאֲרוּהָ.</p>\n<p>וְאִם תְּפִלַּת יָחִיד הִיא - עוֹלָה עַד שֶׁמַּגִּיעָה לְפֶתַח הַהֵיכָל הַזֶּה, שֶׁהַמְמֻנֶּה הַזֶּה עוֹמֵד בּוֹ. אִם נָאָה הִיא הַתְּפִלָּה לְהִכָּנֵס לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ (יפה), מִיָּד פּוֹתֵחַ פֶּתַח וּמַכְנִיס אוֹתָהּ. וְאִם לֹא נָאָה, הוּא דּוֹחֶה אוֹתָהּ הַחוּצָה, וְיוֹרֶדֶת לְשׁוֹטֵט בָּעוֹלָם, וְעוֹמֶדֶת בְּתוֹךְ הָרָקִיעַ הַתַּחְתּוֹן מֵאוֹתָם הָרְקִיעִים שֶׁלְּמַטָּה שֶׁמַּנְהִיגִים תּוֹךְ הָעוֹלָם. וּבְאוֹתוֹ רָקִיעַ עוֹמֵד מְמֻנֶּה אֶחָד שֶׁשְּׁמוֹ סַהֲדִיאֵ\"ל, וּמְמֻנֶּה עַל הָרָקִיעַ הַזֶּה, וְנוֹטֵל אֶת כָּל אוֹתָן הַתְּפִלּוֹת שֶׁנִּדְחוּ, שֶׁנִּקְרָאוֹת תְּפִלּוֹת פְּסוּלוֹת, וְגוֹנֵז אוֹתָן, עַד שֶׁנִּדּוֹן (ששב) אוֹתוֹ אָדָם.</p>\n<p>אִם שָׁב לְרִבּוֹנוֹ כָּרָאוּי וּמִתְפַּלֵּל תְּפִלָּה זַכָּה אַחֶרֶת - אוֹתָהּ תְּפִלָּה זַכָּה כְּשֶׁעוֹלָה, נוֹטֵל אוֹתוֹ הַמְמֻנֶּה סַהֲדִיאֵ\"ל אֶת הַתְּפִלָּה הַזּוֹ, וּמַעֲלֶה אוֹתָהּ לְמַעְלָה, עַד שֶׁפּוֹגֶשֶׁת בְּאוֹתָהּ תְּפִלָּה זַכָּה, וְעוֹלוֹת וּמִתְעָרְבוֹת כְּאֶחָד וְנִכְנָסוֹת לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ.</p>\n<p>וְלִפְעָמִים נִדְחֵית אוֹתָהּ תְּפִלָּה, מִשּׁוּם שֶׁאוֹתוֹ אָדָם נִמְשָׁךְ אַחַר הַצַּד הָאַחֵר, וְהוּא נִטְמָא בְּאוֹתוֹ צַד, וְנוֹטֵל אוֹתָהּ אוֹתוֹ מְמֻנֶּה שֶׁבְּאוֹתוֹ הַצַּד הָאַחֵר הַטָּמֵא. וְאָז עוֹמֵד אוֹתוֹ צַד הָאַחֵר הַטָּמֵא, עוֹלֶה ומַזְכִּיר אֶת חֲטָאֵי אוֹתוֹ הָאָדָם לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וּמַסְטִין עָלָיו לְמַעְלָה. וְלָכֵן כָּל הַתְּפִלּוֹת וְכָל הַנְּשָׁמוֹת, כְּשֶׁעוֹלוֹת, כֻּלָּן עוֹלוֹת וְעוֹמְדוֹת לִפְנֵי הַהֵיכָל הַזֶּה, וְהַמְמֻנֶּה הַזֶּה עוֹמֵד עַל פֶּתַח הַהֵיכָל הַזֶּה לְהַכְנִיס נְשָׁמוֹת וּתְפִלּוֹת, אוֹ לִדְחוֹתָן הַחוּצָה.</p>\n<p>מֵעֵל לַפֶּתַח הַזֶּה יֵשׁ פֶּתַח אַחֵר שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא חוֹתֵר לוֹ, וְנִפְתָּח שָׁלֹשׁ פְּעָמִים בְּיוֹם וְלֹא נִנְעָל, וְעוֹמֵד לְאוֹתָם בַּעֲלֵי תְשׁוּבָה שֶׁשּׁוֹפְכִים דִּמְעָה בִּתְפִלָּתָם לִפְנֵי רִבּוֹנָם. וְכָל הַשְּׁעָרִים וְהַפְּתָחִים נִנְעָלִים, עַד שֶׁנִּכְנָסִים בִּרְשׁוּת, פְּרָט לַשְּׁעָרִים הַלָּלוּ שֶׁנִּקְרָאִים שַׁעֲרֵי דִמְעָה.</p>\n<p>וּכְשֶׁהַתְּפִלָּה הַזּוֹ שֶׁל הַדִּמְעָה עוֹלָה לְמַעְלָה לְהִכָּנֵס בְּאוֹתָם הַשְּׁעָרִים, מִזְדַּמֵּן אוֹתוֹ אוֹפַן שֶׁעוֹמֵד עַל שֵׁשׁ מֵאוֹת חַיּוֹת גְּדוֹלוֹת, שֶׁשְּׁמוֹ רַחֲמִיאֵ\"ל, וְלוֹקֵחַ אוֹתָהּ הַתְּפִלָּה בְּאוֹתָן דְּמָעוֹת, הַתְּפִלָּה נִכְנֶסֶת וְנִקְשֶׁרֶת לְמַעְלָה. וְאוֹתָן דְּמָעוֹת נִשְׁאָרוֹת כָּאן וּרְשׁוּמוֹת בַּפֶּתַח הַזֶּה. וְיֵשׁ דְּמָעוֹת אֲחֵרוֹת, וּרְשׁוּמוֹת תָּמִיד עַל כָּל אוֹתָן מֶרְכָּבוֹת עֶלְיוֹנוֹת שֶׁלֹּא נִמְחוֹת (נראות).</p>\n<p>אֵלֶּה הֵן דְּמָעוֹת שֶׁשָּׁפְכוּ לְמַעְלָה וּלְמַטָּה כְּשֶׁנֶּחֱרַב בֵּית הַמִּקְדָּשׁ, שֶׁכָּתוּב (ישעיה לג) הֵן אֶרְאֶלָּם צָעֲקוּ חֻצָה מַלְאֲכֵי שָׁלוֹם מַר יִבְכָּיוּן. וְאוֹתָן דְּמָעוֹת שֶׁשָּׁפְכוּ עַל צַדִּיקִים וּטְהוֹרִים כְּשֶׁמִּסְתַּלְּקִים מֵהָעוֹלָם. אֶת כֻּלָּן נוֹטְלוֹת אוֹתָן הַמֶּרְכָּבוֹת וּמְעָרְבוֹת אוֹתָן בְּאוֹתָן דְּמָעוֹת שֶׁנִּשְׁפְּכוּ עַל חֻרְבַּן בֵּית הַמִּקְדָּשׁ, וְעַל זֶה כָּתוּב (ישעיה כה) וּמָחָה ה' אֱלֹהִים דִּמְעָה מֵעַל כָּל פָּנִים. מִי הַפָּנִים? אֵלּוּ הַמֶּרְכָּבוֹת הָעֶלְיוֹנוֹת הַקְּדוֹשׁוֹת. וְאַחַר כָּךְ - וְחֶרְפַּת עַמּוֹ יָסִיר מֵעַל כָּל הָאָרֶץ כִּי ה' דִּבֵּר.</p>\n<p>בַּהֵיכָל הַזֶּה יֵשׁ רוּחַ שֶׁנִּקְרֵאת סִטוּטְרִיָּ\"ה, וְזֶהוּ מַרְאֵה הַסַּפִּיר שֶׁנּוֹצֵץ לְכָל עֵבֶר, וְזֶהוּ שֶׁעוֹמֵד לִשְׁנֵי צְדָדִים, וּמֵאֵלּוּ נִפְרָדִים נִיצוֹצוֹת כְּהִתְנוֹצְצוּת הַנֵּר, כְּמוֹ שֶׁבֵּאַרְנוּ בְּכַמָּה צְדָדִים. וְכַמָּה גְוָנִים לוֹהֲטִים מִזֶּה בְּצַד הַיָּמִין.</p>\n<p>כְּשֶׁאוֹתוֹ רָקִיעַ עֶלְיוֹן, הַנָּהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא מֵעֵדֶן מוֹצִיא נְשָׁמוֹת, לְהַכְנִיס לְתוֹךְ הַהֵיכָל הַשְּׁבִיעִי לְמַעְלָה, אוֹתוֹ הֵיכָל שְׁבִיעִי לוֹקֵחַ אוֹתָם. וּכְשֶׁיּוֹצְאוֹת אוֹתָן נְשָׁמוֹת קְדוֹשׁוֹת מִתּוֹךְ אוֹתוֹ הֵיכָל שְׁבִיעִי, יוֹרְדוֹת עַד שֶׁמַּגִּיעוֹת לַהֵיכָל הַזֶּה, וְלוֹקֵחַ אוֹתָם הָרוּחַ הַקָּדוֹשׁ הַזֶּה שֶׁשְּׁמוֹ סִטְּטּוּרִיָּ\"ה, שֶׁהוּא לְיָמִין. וְכָל אוֹתָן נְשָׁמוֹת שֶׁל זְכָרִים שֶׁעֲתִידִים לִפְרֹחַ בְּצַדִּיקִים זְכָרִים, לְיָמִין כֻּלָּן הוּא לוֹקֵחַ אוֹתָן, וּמִתְעַכְּבוֹת שָׁם עַד שֶׁנִּכְלָלוֹת בַּנְּשָׁמוֹת שֶׁל הַנְּקֵבוֹת.</p>\n<p>מֵהָרוּחַ הַזּוֹ יוֹצֵאת רוּחַ אַחֶרֶת לִשְׂמֹאל, שֶׁנִּרְאֵית וְנִגְנֶזֶת וְנִכְלֶלֶת בָּרוּחַ הָרִאשׁוֹנָה הַזּוֹ, וְהֵן אַחַת כְּלוּלוֹת זוֹ בָּזוֹ. וְהָרוּחַ הָאַחֶרֶת הַזּוֹ נִקְרֵאת אַדִּירִיָּ\"ה סָנוּגְיָ\"א סניגיה (סנוגיאסטניה). זוֹהִי רוּחַ לִשְׂמֹאל. וְזוֹ עוֹמֶדֶת. כְּשֶׁתְּשׁוּקַת הַהֵיכָל הַשְּׁבִיעִי לְהִדָּבֵק בְּאוֹתוֹ נָהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא, אוֹתוֹ רָצוֹן שֶׁעוֹלֶה מִמַּטָּה לְמַעְלָה עוֹשֶׂה נְשָׁמוֹת בָּרָצוֹן שֶׁלּוֹ, וְהֵן נְקֵבוֹת.</p>\n<p>וּכְשֶׁהָרָצוֹן שֶׁל אוֹתוֹ נָהָר יוֹרֵד וְנִדְבָּק מִמַּעְלָה לְמַטָּה, עוֹשִׂים נְפָשׁוֹת שֶׁל זְכָרִים. הָרָצוֹן שֶׁלְּמַעְלָה עוֹשֶׂה זְכָרִים, וְהָרָצוֹן שֶׁלְּמַטָּה עוֹשֶׂה נְקֵבוֹת.</p>\n<p>וּכְשֶׁהַנְּשָׁמוֹת הַנְּקֵבוֹת הַלָּלוּ יוֹצְאוֹת מִתּוֹךְ הֵיכָל שְׁבִיעִי, יוֹרְדוֹת (יוצאות) עַד שֶׁמַּגִּיעוֹת לְרוּחַ הַשְּׂמֹאל הַזּוֹ שֶׁנִּקְרֵאת אַדִּירִיָּ\"ה, וְנִקְרֵאת (שמות כד) לִבְנַ\"ת הַסַּפִּי\"ר, כְּמוֹ שֶׁבֵּאַרְנוּ בִּצְדָדִים אֲחֵרִים.</p>\n<p>כֵּיוָן שֶׁהִגִּיעוּ לָרוּחַ הַזּוֹ אוֹתָן נְשָׁמוֹת נְקֵבוֹת, לוֹקַחַת אוֹתָן הָרוּחַ הַזּוֹ וְעוֹמְדוֹת בָּהּ. וְאַחַר כָּךְ נִכְלָלוֹת רוּחַ הַשְּׂמֹאל הַזּוֹ בְּרוּחַ הַיָּמִין הַזּוֹ, וְאָז נַעֲשׂוֹת אוֹתָן הַנְּשָׁמוֹת כְּלוּלוֹת זָכָר וּנְקֵבָה כְּאֶחָד, (מזדוגות) וּפוֹרְחוֹת מֵהַהֵיכָל הַזֶּה, וְנִפְרָדוֹת בִּבְנֵי אָדָם, כְּשֶׁבָּא לְהִתְכַּלֵּל כָּל אַחַת כְּפִי דַרְכָּהּ, וְאַחַר כָּךְ מִזְדַּוְּגוֹת כְּאֶחָד.</p>\n<p>הָרוּחַ הַזּוֹ שֶׁל הַשְּׂמֹאל בְּיָמִין, מַכָּה זוֹ בָּזוֹ לְהִכָּלֵל, וְיוֹצְאִים נִיצוֹצוֹת שֶׁמִּתְפַּשְּׁטִים לְכָל עֵבֶר, וְנַעֲשִׂים אוֹתָם הָאוֹפַנִּים מֵהֶם, מֵאוֹתָם הַנִּיצוֹצוֹת שֶׁיּוֹצְאִים מִתּוֹךְ רוּחַ הַשְּׂמֹאל, שֶׁכָּתוּב בָּהֶם (יחזקאל א) מַרְאֵה הָאוֹפַנִּים וּמַעֲשֵׂיהֶם כְּעֵין תַּרְשִׁישׁ. וְאֵלּוּ הֵם אוֹפַנִּים שֶׁלּוֹהֲטִים בָּאֵשׁ וְעוֹמְדִים בְּשִׁירָה.</p>\n<p>כֵּיוָן שֶׁהִתְבַּשְּׂמוּ רוּחַ בְּרוּחַ וְנִכְלְלוּ כְאֶחָד, אָז יוֹצֵא אוֹר אֶחָד שֶׁעוֹלֶה וְיוֹרֵד, וּמִתְיַשֵּׁב עַל אַרְבַּע שׁוּרוֹת שֶׁל אוֹפַנִּים, וְהִיא חַיָּה אַחַת שֶׁשּׁוֹלֶטֶת עֲלֵיהֶם, וְנִקְרֵאת בָּזָק. הַבָּזָק הַזֶּה מֵאִיר בְּאוֹר שֶׁנּוֹצֵץ תּוֹךְ הַשַּׁלְהֶבֶת, וְשׁוֹלֵט עַל כָּל אוֹתָם הָאוֹפַנִּים.</p>\n<p>וּמִתְפַּשֵּׁט מִמֶּנּוּ רָקִיעַ אֶחָד שֶׁעוֹמֵד עַל שְׁנֵי עַמּוּדִים, וְאוֹתָם שְׁנֵי הָעַמּוּדִים הֵם שְׁנֵי כְרוּבִים, אֶחָד מִצַּד זֶה וְאֶחָד מִצַּד זֶה, וְהָרָקִיעַ הַזֶּה עַל רֹאשָׁם, כְּמוֹ שֶׁכָּתוּב (שם י) וָאֶרְאֶה וְהִנֵּה אֶל הָרָקִיעַ אֲשֶׁר עַל רֹאשׁ הַכְּרֻבִים. וְלֹא הָרָקִיעַ הַזֶּה שֶׁעַל רֹאשׁ הַחַיּוֹת. וְהַבָּזָק הַזֶּה מְמֻנֶּה עָלָיו, וְרוּחַ עֶלְיוֹנָה הַנִּכְלֶלֶת עַל הַכֹּל.</p>\n<p>כָּל אוֹתָן תְּפִלּוֹת שֶׁמַּקְדִּימוֹת טֶרֶם שֶׁסִּיְּמוּ יִשְׂרָאֵל אֶת תְּפִלּוֹתֵיהֶם, מִתְעַכְּבוֹת בָּרָקִיעַ הַזֶּה, וְהַבָּזָק הַזֶּה שֶׁשּׁוֹלֵט עַל הָרָקִיעַ הַזֶּה מְתַקֵּן אוֹתָן, עַד שֶׁבָּא סַנְדַּלְפוֹ\"ן הַמְמֻנֶּה הַגָּדוֹל, רוּחַ עֶלְיוֹנָה שֶׁשּׁוֹלֶטֶת עַל הַכֹּל, וּכְשֶׁיִּשְׂרָאֵל מְסַיְּמִים אֶת כָּל הַתְּפִלּוֹת, הוּא נוֹטֵל אוֹתָם מֵהָרָקִיעַ הַזֶּה, וְעוֹלֶה וְקוֹשֵׁר לָהֶם קְשָׁרִים (וכתרים) לַאֲדוֹנוֹ, כְּמוֹ שֶׁבֵּאֲרוּהָ.</p>\n<p>הַבָּזָק הַזֶּה עוֹמֵד לִמְנוֹת אֶת כָּל אוֹתָן הַתְּפִלּוֹת שֶׁעוֹלוֹת, וְכָל אוֹתָם דִּבְרֵי תוֹרָה שֶׁמִּתְעַטְּרִים בַּלַּיְלָה, כְּשֶׁרוּחַ צָפוֹן מִתְעוֹרֶרֶת וְהַלַּיְלָה נֶחֱלָק, וְכָל מִי שֶׁעוֹמֵד בְּאוֹתָהּ שָׁעָה וְעוֹסֵק בַּתּוֹרָה, כָּל אוֹתָם הַדְּבָרִים עוֹלִים, וְנוֹטֵל אוֹתָם הַבָּזָ\"ק, וּמַנִּיחַ אוֹתָם בָּרָקִיעַ הַזֶּה, עַד שֶׁעוֹלֶה הַיּוֹם.</p>\n<p>וְאַחַר שֶׁעוֹלֶה הַיּוֹם, עוֹלִים אוֹתָם דְּבָרִים וְשׁוֹרִים בַּמָּקוֹם שֶׁל הָרָקִיעַ שֶׁבּוֹ תְלוּיִים כּוֹכָבִים וּמַזָּלוֹת, שֶׁמֶשׁ וּלְבָנָה, וְזֶה נִקְרָא סֵפֶר הַזִּכָּרוֹן, שֶׁכָּתוּב (מלאכי ג) וַיִּכָּתֵב סֵפֶר זִכָּרוֹן לְפָנָיו. לְפָנָיו, מִשּׁוּם שֶׁסֵּפֶר וְזִכָּרוֹן כְּתָב בְּקֶשֶׁר אֶחָד.</p>\n<p>אוֹתָם אַרְבָּעָה גַלְגַּלִּים הֵם נוֹסְעִים עַל שְׁנֵים עָשָׂר עַמּוּדִים. אֵלּוּ הָאַרְבָּעָה: אַהֲנִיאֵ\"ל. קְדוּמִיאֵ\"ל (קדומי\"א מלכיא\"ל) יְאֲהַדוֹנָהִ\"י, יְהֲדוֹנִיָּ\"ה. שֶׁמַּפְתְּחוֹת הַשֵּׁם הַקָּדוֹשׁ בִּידֵיהֶם.</p>\n<p>וְאֵלּוּ הָאַרְבָּעָה הֵם כְּלוּלִים בְּסוֹד הָאוֹתִיּוֹת אֲדנָ\"י, שֶׁסַּנְדַּלְפוֹ\"ן בַּעַל הַמֶּרְכָּבוֹת מִשְׁתַּמֵּשׁ בָּהֶם. אַרְבַּע הָאוֹתִיּוֹת הַלָּלוּ פּוֹרְחוֹת בָּאֲוִיר, שֶׁאוֹתוֹ אֲוִיר כָּלוּל בְּאוֹתִיּוֹת הַשֵּׁם הַקָּדוֹשׁ יְהֹוָ\"ה - יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א. וְאוֹתוֹ הָאֲוִיר כּוֹלֵל אוֹתָם, וְנִכְלְלוּ אֵלֶּה בְּאֵלֶּה, וְאֵלּוּ הָאַרְבָּעָה נוֹטְלִים אוֹתָם בְּסוֹד אוֹתוֹ הַבָּזָק.</p>\n<p>וְאֵלּוּ הָאַרְבָּעָה נִכְנָסִים בְּאַרְבָּעָה, אֵלּוּ בְאֵלּוּ, שֶׁכָּתוּב (שמות לו) מַקְבִּילֹת הַלֻּלָאֹת אַחַת עַל אֶחָת. וַהֲרֵי בֵּאַרְנוּ, וְסוֹד הוּא לְהִכָּלֵל אֵלֶּה בְּאֵלֶּה וּלְשַׁלֵּב אֵלֶּה בְּאֵלֶּה בְּסוֹד אוֹתוֹ הָרוּחַ שֶׁכָּלוּל בְּסוֹד הַשֵּׁם הַקָּדוֹשׁ. שֶׁכָּלוּל שֵׁם זֶה בְּשֵׁם זֶה.</p>\n<p>וְהַסֹל מִתְנַהֲגִים בַּהֵיכָל הַזֶּה וְנוֹסְעִים בְּאוֹתָהּ הָרוּחַ בְּסוֹד הַשֵּׁם הַקָּדוֹשׁ הַשּׁוֹלֵט עַל הַכֹּל. בַּהֵיכָל הַזֶּה הוּא יְאַהֲדוֹנָהִ\"י, כְּלָל שֶׁל שְׁנֵי שֵׁמוֹת, מִתּוֹךְ שֶׁהוּא רוּחַ בְּרוּחַ. וּכְשֶׁשֵּׁם זֶה, שֶׁכָּלוּל בְּסוֹד שֶׁל רוּחַ בְּרוּחַ, וְכָלוּל זֶה בָּזֶה, מֵאִיר זֶה בָּזֶה, אֲזַי הַכֹּל מֵאִיר, וְעוֹלֶה הָאוֹר וְיוֹרֵד כְּאוֹר הַשֶּׁמֶשׁ בְּתוֹךְ הַמַּיִם, וּבֵאַרְנוּ.</p>\n<p>וְאָז (כאשר) נוֹסַעַת הָרוּחַ הַזּוֹ, הַכֹּל נוֹסְעִים בִּשְׁבִילָהּ, שֶׁכָּתוּב (יחזקאל א) אֶל אֲשֶׁר יִהְיֶה שָּׁמָּה הָרוּחַ לָלֶכֶת יֵלֵכוּ לֹא יִסַּבּוּ בְּלֶכְתָּן. וּכְשֶׁרוּחַ זוֹ מְאִירָה בַּשֵּׁם הַזֶּה, אֲזַי נִכְנָסִים כֻּלָּם זֶה בָּזֶה וְנִקְשָׁרִים כֻּלָּם כְּאֶחָד לַעֲלוֹת לְמַעְלָה בְּסוֹד הַשֵּׁם הַקָּדוֹשׁ הַזֶּה.</p>\n<p>בְּאֶמְצַע הַהֵיכָל הַזֶּה עוֹמֵד עַמּוּד אֶחָד הַנָּעוּץ מֵהַהֵיכָל הַזֶּה לַהֵיכָל הַשֵּׁנִי, בָּזֶה עוֹלָה רוּחַ שֶׁלְּמַטָּה אֶל הָרוּחַ שֶׁלְּמַעְלָה, לְהֵאָחֵז רוּחַ בְּרוּחַ, וְכֵן עַד מֵעַל לְכֻלָּן, לִהְיוֹת כֻּלָּן רוּחַ אַחַת, כְּמוֹ שֶׁנֶּאֱמַר וְרוּחַ אֶחָד לָהֶם.</p>\n<p>הָעַמּוּד הַזֶּה שֶׁעוֹמֵד בָּאֶמְצַע, שְׁמוֹ אַדְרָהָנִיאֵ\"ל, וְסוֹדוֹת הַמַּפְתְּחוֹת שֶׁל הַשֵּׁם הַקָּדוֹשׁ בְּיָדוֹ. כְּשֶׁתְּפִלּוֹת עוֹלוֹת וּמַגִּיעוֹת לָעַמּוּד הַזֶּה, אֲזַי כָּל אֵלּוּ שֶׁבַּהֵיכָל הַזֶּה נוֹסְעִים לְתוֹךְ הַהֵיכָל הַשֵּׁנִי, לְהֵאָחֵז זֶה בָּזֶה, לִהְיוֹת הַכֹּל בְּסוֹד אֶחָד, לְהִתְיַחֵד מַעְלָה וּמַטָּה כְּאֶחָד, לִהְיוֹת שֵׁם קָדוֹשׁ שָׁלֵם כָּרָאוּי.</p>"],[9522011908,"<p>היכל עצם השמים הו\"ד הַהֵיכָל הַשֵּׁנִי, הַהֵיכָל הַזֶּה עוֹמֵד תּוֹךְ סוֹד הָאֱמוּנָה לְהֵאָחֵז בַּסּוֹד שֶׁלְּמַעְלָה. הַהֵיכָל הַזֶּה טָמִיר וְגָנוּז יוֹתֵר מִן הָרִאשׁוֹן. וּבַהֵיכָל הַזֶּה יֵשׁ שְׁלֹשָׁה פְתָחִים, וְשַׁמָּשׁ אֶחָד מְמֻנֶּה עֲלֵיהֶם, וּשְׁמוֹ אוּרְפָנִיאֵ\"ל. הַמְמֻנֶּה הַזֶּה שׁוֹלֵט עַל שְׁלֹשֶׁת צִדְדֵי הָעוֹלָם - דָּרוֹם צָפוֹן וּמִזְרָח. דָּרוֹם מִצַּד זֶה, וְצָפוֹן מִצַּד זֶה, וּמִזְרָח בָּאֶמְצַע.</p>\n<p>שְׁלשֶת הַפְּתָחִים הַלָּלוּ לִשְׁלֹשָׁה צְדָדִים אֵלּוּ. שְׁנַיִם סְתוּמִים, וְאֶחָד בָּאֶמְצַע פָּתוּחַ, בְּסוֹד הַכָּתוּב (שמות כד) וּכְעֶצֶם הַשָּׁמַיִם לָטֹהַר. הַמְמֻנֶּה הַזֶּה נִפְקָד וְעוֹמֵד בְּאוֹתוֹ הַפֶּתַח הַפָּתוּחַ, וְתַחַת יָדוֹ שְׁנֵי מְמֻנִּים אֲחֵרִים שֶׁמְּמֻנִּים עַל אוֹתָם הַפְּתָחִים הָאֲחֵרִים הַסְּתוּמִים.</p>\n<p>וְכָל אוֹתָן הַנְּשָׁמוֹת, שֶׁהֵם הֲרוּגֵי בֵּית דִּין, אוֹ אוֹתָם הֲרוּגֵי שְׁאָר הָעַמִּים, כֻּלָּם הִתְמַנּוּ תַּחַת יְדֵיהֶם, וְהַמְמֻנֶּה הַזֶּה שֶׁעֲלֵיהֶם חוֹקֵק אוֹתָם לִדְמֻיּוֹתֵיהֶם בִּלְבוּשָׁיו, שֶׁהֵם אֵשׁ דּוֹלֶקֶת, וּמַעֲלָה אוֹתָם לְמַעְלָה, וּמַרְאָה אוֹתָם לְרִבּוֹנוֹ, וְאָז הוּא נוֹטֵל אוֹתָם וְחוֹקֵק אוֹתָם בְּבִגְדֵי הַמַּלְכוּת שֶׁלּוֹ אֶת אוֹתָם הֲרוּגֵי שְׁאָר הָעַמִּים.</p>\n<p>וְאוֹתָם הֲרוּגֵי בֵּית דִּין מוֹרִיד אוֹתָם הַמְמֻנֶּה הַזֶּה, וּמַכְנִיס אוֹתָם אַחַר אוֹתָם שְׁנֵי הַפְּתָחִים הַסְּתוּמִים שֶׁאוֹתָם שְׁנֵי הַמְמֻנִּים הָאֲחֵרִים עוֹמְדִים עֲלֵיהֶם, וְשָׁם הֵם רוֹאִים אֶת כְּבוֹד כָּל אֵלּוּ שֶׁקִּיְּמוּ תוֹרָה וְשָׁמְרוּ אֶת מִצְווֹתֶיהָ, וְהֵם מִתְבַּיְּשִׁים בְּעַצְמָם וְנִכְוִים מֵהַחֻפָּה שֶׁלָּהֶם, עַד שֶׁהַמְמֻנֶּה הַזֶּה שֶׁעוֹמֵד עֲלֵיהֶם פּוֹתֵחַ לָהֶם אֶת שַׁעַר הַמִּזְרָח, וּמֵאִיר לָהֶם וְנוֹתֵן לָהֶם חַיִּים שֶׁנִּפְתְּחוּ בְּאוֹתוֹ שַׁעַר הַמִּזְרָח. וּבְיַד אוֹתוֹ הַמְמֻנֶּה כּוֹס אַחַת שֶׁל חַיִּים, שֶׁהִיא מְלֵאָה בְאוֹרוֹת. וְזוֹ נִקְרֵאת כּוֹס תַּנְחוּמִים, כּוֹס שֶׁל חַיִּים. (ומאיר ונותן להם חיים) שֶׁהֲרֵי מִשּׁוּם כּוֹס אַחֶרֶת שֶׁשָּׁתוּ בָרִאשׁוֹנָה, זָכוּ לָזֶה.</p>\n<p>כְּמוֹ כֵן יֵשׁ בַּצַּד הָאַחֵר בְּהֵיכַל הַטֻּמְאָה מְמֻנֶּה אַחֵר, וּבְיָדוֹ כּוֹס שֶׁנִּקְרֵאת כּוֹס תַּרְעֵלָה, כּוֹס חֲמָתוֹ. כְּמוֹ שֶׁשָּׁנִינוּ, יֵשׁ יַיִן וְיֵשׁ יַיִן. כָּךְ גַּם יֵשׁ כּוֹס וְיֵשׁ כּוֹס, וְהַכֹּל - זוֹ לְטוֹב וְזוֹ לְרַע. יַיִן לְטוֹב, שֶׁכָּתוּב (תהלים קד) וְיַיִן יְשַׂמַּח לְבַב אֱנוֹשׁ. וְיַיִן לְרַע, שֶׁכָּתוּב (שם עה) וְיַיִן חָמַר מָלֵא מֶסֶךְ וְגוֹ'. כּוֹס לְטוֹב, שֶׁכָּתוּב (שם קטז) כּוֹס יְשׁוּעוֹת אֶשָּׂא. כּוֹס לְרַע, שֶׁכָּתוּב (ישעיה נא) כּוֹס חֲמָתוֹ, כּוֹס הַתַּרְעֵלָה.</p>\n<p>כְּמוֹ שֶׁיֵּשׁ בְּצַד הַקְּדֻשָּׁה הֵיכָלוֹת וּמְמֻנִּים הַכֹּל לְטוֹב, וְרוּחוֹת קְדוֹשׁוֹת וְכָל הַצְּדָדִים הַקְּדוֹשִׁים - כָּךְ גַּם יֵשׁ בְּצַד הַטֻּמְאָה הֵיכָלוֹת וּמְמֻנִּים כֻּלָּם לְרַע, וְרוּחוֹת טְמֵאוֹת מְמֻנּוֹת וְכָל הַצְּדָדִים הַטְּמֵאִים. וְזֶה כְּנֶגֶד זֶה, כְּמוֹ יֵצֶר הַטּוֹב וְיֵצֶר הָרָע, וְהַכֹּל בְּסוֹד אֶחָד.</p>\n<p>הַהֵיכָל הַזֶּה נִקְרָא הֵיכָל זֹהַר, מִשּׁוּם שֶׁיֵּשׁ בּוֹ רוּחַ שֶׁנִּקְרֵאת אוּרְפָנִיאֵ\"ל. וְהִיא זהַר שֶׁלֹּא מִשְׁתַּנֶּה, וְעוֹמֵד בְּאוֹר נִסְתָּר שֶׁמֵּאִיר מִלְמַעְלָה וּבְאוֹר שֶׁמֵּאִיר לְמַטָּה. וּכְשֶׁמַּכֶּה הָאוֹר שֶׁלְּמַטָּה בָּאוֹר הָעֶלְיוֹן, (וכשמאיר אור באור) מְאִירָה הָרוּחַ הַזּוֹ כְּמוֹ מַרְאֵה הָעַיִן, שֶׁכְּשֶׁמִּתְגַּלְגֶּלֶת, אָז מוֹצִיאָה אוֹר שֶׁנּוֹצֵץ וְזוֹהֵר. כָּךְ גַּם בָּרוּחַ הַזּוֹ. וְעַל כָּךְ הַהֵיכָל הַזֶּה נִקְרָא זֹהַר.</p>\n<p>הָרוּחַ הַזּוֹ שֶׁנִּקְרֵאת אוּרְפָנִיאֵ\"ל, זוֹהִי שֶׁמְּאִירָה לַהֵיכָל הַזֶּה, וּמְאִירָה לַהֵיכָל הָרִאשׁוֹן, מִשּׁוּם שֶׁאוֹתָהּ הָרוּחַ שֶׁל הַהֵיכָל הָרִאשׁוֹן מְאִירָה בְּגָלוּי, בְּזוֹ (מזו) הָרוּחַ שֶׁהִיא נִסְתֶּרֶת. זוֹ הָרוּחַ נוֹסַעַת לְמַעְלָה וְנוֹסַעַת לְמַטָּה, בְּסוֹד הַכָּתוּב (שיר השירים ז) חַמּוּקֵי יְרֵכַיִךְ כְּמוֹ חֲלָאִים. וּמַה שֶּׁאָמַר חַמּוּקֵי יְרֵכַיִךְ, מִשּׁוּם שֶׁיֵּשׁ רוּחַ אַחֶרֶת שֶׁיּוֹצֵאת מִמֶּנּוּ לְצַד שְׂמֹאל וְנִקְשֶׁרֶת עִמּוֹ. וְעַל כָּךְ כָּתוּב פַּעֲמַיִם חַמּוּקֵי. וְרוּחַ הַשְּׂמֹאל הַזּוֹ נִקְרֵאת הֲדַרְנִיאֵ\"ל, וְנִכְלָלִים זֶה בָּזֶה, כְּלוּלִים כְּאֶחָד, וְהֵם עֶצֶם הַשָּׁמַיִם, שֶׁכָּלוּל בְּאֵשׁ וּמַיִם.</p>\n<p>כָּתוּב, (יחזקאל א) כְּמַרְאֵה הַקֶּשֶׁת אֲשֶׁר יִהְיֶה בֶעָנָן בְּיוֹם הַגֶּשֶׁם וְגוֹ'. הָרוּחַ הָרִאשׁוֹנָה הַזּוֹ אוּרְפָנִיאֵ\"ל, שֶׁנִּסְתֶּרֶת בֵּין מַעְלָה וּמַטָּה וּמְאִירָה, הִיא כְּעֵין הַחַשְׁמַל. זֶהוּ כְּעֵין הַחַשְׁמַל, וְלִפְעָמִים הוּא חַשְׁמַל. מִשּׁוּם שֶׁמִּמֶּנּוּ קַיָּמִים כָּל אוֹתָם שְׂרָפִים חַיּוֹת אֵשׁ מְדַבְּרוֹת, חַיּוֹת שֶׁעוֹמְדוֹת וְלֹא עוֹמְדוֹת, וְלָכֵן הוּא חַשְׁמַל.</p>\n<p>אוּרְפָנִיאֵ\"ל שֶׁאָמַרְנוּ, בָּזֶה נוֹדָעִים חַיִּים לָעוֹלָם. כְּשֶׁנִּדּוֹן הָעוֹלָם לְטוֹב, אָז מְאִירָה הָרוּחַ הַזּוֹ, וְכָל הַחַיִּים וְכָל הַשִּׂמְחָה נִמְצָאִים, שֶׁהֲרֵי כֵּיוָן שֶׁזְּכוּת יוֹצֵאת, וּמְאִירִים הַדִּינִים, אָז הָרוּחַ הַזּוֹ מְאִירָה. וְסִימָנְךְ - (משלי טז) בְּאוֹר פְּנֵי מֶלֶךְ חַיִּים.</p>\n<p>וּכְשֶׁנִּדּוֹן הָעוֹלָם בְּדִין (באותה זכות), אֲזַי אוֹתוֹ הַצַּד הָאַחֵר הַטָּמֵא שׁוֹלֵט וּמִתְחַזֵּק, (וכשהעולם נדון באותה הזכות, אז הרוח האחרת שולטת ומתחזקת) וְהָרוּחַ הַזּוֹ נִגְנֶזֶת וְנֶחְשֶׁכֶת, וְאָז כָּל הָעוֹלָם עוֹמֵד בְּדִין וְנִדּוֹן. וְהַכֹּל עוֹמֵד בָּרוּחַ הַזּוֹ, וְסִימָנְךְ - (דניאל ה) וְאַרְכֻּבּוֹתָיו נוֹקְשׁוֹת זוֹ לָזוֹ.</p>\n<p>כָּאן עוֹמְדִים כָּל אוֹתָם מַלְבּוּשִׁים שֶׁל נִשְׁמוֹת הַצַּדִּיקִים שֶׁעוֹלוֹת לְהֵרָאוֹת לִפְנֵי רִבּוֹנָם וְלַעֲמֹד לְפָנָיו. וּכְשֶׁנְּשָׁמָה עוֹלָה וּמַגִּיעָה לַהֵיכָל הַזֶּה, אֲזַי מִזְדַּמֵּן מְמֻנֶּה אֶחָד שֶׁנִּפְקָד עַל אוֹתָם לְבוּשִׁים, וּשְׁמוֹ צִדְקִיאֵ\"ל. שֶׁהֲרֵי בִּזְמַן שֶׁאָדָם עוֹשֶׂה אֶת מִצְווֹת הַתּוֹרָה בָּעוֹלָם הַזֶּה - כְּמוֹ שֶׁהוּא מִשְׁתַּדֵּל עַל עַצְמוֹ, כָּךְ נַעֲשֶׂה לוֹ בַּהֵיכָל הַזֶּה לְמַעְלָה מַלְבּוּשׁ לְהִתְלַבֵּשׁ בְּאוֹתוֹ הָעוֹלָם.</p>\n<p>וּכְשֶׁנְּשָׁמָה עוֹלָה, אוֹתוֹ מְמֻנֶּה נוֹטֵל אוֹתוֹ הַלְּבוּשׁ שֶׁלָּהּ וְהוֹלֵךְ עִמָּהּ עַד שֶׁמַּגִּיעָה לִנְהַר דִּינוּר, שֶׁהַנְּשָׁמָה צְרִיכָה לִרְחֹץ וּלְהִתְלַבֵּן שָׁם, וְלִפְעָמִים שֶׁטּוֹבַעַת אוֹתָהּ נְשָׁמָה שָׁם וְנִשְׂרֶפֶת וְלֹא עוֹלָה כָּל הַיּוֹם, עַד הַבֹּקֶר, כְּשֶׁמִּתְעוֹרֶרֶת רוּחַ שֶׁל צַד דָּרוֹם, אָז עוֹמְדוֹת כֻּלָּן וּמִתְחַדְּשׁוֹת וְאוֹמְרוֹת שִׁירָה, וּמְזַמְּרוֹת כְּמוֹ אוֹתָם מַלְאָכִים שֶׁעָבַר שִׁלְטוֹנָם וְנִשְׂרָפִים, וְעוֹמְדִים וּמִתְחַדְּשִׁים כְּמִקֹּדֶם וְאוֹמְרִים שִׁירָה, (והולכיםלהם) כָּךְ גַּם הַנְּשָׁמוֹת הַלָּלוּ.</p>\n<p>וְאִם זוֹכָה הַנְּשָׁמָה הַזּוֹ וְעוֹלָה, הַמְמֻנֶּה הַזֶּה צִדְקִיאֵ\"ל נוֹטֵל אֶת הַנְּשָׁמָה הַזּוֹ, וּמַלְבִּישׁ אוֹתָהּ בְּאוֹתוֹ לְבוּשׁ, וְנִתְתַּקֶּנֶת בּוֹ, וְעוֹלָה לְקָרְבָּן עַל יְדֵי מִיכָאֵל הַכֹּהֵן לַעֲמֹד תָּמִיד כָּל הַיָּמִים לִפְנֵי עַתִּיק הַיָּמִים. אַשְׁרֵי חֶלְקָהּ שֶׁל הַנְּשָׁמָה הַזּוֹ שֶׁעוֹמֶדֶת וְזוֹכָה לָזֶה.</p>\n<p>וּבַכֹּל מִתְמַנֶּה הָרוּחַ הַזֶּה אוּרְפָנִיאֵ\"ל שֶׁאָמַרְנוּ, וְהוּא שׁוֹלֵט עַל הַהֵיכָל הַזֶּה. מִכְּלָל זֶה, כְּשֶׁנִּכְלֶלֶת רוּחַ בְּרוּחַ וּמַכָּה זוֹ בָּזוֹ לְהִכָּלֵל כְּאֶחָד, נִבְרָאִים אוֹתָם שַׁלִּיטִים אֲחֵרִים שֶׁהִתְמַנּוּ עַל הָעוֹלָם, וְאֵלּוּ הֵם שְׂרָפִים שֶׁל שֵׁשׁ כְּנָפַיִם שֶׁמְּקַדְּשִׁים אֶת רִבּוֹנָם שָׁלֹשׁ פְּעָמִים בְּיוֹם, וְאֵלּוּ הֵם שֶׁמְּדַקְדְּקִים עִם הַצַּדִּיקִים, וַאֲפִלּוּ כְּמוֹ נִימָה אַחַת שֶׁל שַׂעֲרָה. וְאֵלֶּה הֵם שֶׁעוֹמְדִים לְהֵעָנֵשׁ בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, וּלְאוֹתָם שֶׁמְּזַלְזְלִים בְּבֶן אָדָם שֶׁלָּמְדוּ מִמֶּנּוּ אֲפִלּוּ דְּבַר תּוֹרָה אֶחָד וְלֹא נוֹהֲגִים בּוֹ כָּבוֹד, וּלְכָל אוֹתָם שֶׁמִּשְׁתַּמְּשִׁים בְּמִי שֶׁקּוֹרְאִים שִׁשָּׁה סִדְרֵי מִשְׁנָה, לְיַחֵד אֶת יִחוּד רִבּוֹנָם.</p>\n<p>כְּשֶׁמִּתְיַשְּׁבוֹת רוּחַ בְּרוּחַ וּמְאִירוֹת כְּאַחַת, מֵאוֹתוֹ הָאוֹר יוֹצֵאת חַיָּה אַחַת שֶׁשּׁוֹלֶטֶת עַל אוֹתָם שְׂרָפִים, וְאַרְבַּע תַּחְתֶּיהָ, שֶׁפְּנֵיהֶם פְּנֵי נֶשֶׁר, הַחַיָּה הַזּוֹ שְׁמָהּ יוֹפִיאֵ\"ל, וְהִיא עוֹמֶדֶת בְּכָל סוֹדוֹת הַחָכְמָה, לְכָל אוֹתָם מַפְתְּחוֹת שֶׁל הַחָכְמָה עוֹמְדִים בָּהּ.</p>\n<p>הַחַיָּה הַזּוֹ עוֹמֶדֶת לִתְבֹּעַ שָׂכָר מֵעִם הַקָּדוֹשׁ בָּרוּךְ הוּא, לָתֵת לְכָל אוֹתָם שֶׁרוֹדְפִים אַחַר בַּעֲלֵי הַחָכְמָה, וַאֲפִלּוּ מִכָּל אָדָם וְלוֹמְדֵי חָכְמָה לָדַעַת אֶת רִבּוֹנָם, וְאוֹתוֹ שָׂכָר שֶׁנּוֹתֵן לִבְנֵי אָדָם שֶׁרוֹדְפִים אַחַר הַחָכְמָה לְהַכִּיר אֶת רִבּוֹנָם.</p>\n<p>שֶׁכְּשֶׁיּוֹצֵא אָדָם מִן הָעוֹלָם הַזֶּה, הַחַיָּה הַזּוֹ יוֹצֵאת עַל אַרְבָּעָה שְׂרָפִים מְעוֹפְפִים וְטָסָה לְפָנָיו, וְלֹא נוֹתֶנֶת לְכָל אוֹתָם שׁוֹמְרֵי הַחֻקִּים שֶׁבַּצַּד הָאַחֵר לִקְרַב אֵלָיו, וְכַמָּה הֵם שְׁלִיחִים שֶׁל שָׁלוֹם סְבִיבוֹ. וְהַשְּׂרָפִים הַלָּלוּ כְּשֶׁנּוֹסְעִים וְנִרְאִים, נִכְנָעִים אוֹתָם שְׂרָפִים נְחָשִׁים שֶׁיּוֹצְאִים מֵאוֹתוֹ נָחָשׁ שֶׁגָּרַם מָוֶת לְכָל הָעוֹלָם.</p>\n<p>הַחַיָּה הַקְּדוֹשָׁה הַזּוֹ עוֹמֶדֶת כְּשֶׁנְּשָׁמָה עוֹלָה וּמַגִּיעָה אֵלֶיהָ, וְאָז שׁוֹאֶלֶת אוֹתָהּ בְּסוֹד הַחָכְמָה שֶׁל אֲדוֹנוֹ, וּכְפִי אוֹתָהּ הַחָכְמָה שֶׁרָדַף אַחֲרֶיהָ וְהִשִּׂיג (בה) - כָּךְ נוֹתְנִים לוֹ שְׂכָרוֹ. וְאִם יָכֹל לְהַשִּׂיג וְלֹא הִשִּׂיג - דּוֹחִים אוֹתוֹ הַחוּצָה, וְלֹא נִכְנֶסֶת, וְעוֹמֶדֶת תַּחַת אוֹתוֹ הַהֵיכָל בְּבוּשָׁה. וּכְשֶׁמְּרִימִים כַּנְפֵיהֶם הַשְּׂרָפִים הַלָּלוּ שֶׁתַּחְתֶּיהָ, אָז כֻּלָּם מַכִּים בְּכַנְפֵיהֶם וְשׂוֹרְפִים אוֹתָהּ, וְנִשְׂרֶפֶת וְלֹא נִשְׂרֶפֶת, וְעוֹמֶדֶת וְלֹא עוֹמֶדֶת, וְכָךְ נִדּוֹנֵית בְּכָל יוֹם, מְאִירָה וְלֹא מְאִירָה.</p>\n<p>וְאַף עַל גַּב שֶׁיֵּשׁ לָהּ מַעֲשִׂים טוֹבִים, מִשּׁוּם שֶׁאֵין שָׂכָר בְּאוֹתוֹ הָעוֹלָם כְּמוֹ אוֹתָם שֶׁמִּשְׁתַּדְּלִים בַּחָכְמָה לְהִסְתַּכֵּל בִּכְבוֹד רִבּוֹנָם, וְאֵין שִׁעוּר לַשָּׂכָר שֶׁל אוֹתָם שֶׁיּוֹדְעִים הַחָכְמָה לְהִסְתַּכֵּל בִּכְבוֹד רִבּוֹנָם. אַשְׁרֵי חֶלְקָם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, שֶׁכָּתוּב (משלי ג) אַשְׁרֵי אָדָם מָצָא חָכְמָה וְאָדָם יָפִיק תְּבוּנָה.</p>\n<p>הָרוּחַ הַזּוֹ שׁוֹלֶטֶת עַל הַכֹּל. הַכֹּל כְּלוּלִים בָּהּ, וְכֻלָּם מִסְתַּכְּלִים אֵלֶיהָ. הַחַיָּה הַזּוֹ שׁוֹלֶטֶת עַל אַרְבַּע אֲחֵרוֹת, וְאַרְבָּעָה גַלְגַּלִּים לְכָל אַחַת וְאַחַת. גַּלְגַּל אֶחָד מִסְתַּכֵּל לְצַד מִזְרָח, וְגַלְגַּל אֶחָד מִסְתַּכֵּל לְצַד צָפוֹן, וְגַלְגַּל אֶחָד מִסְתַּכֵּל לְצַד דָּרוֹם, וְגַלְגַּל אֶחָד מִסְתַּכֵּל לְצַד מַעֲרָב, וְכָל אֶחָד וְאֶחָד בִּשְׁלֹשָׁה עַמּוּדִים. הַגַּלְגַּל שֶׁלְּצַד מִזְרָח שְׁמוֹ חֲנִיאֵ\"ל. הַגַּלְגַּל שֶׁלְּצַד צָפוֹן שְׁמוֹ קַרְשִׁיאֵ\"ל. הַגַּלְגַּל שֶׁלְּצַד דָּרוֹם שְׁמוֹ עַזְרִיאֵ\"ל. הַגַּלְגַּל שֶׁלְּצַד מַעֲרָב שְׁמוֹ עֲנִיאֵ\"ל. וְכָל אוֹתָם שְׁלֹשֶׁת הָעַמּוּדִים שֶׁהֵם לְכָל אֶחָד וְאֶחָד, כֻּלָּם מִסְתַּכְּלִים לָאֶמְצַע, מִשּׁוּם שֶׁהָאֶמְצַע נוֹטֵל אוֹתָם, וְכֻלָּם נוֹסְעִים בִּשְׁבִיל הָאֶמְצַע.</p>\n<p>אֵלּוּ שֶׁעוֹמְדִים בָּאֶמְצַע, כֻּלָּם מְמֻנִּים בַּשִּׁירָה. וְאֵלּוּ שֶׁל הַיָּמִין אוֹמְרִים שִׁירָה, שֶׁעוֹלֶה הָרָצוֹן לְמַעְלָה וְאוֹמְרִים קָדוֹשׁ. וְאֵלּוּ שֶׁל הַשְּׂמֹאל אוֹמְרִים שִׁירָה, וְעוֹלֶה הָרָצוֹן לְמַעְלָה וְאוֹמְרִים בָּרוּךְ. קָדוֹשׁ לְמַעְלָה, וּבָרוּךְ לְמַטָּה. אֵלּוּ שֶׁעוֹמְדִים לְמַעְלָה לְצַד יָמִין, לוֹקְחִים קְדֻשָּׁה וּמִתְחַבְּרִים בִּקְדֻשָּׁה בְּכָל אוֹתָם שֶׁיּוֹדְעִים לְקַדֵּשׁ אֶת רִבּוֹנָם בַּיִּחוּד שֶׁל סוֹד הַחָכְמָה. וְאֵלּוּ שֶׁעוֹמְדִים בִּשְׂמֹאל, נוֹטְלִים קְדֻשָּׁה, וּמִתְחַבְּרִים בְּכָל אוֹתָם שֶׁלֹּא יוֹדְעִים לְקַדֵּשׁ אֶת רִבּוֹנָם כָּרָאוּי. וְכֻלָּם כְּלוּלִים אֵלֶּה בְּאֵלֶּה בְּיִחוּד אֶחָד וְנִקְשָׁרִים זֶה עִם זֶה, עַד שֶׁכֻּלָּם נַעֲשִׂים קֶשֶׁר אֶחָד וְרוּחַ אַחַת, וּמִתְקַשְּׁרִים עִם אוֹתָם שֶׁלְּמַעְלָה לִהְיוֹת הַכֹּל אֶחָד וּלְהִכָּלֵל זֶה עִם זֶה.</p>\n<p>מֵהַמָּקוֹם הַזֶּה יוֹנְקִים כָּל אוֹתָם בַּעֲלֵי הַחָכְמָה שֶׁעוֹמְדִים לָדַעַת בְּמַרְאֶה אוֹ בְּסוֹד הַחֲלוֹם, מִשּׁוּם שֶׁנְּבִיאִים יוֹנְקִים מִלְמַעְלָה, וּבַעֲלֵי הַחֲלוֹם אוֹ הַמַּרְאֶה יוֹנְקִים מִכָּאן. וּכְשֶׁמִּתְחַבֵּר מָקוֹם זֶה בַּמָּקוֹם שֶׁלְּמַעְלָה בְּקֶשֶׁר אֶחָד, אֲזַי הַנְּבִיאִים יוֹנְקִים מִמַּעְלָה וּמִמַּטָּה בְּקֶשֶׁר אֶחָד.</p>\n<p>וּמִשּׁוּם כָּךְ יֵשׁ מָשָׁל בְּדִבְרֵיהֶם, שֶׁאֵין נְבוּאָתָם מְצֻחְצַחַת כָּרָאוּי כְּמוֹ שֶׁהָיָה בְּמֹשֶׁה, שֶׁנְּבוּאָתוֹ הָיְתָה מְצֻחְצַחַת בַּכֹּל. מִשּׁוּם שֶׁאוֹר יוֹצֵא מִלְמַעְלָה מִמָּקוֹם שֶׁכָּל הָאוֹרוֹת יוֹצְאִים מִמֶּנּוּ, וּמַגִּיעַ לְדַרְגָּתוֹ, וּמִשָּׁם הוּא יוֹנֵק אֶת נְבוּאָתוֹ וּמֵאִיר מַה שֶּׁלֹּא הָיָה אָז לְכֻלָּם, לְכָל שְׁאָר הַנְּבִיאִים. אוֹתָם בַּעֲלֵי הַחֲלוֹם, בַּעֲלֵי הַמַּרְאֶה, כֻּלָּם יוֹנְקִים מִמָּקוֹם זֶה לְמַטָּה בְּלִי חִבּוּר שֶׁל מַעְלָה עַל יְדֵי דַרְגָּה אַחֶרֶת תַּחְתּוֹנָה מִמֶּנָּה, שֶׁהִיא בַּחוּץ.</p>\n<p>כְּמוֹ שֶׁדַּרְגָּה שֶׁל הַנְּבִיאִים שֶׁלְּמַעְלָה, לֹא הָיוּ רוֹאִים אוֹתָהּ הַנְּבִיאִים, רַק עַל יְדֵי דַרְגָּה אַחֶרֶת לְמַטָּה. כָּךְ גַּם אֵלּוּ, דַּרְגַּת הַיְנִיקָה שֶׁלָּהֶם הִיא לְמַעְלָה בַּדַּרְגָּה הַתַּחְתּוֹנָה הַזּוֹ, אֲבָל לֹא נִגְלְתָה לָהֶם אֶלָּא עַל יְדֵי דַרְגָּה חִיצוֹנִית אַחֶרֶת, שֶׁהִיא תַּחְתּוֹנָה מִמֶּנָּה, מִשּׁוּם שֶׁיּוֹצֵאת מֵהַהֵיכָל הַזֶּה, וּמַגִּיעַ הַדָּבָר עַד אוֹתוֹ מְמֻנֶּה שֶׁעוֹמֵד עַל שַׁעַר הַהֵיכָל הַזֶּה, וּמִשָּׁם לְאוֹתוֹ מְמֻנֶּה שֶׁתַּחַת יָדוֹ, וְכֵן עַד (כלם), שֶׁכַּמָּה הֵם שֶׁנּוֹטְלִים אֶת אוֹתוֹ הַדָּבָר וּמִתְעָרְבִים עִמּוֹ. וְלָכֵן, כְּשֶׁמַּגִּיעַ הַדָּבָר לָאָדָם, כַּמָּה הֵם שֶׁמִּתְעָרְבִים עִמּוֹ, וְלָכֵן הַדָּבָר לֹא מְצֻחְצָח כָּרָאוּי.</p>\n<p>כְּשֶׁמִּתְחַבְּרִים אַרְבַּעַת הַגַּלְגַּלִּים הַלָּלוּ בְּאוֹתָם הָאַרְבָּעָה שֶׁבָּאֶמְצַע, אֲזַי כֻּלָּם נִקְרָאִים חֲמוּדוֹת. וְהֵם בַּעֲלֵי הַמַּרְאֶה. וּמִשּׁוּם כָּךְ הַחַיָּה הַזּוֹ שֶׁאָמַרְנוּ שׁוֹלֶטֶת עֲלֵיהֶם, וּמִשּׁוּם כָּךְ נִקְרָא דָּנִיֵּאל אִישׁ חֲמוּדוֹת, שֶׁכָּתוּב (דניאל ט) כִּי חֲמוּדוֹת אָתָּה. וְהַכֹּל סוֹד כָּרָאוּי. אַשְׁרֵי אוֹתָם הַיּוֹדְעִים אֶת סוֹדוֹת רִבּוֹנָם לָלֶכֶת בְּדֶרֶךְ הָאֱמֶת בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>"]]});
